INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(1, 0, 'product/category', '&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ДИЗАЙН */\r\n    html, body, #product-category, #content, .container, .row, header, footer, nav {\r\n        background-color: #0a0a0a !important;\r\n        color: #ffffff !important;\r\n        border: none !important;\r\n    }\r\n\r\n    header, footer, .breadcrumb {\r\n        border-bottom: 1px solid #1a1a1a !important;\r\n        border-top: 1px solid #1a1a1a !important;\r\n    }\r\n\r\n    /* 2. ШАПКА КАТЕГОРИИ */\r\n    .cat-header {\r\n        border-left: 5px solid #ff0000;\r\n        background: linear-gradient(90deg, #1a1a1a 0%, #0a0a0a 100%);\r\n        padding: 15px 25px;\r\n        margin: 20px 0;\r\n        display: flex;\r\n        align-items: center;\r\n        box-shadow: inset 0 0 20px rgba(0,0,0,0.5);\r\n    }\r\n\r\n    .cat-header h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 1.3rem !important;\r\n        color: #fff !important;\r\n        text-transform: uppercase;\r\n        letter-spacing: 3px;\r\n        margin: 0;\r\n    }\r\n\r\n    /* 3. КАРТОЧКИ ТОВАРОВ */\r\n    .grid-container {\r\n        display: grid;\r\n        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\r\n        gap: 25px;\r\n        margin-top: 40px;\r\n    }\r\n\r\n    .card-item {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        transition: 0.4s cubic-bezier(0.25, 0.46, 0.45, 0.94);\r\n        display: flex;\r\n        flex-direction: column;\r\n        position: relative;\r\n        overflow: hidden;\r\n    }\r\n\r\n    .card-item:hover {\r\n        border-color: #ff0000;\r\n        box-shadow: 0 0 25px rgba(255, 0, 0, 0.2);\r\n        transform: translateY(-5px);\r\n    }\r\n\r\n    .card-top-actions {\r\n        position: absolute;\r\n        top: 10px;\r\n        right: 10px;\r\n        display: flex;\r\n        flex-direction: column;\r\n        gap: 8px;\r\n        z-index: 10;\r\n        opacity: 0;\r\n        transform: translateX(20px);\r\n        transition: 0.3s ease;\r\n    }\r\n\r\n    .card-item:hover .card-top-actions {\r\n        opacity: 1;\r\n        transform: translateX(0);\r\n    }\r\n\r\n    .action-btn {\r\n        width: 35px;\r\n        height: 35px;\r\n        background: rgba(0, 0, 0, 0.8);\r\n        border: 1px solid #333;\r\n        color: #fff;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        cursor: pointer;\r\n        transition: 0.3s;\r\n        font-size: 14px;\r\n    }\r\n\r\n    .action-btn:hover { background: #ff0000; border-color: #ff0000; color: #000; }\r\n\r\n    .card-img-wrap {\r\n        height: 240px;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        background: #000;\r\n        overflow: hidden;\r\n        padding: 15px;\r\n        border-bottom: 1px solid #1a1a1a;\r\n    }\r\n\r\n    .card-img-wrap img {\r\n        max-width: 90%;\r\n        max-height: 90%;\r\n        object-fit: contain;\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .card-item:hover .card-img-wrap img {\r\n        transform: scale(1.1);\r\n        filter: drop-shadow(0 0 10px rgba(255, 0, 0, 0.4));\r\n    }\r\n\r\n    .card-body {\r\n        padding: 20px;\r\n        flex-grow: 1;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: space-between;\r\n    }\r\n\r\n    .card-title {\r\n        color: #fff !important;\r\n        text-align: center;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 13px;\r\n        text-transform: uppercase;\r\n        text-decoration: none !important;\r\n        margin-bottom: 15px;\r\n        display: -webkit-box;\r\n        -webkit-line-clamp: 2;\r\n        -webkit-box-orient: vertical;\r\n        overflow: hidden;\r\n        height: 36px;\r\n    }\r\n\r\n    .price-tag {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        color: #ff0000;\r\n        font-size: 1.6rem;\r\n        font-weight: 900;\r\n        text-align: center;\r\n        margin-top: auto;\r\n    }\r\n\r\n    .btn-order {\r\n        background: #1a1a1a;\r\n        color: #fff !important;\r\n        text-align: center;\r\n        padding: 16px;\r\n        font-weight: 900;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-decoration: none !important;\r\n        cursor: pointer;\r\n        transition: 0.3s;\r\n        border: none;\r\n        border-top: 1px solid #222;\r\n        letter-spacing: 2px;\r\n    }\r\n\r\n    .card-item:hover .btn-order { background: #ff0000; color: #000 !important; }\r\n\r\n    .btn-order-text::after { content: &quot;ORDER&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .btn-order-text::after { content: &quot;ZAMÓW&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .btn-order-text::after { content: &quot;ЗАМОВИТИ&quot;; }\r\n\r\n	/* Стиль для активного сердечка */\r\n    .action-btn.active {\r\n        background: #ff0000 !important;\r\n        border-color: #ff0000 !important;\r\n        color: #000 !important;\r\n    }\r\n\r\n    .action-btn.active i {\r\n        font-weight: 900; /* Делаем иконку закрашенной (FontAwesome Solid) */\r\n    }\r\n\r\n    /* Убираем кнопку сравнения из сетки, если она там была прописана жестко */\r\n    .btn-compare-garage { display: none !important; }\r\n\r\n    /* 4. УВЕДОМЛЕНИЯ GARAGE */\r\n    .garage-toast {\r\n        position: fixed;\r\n        bottom: 30px;\r\n        right: 30px;\r\n        width: 320px;\r\n        background: #000;\r\n        border: 2px solid #ff0000;\r\n        box-shadow: 0 0 20px rgba(255, 0, 0, 0.4);\r\n        z-index: 10000;\r\n        font-family: \'Orbitron\', sans-serif;\r\n    }\r\n\r\n    .toast-header {\r\n        background: #1a1a1a;\r\n        padding: 10px 15px;\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n        border-bottom: 1px solid #333;\r\n    }\r\n\r\n    .toast-title { color: #ff0000; font-weight: 900; font-size: 14px; letter-spacing: 1px; }\r\n    .toast-close { color: #fff; cursor: pointer; font-size: 20px; line-height: 1; }\r\n    .toast-body { padding: 20px; color: #fff; }\r\n    .toast-body p { margin-bottom: 15px; font-size: 12px; line-height: 1.4; }\r\n    .toast-link {\r\n        color: #000; background: #ff0000; text-decoration: none;\r\n        padding: 8px 15px; display: inline-block; font-weight: 900; font-size: 11px; transition: 0.3s;\r\n    }\r\n    .toast-link:hover { background: #fff; }\r\n    .toast-progress { height: 3px; background: #ff0000; width: 100%; animation: toastProgress 5s linear forwards; }\r\n    @keyframes toastProgress { from { width: 100%; } to { width: 0%; } }\r\n    \r\n    .garage-toast {\r\n        position: fixed;\r\n        bottom: 30px;\r\n        right: 30px;\r\n        width: 350px;\r\n        background: rgba(10, 10, 10, 0.95);\r\n        border: 1px solid #ff0000;\r\n        backdrop-filter: blur(10px);\r\n        z-index: 10000;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        box-shadow: 0 15px 35px rgba(0, 0, 0, 0.8);\r\n    }\r\n\r\n    .toast-header {\r\n        padding: 12px 20px;\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n        border-bottom: 1px solid rgba(255, 255, 255, 0.05);\r\n    }\r\n\r\n    .toast-title {\r\n        color: #ff0000;\r\n        font-weight: 700;\r\n        font-size: 11px;\r\n        letter-spacing: 2px;\r\n    }\r\n\r\n    .toast-body {\r\n        padding: 20px;\r\n    }\r\n\r\n    .toast-body p {\r\n        color: #ccc;\r\n        font-size: 12px;\r\n        line-height: 1.6;\r\n        margin-bottom: 15px;\r\n        font-family: \'Inter\', sans-serif; /* Для лучшей читаемости текста */\r\n        text-transform: none; /* Текст сообщения не капсом — так аккуратнее */\r\n    }\r\n\r\n    .toast-link {\r\n        color: #fff;\r\n        text-decoration: none;\r\n        font-size: 10px;\r\n        font-weight: 900;\r\n        letter-spacing: 1px;\r\n        padding: 8px 16px;\r\n        border: 1px solid #ff0000;\r\n        transition: 0.3s;\r\n        display: inline-block;\r\n    }\r\n\r\n    .toast-link:hover {\r\n        background: #ff0000;\r\n        color: #000;\r\n    }\r\n\r\n    .toast-progress {\r\n        height: 2px;\r\n        background: #ff0000;\r\n        width: 100%;\r\n        animation: toastProgress 5s linear forwards;\r\n    }\r\n&lt;/style&gt;\r\n\r\n{{ header }}\r\n\r\n&lt;div id=&quot;product-category&quot; class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        &lt;div id=&quot;content&quot; class=&quot;col-sm-12&quot;&gt;\r\n            &lt;div class=&quot;cat-header&quot;&gt;\r\n                &lt;h1&gt;{{ heading_title }}&lt;/h1&gt;\r\n            &lt;/div&gt;\r\n\r\n            {% if categories %}\r\n                    &lt;link href=&quot;https://fonts.googleapis.com/css2?family=Rajdhani:wght@600;700;800&amp;family=Inter:wght@400;500;600&amp;display=swap&quot; rel=&quot;stylesheet&quot;&gt;\r\n                    &lt;link rel=&quot;stylesheet&quot; href=&quot;https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css&quot;&gt;\r\n\r\n                    &lt;div class=&quot;workshop-interface&quot;&gt;\r\n                        &lt;div class=&quot;interface-container&quot;&gt;\r\n\r\n                            &lt;div class=&quot;hud-header style-1&quot;&gt;\r\n                                &lt;div&gt;\r\n                                    &lt;div class=&quot;hud-title&quot;&gt;\r\n                                        {% if heading_title == &quot;Послуги автосервісу&quot; %}\r\n                                           &lt;span class=&quot;text-red&quot;&gt; ОБЕРИ ТЕ, ЩО ТУРБУЄ ТВОЮ АВТІВКУ&lt;/span&gt;\r\n                                        {% else %}\r\n                                            {{ heading_title }}\r\n                                        {% endif %}\r\n                                        &lt;span class=&quot;blink&quot;&gt;● LIVE&lt;/span&gt;\r\n                                    &lt;/div&gt;\r\n                                    &lt;div class=&quot;hud-subtitle&quot;&gt;{% if heading_title == &quot;Послуги автосервісу&quot; %}Інтерактивна карта нашого автосервісу{% else %}Виберіть розділ на планшеті{% endif %}&lt;/div&gt;\r\n                                &lt;/div&gt;\r\n                            &lt;/div&gt;\r\n\r\n                            &lt;div class=&quot;device-stage&quot;&gt;\r\n                                &lt;div class=&quot;launch-pro3-body&quot;&gt;\r\n                                    &lt;div class=&quot;camera-hole&quot;&gt;&lt;/div&gt;\r\n                                    &lt;div class=&quot;sensor-hole&quot;&gt;&lt;/div&gt;\r\n                                    &lt;div class=&quot;armor-grip left&quot;&gt;&lt;/div&gt;\r\n                                    &lt;div class=&quot;armor-grip right&quot;&gt;&lt;/div&gt;\r\n                                    &lt;div class=&quot;device-bezel&quot;&gt;\r\n                                        &lt;div class=&quot;device-screen&quot;&gt;\r\n                                            &lt;div class=&quot;glass-reflection&quot;&gt;&lt;/div&gt;\r\n\r\n                                            {% if heading_title == &quot;Послуги автосервісу&quot; %}\r\n                                                &lt;div class=&quot;screen-content map-view&quot;&gt;\r\n                                                    &lt;img src=&quot;https://i.imgur.com/ImIDx2z.jpeg&quot; class=&quot;bg-image&quot; alt=&quot;Схема СТО&quot;&gt;\r\n                                                    &lt;div class=&quot;markers-overlay&quot;&gt;\r\n                                                        {% for category in categories %}\r\n                                                            {% set zone_style = \'display: none;\' %}{% set zone_icon = \'+\' %}\r\n                                                            {% if \'Шиномонт\' in category.name %}{% set zone_style = \'top: 68%; left: 21%;\' %}{% set zone_icon = \'◎\' %}\r\n                                                            {% elseif \'Підійм\' in category.name %}{% set zone_style = \'top: 40%; left: 48%;\' %}{% set zone_icon = \'⬆\' %}\r\n                                                            {% elseif \'Діагност\' in category.name %}{% set zone_style = \'top: 70%; left: 48%;\' %}{% set zone_icon = \'⚡\' %}\r\n                                                            {% elseif \'розвал\' in category.name %}{% set zone_style = \'top: 78%; left: 62%;\' %}{% set zone_icon = \'⌖\' %}\r\n                                                            {% elseif \'Компресор\' in category.name %}{% set zone_style = \'top: 42%; left: 28%;\' %}{% set zone_icon = \'♨\' %}\r\n                                                            {% elseif \'Кліма\' in category.name %}{% set zone_style = \'top: 62%; left: 40%;\' %}{% set zone_icon = \'❄\' %}\r\n                                                            {% elseif \'Візки\' in category.name or \'меблі\' in category.name %}{% set zone_style = \'top: 50%; left: 18%;\' %}{% set zone_icon = \'▤\' %}\r\n                                                            {% elseif \'Гаражне\' in category.name %}{% set zone_style = \'top: 53%; left: 7%;\' %}{% set zone_icon = \'⚒\' %}\r\n                                                            {% endif %}\r\n                                                            &lt;div class=&quot;marker-point&quot; style=&quot;{{ zone_style }}&quot; data-link=&quot;sync-item-{{ loop.index }}&quot; onclick=&quot;location.href=\'{{ category.href }}\'&quot;&gt;\r\n                                                                &lt;div class=&quot;marker-pulse-ring&quot;&gt;&lt;/div&gt;\r\n                                                                &lt;div class=&quot;marker-center&quot;&gt;{{ zone_icon }}&lt;/div&gt;\r\n                                                                &lt;div class=&quot;marker-popover&quot;&gt;\r\n                                                                    &lt;span class=&quot;mp-title&quot;&gt;{{ category.name }}&lt;/span&gt;\r\n                                                                    &lt;span class=&quot;mp-action&quot;&gt;ПЕРЕЙТИ &amp;rarr;&lt;/span&gt;\r\n                                                                &lt;/div&gt;\r\n                                                            &lt;/div&gt;\r\n                                                        {% endfor %}\r\n                                                    &lt;/div&gt;\r\n                                                &lt;/div&gt;\r\n                                            {% else %}\r\n                                                &lt;div class=&quot;screen-content tiles-view&quot;&gt;\r\n                                                    &lt;div class=&quot;tablet-nav-bar&quot;&gt;\r\n                                                        &lt;button class=&quot;t-back&quot; onclick=&quot;history.back()&quot;&gt;&lt;i class=&quot;fas fa-chevron-left&quot;&gt;&lt;/i&gt; Назад&lt;/button&gt;\r\n                                                        &lt;div class=&quot;t-path&quot;&gt;Головна / Послуги автосервісу / {{ heading_title }}&lt;/div&gt;\r\n                                                    &lt;/div&gt;\r\n                                                    &lt;div class=&quot;tiles-scroll-area&quot;&gt;\r\n                                                        &lt;div class=&quot;tiles-grid&quot;&gt;\r\n                                                            {% for category in categories %}\r\n                                                                &lt;a href=&quot;{{ category.href }}&quot; class=&quot;tile-card&quot;&gt;\r\n                                                                    &lt;div class=&quot;tile-img&quot;&gt;\r\n                                                                        &lt;img src=&quot;{{ category.image ? category.image : \'image/no_image.png\' }}&quot; alt=&quot;{{ category.name }}&quot;&gt;\r\n                                                                    &lt;/div&gt;\r\n                                                                    &lt;div class=&quot;tile-label&quot;&gt;{{ category.name }}&lt;/div&gt;\r\n                                                                &lt;/a&gt;\r\n                                                            {% endfor %}\r\n                                                        &lt;/div&gt;\r\n                                                    &lt;/div&gt;\r\n                                                &lt;/div&gt;\r\n                                            {% endif %}\r\n\r\n                                            &lt;div class=&quot;ui-grid-overlay&quot;&gt;&lt;/div&gt;\r\n                                        &lt;/div&gt;\r\n                                        &lt;div class=&quot;launch-chrome-logo&quot;&gt;LAUNCH&lt;/div&gt;\r\n                                    &lt;/div&gt;\r\n                                &lt;/div&gt;\r\n                                &lt;div class=&quot;device-shadow&quot;&gt;&lt;/div&gt;\r\n                            &lt;/div&gt;\r\n\r\n                            {% if heading_title == &quot;Обладнання для автосервісу&quot; %}\r\n                                &lt;div class=&quot;bottom-cats-wrapper&quot;&gt;\r\n                                    &lt;button class=&quot;scroll-arrow scroll-left&quot; id=&quot;scroll-left&quot;&gt;&lt;i class=&quot;fas fa-chevron-left&quot;&gt;&lt;/i&gt;&lt;/button&gt;\r\n                                    &lt;div class=&quot;bottom-cats&quot; id=&quot;bottom-cats-container&quot;&gt;\r\n                                        {% for category in categories %}\r\n                                            &lt;a href=&quot;{{ category.href }}&quot; class=&quot;b-cat-card&quot; id=&quot;sync-item-{{ loop.index }}&quot; data-target=&quot;sync-item-{{ loop.index }}&quot;&gt;\r\n                                                &lt;div class=&quot;cat-img-wrap&quot;&gt;\r\n                                                    &lt;img src=&quot;{{ category.image ? category.image : \'image/no_image.png\' }}&quot; alt=&quot;{{ category.name }}&quot;&gt;\r\n                                                &lt;/div&gt;\r\n                                                &lt;div class=&quot;cat-info&quot;&gt;\r\n                                                    &lt;span class=&quot;cat-name&quot;&gt;{{ category.name }}&lt;/span&gt;\r\n                                                    &lt;span class=&quot;cat-arrow&quot;&gt;Перейти &amp;rarr;&lt;/span&gt;\r\n                                                &lt;/div&gt;\r\n                                            &lt;/a&gt;\r\n                                        {% endfor %}\r\n                                    &lt;/div&gt;\r\n                                    &lt;button class=&quot;scroll-arrow scroll-right&quot; id=&quot;scroll-right&quot;&gt;&lt;i class=&quot;fas fa-chevron-right&quot;&gt;&lt;/i&gt;&lt;/button&gt;\r\n                                &lt;/div&gt;\r\n                            {% endif %}\r\n\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;style&gt;\r\n                    /* === КОРПУС ПЛАНШЕТА (БАЗА) === */\r\n                    .workshop-interface { background: #0a0a0a; padding: 40px 0; font-family: \'Inter\', sans-serif; }\r\n                    .interface-container { max-width: 1400px; margin: 0 auto; padding: 0 20px; }\r\n                    .device-stage { perspective: 2000px; display: flex; flex-direction: column; align-items: center; margin-bottom: 30px; }\r\n                    .launch-pro3-body {\r\n                        position: relative; width: 100%; max-width: 1000px; background: #c01313; /* Фирменный красный */\r\n                        border-radius: 40px; padding: 12px; box-shadow: inset 0 2px 4px rgba(252, 3, 3,0.3), 0 20px 40px rgba(0,0,0,0.2);\r\n                    }\r\n                    .armor-grip { position: absolute; top: 60px; bottom: 60px; width: 15px; background: #a01010; }\r\n                    .armor-grip.left { left: 0; border-radius: 0 10px 10px 0; }\r\n                    .armor-grip.right { right: 0; border-radius: 10px 0 0 10px; }\r\n                    .device-bezel { background: #080a0f; border-radius: 30px; padding: 25px 25px 50px 25px; position: relative; border: 2px solid #1a1d24; }\r\n                    .device-screen { position: relative; width: 100%; border-radius: 4px; overflow: hidden; background: #000; height: 580px; }\r\n                    .launch-chrome-logo { position: absolute; bottom: 12px; left: 50%; transform: translateX(-50%); font-family: \'Rajdhani\', sans-serif; font-weight: 800; font-size: 24px; color: #4a4e5a; letter-spacing: 4px; }\r\n\r\n                    /* === ЭКРАН: ПОДКАТЕГОРИИ (ПЛИТКА) === */\r\n                    .tiles-view { display: flex; flex-direction: column; height: 100%; background: #000; }\r\n                    .tablet-nav-bar { background: #11141b; padding: 15px 20px; display: flex; align-items: center; border-bottom: 1px solid #222; }\r\n                    .t-back { background: #c01313; color: #fff; border: none; padding: 8px 16px; border-radius: 4px; cursor: pointer; font-weight: 600; font-size: 13px; margin-right: 20px; }\r\n                    .t-path { color: #888; font-size: 12px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }\r\n                    .tiles-scroll-area { flex-grow: 1; overflow-y: auto; padding: 30px; }\r\n                    .tiles-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(160px, 1fr)); gap: 25px; }\r\n                    .tile-card { background: #11141b; border-radius: 12px; padding: 20px; text-decoration: none; transition: 0.3s; display: flex; flex-direction: column; align-items: center; border: 1px solid #222; }\r\n                    .tile-card:hover { border-color: #c01313; transform: translateY(-5px); background: #161a23; }\r\n                    .tile-img { width: 100px; height: 100px; background: #fff; border-radius: 8px; display: flex; align-items: center; justify-content: center; padding: 10px; margin-bottom: 15px; }\r\n                    .tile-img img { max-width: 100%; max-height: 100%; object-fit: contain; }\r\n                    .tile-label { color: #fff; font-size: 14px; text-align: center; font-weight: 500; line-height: 1.2; }\r\n                    .tiles-scroll-area::-webkit-scrollbar { width: 5px; }\r\n                    .tiles-scroll-area::-webkit-scrollbar-thumb { background: #c01313; border-radius: 10px; }\r\n\r\n                    /* === ЭКРАН: ГЛАВНАЯ (МАРКЕРЫ) === */\r\n                    .bg-image { width: 100%; height: 100%; object-fit: cover; }\r\n                    .marker-point { position: absolute; cursor: pointer; z-index: 10; }\r\n                    .marker-center { width: 30px; height: 30px; background: #c01313; border: 2px solid #fff; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 16px; font-weight: bold; }\r\n                    .marker-pulse-ring { position: absolute; width: 50px; height: 50px; left: -10px; top: -10px; border: 2px solid #c01313; border-radius: 50%; animation: p-pulse 2s infinite; }\r\n                    @keyframes p-pulse { 0% {transform: scale(0.6); opacity: 1;} 100% {transform: scale(1.4); opacity: 0;} }\r\n                    .marker-popover { position: absolute; bottom: 40px; left: 50%; transform: translateX(-50%); background: #fff; padding: 10px 15px; border-radius: 6px; white-space: nowrap; opacity: 0; visibility: hidden; transition: 0.3s; box-shadow: 0 10px 20px rgba(0,0,0,0.3); }\r\n                    .marker-point:hover .marker-popover { opacity: 1; visibility: visible; }\r\n                    .mp-title { display: block; color: #000; font-size: 13px; font-weight: 700; margin-bottom: 2px; }\r\n                    .mp-action { color: #c01313; font-size: 11px; font-weight: 800; }\r\n\r\n                    /* === НИЖНИЙ СПИСОК КАРТОЧЕК === */\r\n                    .bottom-cats-wrapper { position: relative; display: flex; align-items: center; padding: 0 40px; }\r\n                    .bottom-cats { display: flex; gap: 20px; overflow-x: auto; scroll-behavior: smooth; padding: 10px 5px 30px; scrollbar-width: none; }\r\n                    .bottom-cats::-webkit-scrollbar { display: none; }\r\n                    .b-cat-card { flex: 0 0 220px; background: #fff; border: 1px solid #eee; border-radius: 12px; text-decoration: none; transition: 0.3s; overflow: hidden; box-shadow: 0 4px 6px rgba(0,0,0,0.02); }\r\n                    .b-cat-card:hover, .b-cat-card.active-card-sync { border-color: #c01313; transform: translateY(-5px); box-shadow: 0 10px 20px rgba(0,0,0,0.08); }\r\n                    .cat-img-wrap { height: 140px; display: flex; align-items: center; justify-content: center; padding: 15px; border-bottom: 1px solid #f9f9f9; }\r\n                    .cat-img-wrap img { max-width: 100%; max-height: 100%; object-fit: contain; }\r\n                    .cat-info { padding: 15px; }\r\n                    .cat-name { display: block; font-size: 14px; font-weight: 700; color: #333; margin-bottom: 5px; height: 34px; overflow: hidden; }\r\n                    .cat-arrow { color: #c01313; font-size: 11px; font-weight: 700; text-transform: uppercase; }\r\n\r\n                    /* ДЕКОР И СТРЕЛКИ */\r\n                    .scroll-arrow { width: 44px; height: 44px; border-radius: 50%; background: #fff; border: 1px solid #ddd; color: #333; position: absolute; z-index: 10; cursor: pointer; transition: 0.3s; }\r\n                    .scroll-arrow:hover { background: #c01313; border-color: #c01313; color: #fff; }\r\n                    .scroll-left { left: 0; } .scroll-right { right: 0; }\r\n                    .hud-header { border-left: 4px solid #c01313; padding-left: 20px; margin-bottom: 30px; }\r\n                    .hud-title { font-size: 24px; font-weight: 800; color: #111; font-family: \'Rajdhani\'; }\r\n                    .text-red { color: #c01313; }\r\n                    .blink { color: #c01313; animation: b-pulse 1.5s infinite; font-size: 10px; margin-left: 10px; }\r\n                    @keyframes b-pulse { 0% {opacity: 1;} 50% {opacity: 0.3;} 100% {opacity: 1;} }\r\n                    .ui-grid-overlay { position: absolute; inset: 0; background: radial-gradient(rgba(255,255,255,0.03) 1px, transparent 1px); background-size: 20px 20px; pointer-events: none; }\r\n                    &lt;/style&gt;\r\n\r\n                    &lt;script&gt;\r\n                    document.addEventListener(\'DOMContentLoaded\', function() {\r\n                        const markers = document.querySelectorAll(\'.marker-point\');\r\n                        const cards = document.querySelectorAll(\'.b-cat-card\');\r\n                        const container = document.getElementById(\'bottom-cats-container\');\r\n\r\n                        // Синхронизация Маркер -&gt; Карточка (на главной)\r\n                        markers.forEach(marker =&gt; {\r\n                            marker.addEventListener(\'mouseenter\', () =&gt; {\r\n                                const id = marker.getAttribute(\'data-link\');\r\n                                const card = document.getElementById(id);\r\n                                if (card &amp;&amp; container) {\r\n                                    card.classList.add(\'active-card-sync\');\r\n                                    container.scrollTo({ left: card.offsetLeft - (container.clientWidth / 2) + (card.clientWidth / 2), behavior: \'smooth\' });\r\n                                }\r\n                            });\r\n                            marker.addEventListener(\'mouseleave\', () =&gt; {\r\n                                const id = marker.getAttribute(\'data-link\');\r\n                                const card = document.getElementById(id);\r\n                                if (card) card.classList.remove(\'active-card-sync\');\r\n                            });\r\n                        });\r\n\r\n                        // Стрелки скролла\r\n                        const btnL = document.getElementById(\'scroll-left\');\r\n                        const btnR = document.getElementById(\'scroll-right\');\r\n                        if(btnL &amp;&amp; btnR) {\r\n                            btnL.addEventListener(\'click\', () =&gt; container.scrollBy({ left: -300, behavior: \'smooth\' }));\r\n                            btnR.addEventListener(\'click\', () =&gt; container.scrollBy({ left: 300, behavior: \'smooth\' }));\r\n                        }\r\n                    });\r\n                    &lt;/script&gt;\r\n                {% endif %}\r\n\r\n            {% if products %}\r\n            &lt;div class=&quot;grid-container&quot;&gt;\r\n                {% for product in products %}\r\n                &lt;div class=&quot;card-item&quot;&gt;\r\n                    &lt;div class=&quot;card-top-actions&quot;&gt;\r\n                        {# Кнопки теперь без onclick, их перехватит jQuery #}\r\n                        &lt;button type=&quot;button&quot; class=&quot;action-btn btn-wish-garage&quot; data-id=&quot;{{ product.product_id }}&quot;&gt;\r\n                            &lt;i class=&quot;fa-regular fa-heart&quot;&gt;&lt;/i&gt;\r\n                        &lt;/button&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;card-img-wrap&quot;&gt;\r\n                        &lt;a href=&quot;{{ product.href }}&quot;&gt;\r\n                            &lt;img src=&quot;{{ product.thumb }}&quot; alt=&quot;{{ product.name }}&quot; title=&quot;{{ product.name }}&quot;&gt;\r\n                        &lt;/a&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;card-body&quot;&gt;\r\n                        &lt;a href=&quot;{{ product.href }}&quot; class=&quot;card-title&quot;&gt;{{ product.name }}&lt;/a&gt;\r\n                        &lt;div class=&quot;price-tag&quot;&gt;\r\n                            {% if product.special %}\r\n                                &lt;span style=&quot;text-decoration: line-through; color: #666; font-size: 1rem;&quot;&gt;{{ product.price }}&lt;/span&gt;\r\n                                &lt;span style=&quot;color: #ff0000;&quot;&gt;{{ product.special }}&lt;/span&gt;\r\n                            {% else %}\r\n                                {{ product.price }}\r\n                            {% endif %}\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;a onclick=&quot;cart.add(\'{{ product.product_id }}\');&quot; class=&quot;btn-order&quot;&gt;\r\n                        &lt;span class=&quot;btn-order-text&quot;&gt;&lt;/span&gt;\r\n                    &lt;/a&gt;\r\n                &lt;/div&gt;\r\n                {% endfor %}\r\n            &lt;/div&gt;\r\n            {% endif %}\r\n\r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script type=&quot;text/javascript&quot;&gt;\r\n$(document).ready(function() {\r\n    // Получаем токен из URL\r\n    const urlParams = new URLSearchParams(window.location.search);\r\n    const customerToken = urlParams.get(\'customer_token\') || \'\';\r\n\r\n    // Объект переводов (сохраняем твою красоту)\r\n    const garageI18n = {\r\n        pl: {\r\n            successTitle: \'❤️ MÓJ GARAŻ\',\r\n            successMsg: \'Część została dodana do Twojej listy. Czy chcesz ją przejrzeć?\',\r\n            errorTitle: \'⚠️ WYMAGANE LOGOWANIE\',\r\n            errorMsg: \'Aby dodać produkt do garażu, musisz się najpierв zalogować.\',\r\n            btnText: \'PRZEJDŹ →\'\r\n        },\r\n        ua: {\r\n            successTitle: \'❤️ МІЙ ГАРАЖ\',\r\n            successMsg: \'Запчастину додано до вашого списку. Бажаєте переглянути?\',\r\n            errorTitle: \'⚠️ ПОТРІБНА АВТОРИЗАЦІЯ\',\r\n            errorMsg: \'Щоб додати товар у гараж, потрібно спочатку увійти в акаунт.\',\r\n            btnText: \'ПЕРЕЙТИ →\'\r\n        },\r\n        en: {\r\n            successTitle: \'❤️ MY GARAGE\',\r\n            successMsg: \'The part has been added to your list. Would you like to view it?\',\r\n            errorTitle: \'⚠️ LOGIN REQUIRED\',\r\n            errorMsg: \'To add a product to your garage, you must first log in.\',\r\n            btnText: \'VIEW NOW →\'\r\n        }\r\n    };\r\n\r\n    window.showGarageToast = function(isError = false) {\r\n        $(\'.garage-toast\').remove();\r\n        const lang = document.body.getAttribute(\'data-lang\') || \'ua\';\r\n        const texts = garageI18n[lang] || garageI18n[\'en\'];\r\n        const title = isError ? texts.errorTitle : texts.successTitle;\r\n        const message = isError ? texts.errorMsg : texts.successMsg;\r\n        let link = isError ? \'index.php?route=account/login\' : \'index.php?route=account/wishlist\';\r\n        if (customerToken) link += \'&amp;customer_token=\' + customerToken;\r\n\r\n        const toastHtml = `\r\n            &lt;div class=&quot;garage-toast&quot; style=&quot;display:none;&quot;&gt;\r\n                &lt;div class=&quot;toast-header&quot;&gt;\r\n                    &lt;span class=&quot;toast-title&quot;&gt;${title}&lt;/span&gt;\r\n                    &lt;span class=&quot;toast-close&quot; onclick=&quot;$(this).closest(\'.garage-toast\').fadeOut(300)&quot;&gt;×&lt;/span&gt;\r\n                &lt;/div&gt;\r\n                &lt;div class=&quot;toast-body&quot;&gt;\r\n                    &lt;p&gt;${message}&lt;/p&gt;\r\n                    &lt;a href=&quot;${link}&quot; class=&quot;toast-link&quot;&gt;${texts.btnText}&lt;/a&gt;\r\n                &lt;/div&gt;\r\n                &lt;div class=&quot;toast-progress&quot;&gt;&lt;/div&gt;\r\n            &lt;/div&gt;`;\r\n\r\n        $(\'body\').append(toastHtml);\r\n        $(\'.garage-toast\').fadeIn(400);\r\n        setTimeout(() =&gt; { $(\'.garage-toast\').fadeOut(600, function() { $(this).remove(); }); }, 5000);\r\n    };\r\n\r\n    $(document).on(\'click\', \'.btn-wish-garage\', function(e) {\r\n        e.preventDefault();\r\n        const $btn = $(this);\r\n        const pid = $btn.data(\'id\');\r\n\r\n        if (!$btn.hasClass(\'active\')) {\r\n            $.ajax({\r\n                url: \'index.php?route=account/wishlist|add&amp;language=\' + (document.body.getAttribute(\'data-lang\') || \'ua\') + (customerToken ? \'&amp;customer_token=\' + customerToken : \'\'),\r\n                type: \'post\',\r\n                data: \'product_id=\' + pid,\r\n                dataType: \'json\',\r\n                beforeSend: function() {\r\n                    $btn.css(\'opacity\', \'0.5\'); // Визуальный отклик\r\n                },\r\n                complete: function() {\r\n                    $btn.css(\'opacity\', \'1\');\r\n                },\r\n                success: function(json) {\r\n                    // Если сервер прислал редирект на логин — значит сессия сбросилась\r\n                    if (json[\'redirect\'] || (typeof json === \'string\' &amp;&amp; json.includes(\'login\'))) {\r\n                        showGarageToast(true);\r\n                        return;\r\n                    }\r\n\r\n                    if (json[\'success\']) {\r\n                        $btn.addClass(\'active\');\r\n                        $btn.find(\'i\').removeClass(\'fa-regular\').addClass(\'fa-solid\');\r\n                        showGarageToast(false);\r\n                    } else if (json[\'error\']) {\r\n                        showGarageToast(true);\r\n                    }\r\n                },\r\n                error: function(xhr, ajaxOptions, thrownError) {\r\n                    // Если AJAX вообще упал (например 403 ошибка сессии)\r\n                    showGarageToast(true);\r\n                }\r\n            });\r\n        } else {\r\n            window.location = \'index.php?route=account/wishlist\' + (customerToken ? \'&amp;customer_token=\' + customerToken : \'\');\r\n        }\r\n    });\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 19:34:37');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(2, 0, 'common/home', '&lt;style&gt;\r\n    /* ПРИНУДИТЕЛЬНОЕ ЗАТЕМНЕНИЕ */\r\n    body, #common-home, #content { background-color: #121212 !important; color: #eee !important; }\r\n    #menu, .navbar-inverse, .nav-container { background-color: #1a1a1a !important; border-bottom: 2px solid #e63946 !important; }\r\n    #search .input-lg, #cart &gt; .btn { background-color: #222 !important; border: 1px solid #e63946 !important; color: #fff !important; }\r\n\r\n    /* ГЛАВНЫЙ БАННЕР */\r\n    .hero-premium {\r\n        background: linear-gradient(rgba(0,0,0,0.7), rgba(0,0,0,0.7)),\r\n                    url(\'https://images.unsplash.com/photo-1492144534655-ae79c964c9d7?auto=format&amp;fit=crop&amp;q=80&amp;w=1600\');\r\n        background-size: cover; background-position: center; padding: 120px 0; border-bottom: 3px solid #e63946; margin-bottom: 50px; text-align: center;\r\n    }\r\n    .hero-premium h1 { font-size: 4rem; font-weight: 900; color: #fff; text-transform: uppercase; }\r\n    .hero-premium .highlight { color: #e63946; }\r\n\r\n    /* КАРТОЧКИ */\r\n    .service-box {\r\n        background: #1a1a1a; border: 1px solid #333; border-top: 3px solid #e63946;\r\n        padding: 40px 20px; transition: 0.4s ease; text-align: center; margin-bottom: 30px; min-height: 300px;\r\n    }\r\n    .service-box:hover { border-color: #e63946; transform: translateY(-5px); box-shadow: 0 10px 30px rgba(230, 57, 70, 0.2); }\r\n\r\n    .btn-red-outline {\r\n        background: transparent; border: 2px solid #e63946; color: #fff; padding: 12px 35px;\r\n        font-weight: bold; text-transform: uppercase; transition: 0.3s; display: inline-block; text-decoration: none;\r\n    }\r\n    .btn-red-outline:hover { background: #e63946; color: #fff; box-shadow: 0 0 20px rgba(230, 57, 70, 0.4); }\r\n\r\n    /* Скрываем все языковые блоки по умолчанию */\r\n    .lang-block { display: none; }\r\n    /* УДАЛЯЕМ ГОЛУБОЙ ЦВЕТ И ДЕЛАЕМ МЕНЮ ПРЕМИАЛЬНЫМ */\r\n    #navbar-menu, .navbar {\r\n        background-color: #0a0a0a !important; /* Глубокий черный */\r\n        border-bottom: 2px solid #ff0000 !important; /* Красная линия под меню */\r\n        padding: 0 !important;\r\n    }\r\n\r\n    /* Основные ссылки меню */\r\n    .nav.navbar-nav &gt; li &gt; a,\r\n    .nav-link.dropdown-toggle {\r\n        color: #ffffff !important;\r\n        text-transform: uppercase !important;\r\n        font-weight: 800 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 13px !important;\r\n        padding: 15px 25px !important;\r\n        background: transparent !important;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    /* Эффект при наведении на пункт меню */\r\n    .nav.navbar-nav &gt; li:hover &gt; a {\r\n        background-color: #ff0000 !important; /* Красный фон при наведении */\r\n        color: #000000 !important; /* Черный текст на красном фоне */\r\n    }\r\n\r\n    /* ВЫПАДАЮЩЕЕ МЕНЮ (DROPDOWN) */\r\n    .dropdown-menu {\r\n        background-color: #111111 !important; /* Темный фон выпадающего окна */\r\n        border: 1px solid #ff0000 !important; /* Красная тонкая обводка */\r\n        border-top: 3px solid #ff0000 !important; /* Жирная линия сверху */\r\n        border-radius: 0 !important;\r\n        padding: 10px 0 !important;\r\n        box-shadow: 0 15px 30px rgba(0,0,0,0.9);\r\n    }\r\n\r\n    /* Ссылки внутри выпадающего меню */\r\n    .dropdown-item {\r\n        color: #cccccc !important;\r\n        font-size: 12px !important;\r\n        font-weight: 600 !important;\r\n        padding: 10px 20px !important;\r\n        transition: 0.2s;\r\n    }\r\n\r\n    .dropdown-item:hover {\r\n        background-color: #1a1a1a !important;\r\n        color: #ff0000 !important; /* Текст становится красным при наведении */\r\n        padding-left: 25px !important; /* Эффект сдвига */\r\n    }\r\n\r\n    /* Разделитель в меню */\r\n    .dropdown-divider {\r\n        border-top: 1px solid #333 !important;\r\n    }\r\n\r\n    /* Исправление отображения на мобильных устройствах */\r\n    .navbar-toggler {\r\n        border-color: #ff0000 !important;\r\n        background-color: #1a1a1a !important;\r\n    }\r\n    .navbar-toggler-icon {\r\n        filter: invert(1); /* Делает иконку &quot;гамбургера&quot; белой */\r\n    }\r\n    /* УДАЛЯЕМ ВСЕ СИНИЕ ПОЛОСКИ И ТЕНИ */\r\n    #menu,\r\n    .navbar,\r\n    #navbar-menu,\r\n    .navbar-collapse,\r\n    .nav-container {\r\n        border: none !important; /* Убирает все рамки */\r\n        box-shadow: none !important; /* Убирает голубое свечение/тени */\r\n        outline: none !important;\r\n        background-image: none !important;\r\n    }\r\n\r\n    /* Если синяя полоска — это верхняя граница контейнера меню */\r\n    .nav-container, #menu {\r\n        border-top: none !important;\r\n        border-left: none !important;\r\n        border-right: none !important;\r\n        /* Оставляем только твою красную полосу снизу */\r\n        border-bottom: 2px solid #ff0000 !important;\r\n    }\r\n\r\n    /* Убираем синий фон у активных пунктов, если он остался */\r\n    .nav.navbar-nav &gt; li &gt; a:focus,\r\n    .nav.navbar-nav &gt; li &gt; a:active {\r\n        background-color: transparent !important;\r\n        color: #fff !important;\r\n        box-shadow: none !important;\r\n    }\r\n\r\n    /* Прячем дефолтные разделители, которые могут давать синеву */\r\n    .navbar-nav &gt; li {\r\n        border: none !important;\r\n    }\r\n    /* УНИЧТОЖАЕМ БЕЛЫЕ ГРАНИЦЫ И ЦЕНТРИРУЕМ */\r\n    #carousel-banner-0 {\r\n        background-color: #0d0d0d !important; /* Глубокий черный фон */\r\n        padding: 0 !important;\r\n        margin-bottom: 40px;\r\n        border-bottom: 2px solid #ff0000; /* Фирменная красная линия снизу */\r\n    }\r\n\r\n    /* Настройка внутреннего контейнера */\r\n    #carousel-banner-0 .carousel-inner {\r\n        border: none !important;\r\n        background: #0d0d0d !important;\r\n    }\r\n\r\n    /* Работа с самим изображением */\r\n    #carousel-banner-0 .carousel-item img {\r\n        width: 100%;\r\n        max-width: 1140px; /* Ограничиваем ширину по контейнеру */\r\n        height: auto;\r\n        display: block;\r\n        margin: 0 auto;\r\n        /* Мягкое затемнение краев, чтобы белый фон картинки плавно переходил в черный фон сайта */\r\n        mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\r\n        -webkit-mask-image: linear-gradient(to right, transparent 0%, black 5%, black 95%, transparent 100%);\r\n\r\n        /* Делаем картинку чуть контрастнее для &quot;дорогого&quot; вида */\r\n        filter: brightness(0.9) contrast(1.1);\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    #carousel-banner-0 .carousel-item img:hover {\r\n        filter: brightness(1) contrast(1.1);\r\n    }\r\n\r\n    /* Стилизация индикаторов (точек) под баннером */\r\n    .carousel-indicators [data-bs-target] {\r\n        background-color: #ff0000 !important; /* Красные точки */\r\n        width: 30px;\r\n        height: 3px;\r\n        border: none;\r\n    }\r\n    /* УНИЧТОЖАЕМ БЕЛЫЕ ГРАНИЦЫ И ДОБАВЛЯЕМ КРАСНУЮ РАМКУ */\r\n    #carousel-banner-0 {\r\n        background-color: #0d0d0d !important;\r\n        padding: 0 !important;\r\n        margin-bottom: 40px;\r\n    }\r\n\r\n    /* Контейнер с красной рамкой */\r\n    #carousel-banner-0 .carousel-inner {\r\n        border: 2px solid #ff0000 !important; /* КРАСНАЯ ГРАНИЦА ВОКРУГ */\r\n        background: #000 !important;\r\n        border-radius: 0 !important;\r\n        overflow: hidden;\r\n    }\r\n\r\n    /* Исправляем само изображение */\r\n    #carousel-banner-0 .carousel-item img {\r\n        width: 100%;\r\n        height: 400px; /* Фиксируем высоту, чтобы обрезать белые края картинки */\r\n        object-fit: cover; /* КЛЮЧЕВОЙ МОМЕНТ: растягивает фото, скрывая лишние поля по краям */\r\n        display: block;\r\n        margin: 0 auto;\r\n\r\n        /* Убираем старые маски, если они мешали */\r\n        mask-image: none !important;\r\n        -webkit-mask-image: none !important;\r\n\r\n        /* Делаем картинку сочной */\r\n        filter: brightness(0.8) contrast(1.2);\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    /* Эффект свечения рамки при наведении */\r\n    #carousel-banner-0:hover .carousel-inner {\r\n        box-shadow: 0 0 20px rgba(255, 0, 0, 0.4);\r\n        border-color: #ff3333 !important;\r\n    }\r\n\r\n    #carousel-banner-0 .carousel-item img:hover {\r\n        filter: brightness(1) contrast(1.1);\r\n    }\r\n    /* ОБЩИЙ СТИЛЬ ДЛЯ ВСЕХ КАРУСЕЛЕЙ */\r\n    .carousel {\r\n        background-color: #0d0d0d !important;\r\n        margin-bottom: 40px;\r\n    }\r\n\r\n    /* Красная рамка для всех внутренних контейнеров каруселей */\r\n    .carousel-inner {\r\n        border: 2px solid #ff0000 !important;\r\n        background: #000 !important;\r\n        border-radius: 0 !important;\r\n        overflow: hidden;\r\n    }\r\n\r\n    /* Настройка изображений для главного баннера (слайдера) */\r\n    #carousel-banner-0 .carousel-item img {\r\n        width: 100%;\r\n        height: 400px; /* Фиксированная высота для скрытия полей */\r\n        object-fit: cover; /* Растягивает фото, обрезая белые края */\r\n        filter: brightness(0.8) contrast(1.2);\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    /* Настройка изображений для карусели брендов (внизу) */\r\n    #carousel-banner-1 {\r\n        padding: 20px 0;\r\n    }\r\n\r\n    #carousel-banner-1 .carousel-inner {\r\n        border: 1px solid #333 !important; /* Для брендов сделаем рамку потише */\r\n        padding: 15px 0;\r\n    }\r\n\r\n    #carousel-banner-1 img {\r\n        filter: grayscale(1) invert(1) brightness(2); /* Делает логотипы белыми и стильными */\r\n        opacity: 0.6;\r\n        transition: 0.3s;\r\n        max-height: 50px;\r\n        width: auto;\r\n    }\r\n\r\n    #carousel-banner-1 img:hover {\r\n        filter: grayscale(0) invert(0) brightness(1); /* Возвращает цвет при наведении */\r\n        opacity: 1;\r\n    }\r\n\r\n    /* Стилизация стрелок управления */\r\n    .carousel-control-prev, .carousel-control-next {\r\n        width: 5%;\r\n        filter: drop-shadow(0 0 5px #ff0000);\r\n    }\r\n\r\n    .carousel-control-prev span, .carousel-control-next span {\r\n        color: #ff0000;\r\n        font-size: 2rem;\r\n    }\r\n\r\n    /* Стилизация индикаторов (точек) */\r\n    .carousel-indicators [data-bs-target] {\r\n        background-color: #ff0000 !important;\r\n        height: 3px;\r\n        width: 30px;\r\n        border: none;\r\n    }\r\n    /* АГРЕССИВНОЕ УДАЛЕНИЕ БЕЛЫХ ГРАНИЦ */\r\n    #carousel-banner-0, #carousel-banner-1 {\r\n        background-color: transparent !important;\r\n        padding: 0 !important;\r\n        margin-bottom: 40px !important;\r\n        border: none !important; /* Убираем системные рамки */\r\n    }\r\n\r\n    /* Красная рамка БЕЗ внутренних просветов */\r\n    .carousel-inner {\r\n        border: 3px solid #ff0000 !important; /* Делаем чуть толще для уверенности */\r\n        background: #000 !important;\r\n        border-radius: 0 !important;\r\n        overflow: hidden;\r\n        padding: 0 !important; /* Гарантируем отсутствие зазоров внутри */\r\n    }\r\n\r\n    /* Растягиваем изображение так, чтобы оно &quot;выдавило&quot; белый фон */\r\n    #carousel-banner-0 .carousel-item img {\r\n        width: 100% !important;\r\n        height: 400px !important;\r\n        object-fit: cover !important; /* Обрезает родные белые края картинки */\r\n        display: block !important;\r\n        margin: 0 !important;\r\n        border: none !important;\r\n    }\r\n\r\n    /* Убираем отступы у колонок, если баннер внутри col-sm-12 */\r\n    .col-sm-12 &gt; #carousel-banner-0 {\r\n        margin-left: 0 !important;\r\n        margin-right: 0 !important;\r\n    }\r\n\r\n    /* Фикс для карусели брендов (чтобы не было белых дырок) */\r\n    #carousel-banner-1 .carousel-inner {\r\n        border: 1px solid #333 !important;\r\n    }\r\n    /* ФИНАЛЬНЫЙ ФИКС ОБРЕЗКИ БАННЕРА */\r\n    #carousel-banner-0 .carousel-item img {\r\n        width: 100% !important;\r\n        height: auto !important; /* Убираем фиксированную высоту, чтобы пропорции были родными */\r\n        max-height: 400px; /* Ограничиваем только максимальную высоту */\r\n        object-fit: contain !important; /* Картинка всегда вписывается целиком, без обрезки краев */\r\n        display: block !important;\r\n        margin: 0 auto !important;\r\n        background-color: #000; /* Если по бокам останется микро-зазор, он будет черным */\r\n    }\r\n    \r\n    /* Убираем лишние отступы у колонок Bootstrap, которые могут &quot;сдавливать&quot; баннер */\r\n    #carousel-banner-0 .col-12 {\r\n        padding: 0 !important;\r\n    }\r\n    \r\n    #carousel-banner-0 .row {\r\n        margin: 0 !important;\r\n    }\r\n    &lt;/style&gt;\r\n\r\n&lt;div id=&quot;common-home&quot;&gt;\r\n    {{ header }}\r\n\r\n    &lt;div class=&quot;hero-premium&quot;&gt;\r\n        &lt;div class=&quot;container&quot;&gt;\r\n            &lt;h1&gt;&lt;span class=&quot;highlight&quot;&gt;CAR SERVICE&lt;/span&gt; GARAGE&lt;/h1&gt;\r\n\r\n            &lt;div class=&quot;lang-block lang-en&quot;&gt;\r\n                &lt;p style=&quot;font-size: 1.5rem; color: #bbb;&quot;&gt;Professional care for your vehicle&lt;/p&gt;&lt;br&gt;\r\n                &lt;a href=&quot;index.php?route=information/contact&quot; class=&quot;btn-red-outline&quot;&gt;Book Now&lt;/a&gt;\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;lang-block lang-ua&quot;&gt;\r\n                &lt;p style=&quot;font-size: 1.5rem; color: #bbb;&quot;&gt;Турбота про ваш автомобіль на найвищому рівні&lt;/p&gt;&lt;br&gt;\r\n                &lt;a href=&quot;index.php?route=information/contact&quot; class=&quot;btn-red-outline&quot;&gt;Записатися&lt;/a&gt;\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;lang-block lang-pl&quot;&gt;\r\n                &lt;p style=&quot;font-size: 1.5rem; color: #bbb;&quot;&gt;Profesjonalna obsługa Twojego samochodu&lt;/p&gt;&lt;br&gt;\r\n                &lt;a href=&quot;index.php?route=information/contact&quot; class=&quot;btn-red-outline&quot;&gt;Zarezerwuj&lt;/a&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n\r\n    &lt;div class=&quot;container&quot;&gt;\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-sm-12&quot;&gt;\r\n                {{ content_top }}\r\n\r\n                &lt;div class=&quot;row&quot;&gt;\r\n                    &lt;div class=&quot;col-sm-4&quot;&gt;\r\n                        &lt;div class=&quot;service-box&quot;&gt;\r\n                            &lt;i class=&quot;fa fa-cogs&quot; style=&quot;font-size: 40px; color: #e63946; margin-bottom: 15px;&quot;&gt;&lt;/i&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-en&quot;&gt;Engine&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-ua&quot;&gt;Двигун&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-pl&quot;&gt;Silnik&lt;/h3&gt;\r\n\r\n                            &lt;p class=&quot;lang-block lang-en&quot;&gt;Overhaul and high-precision diagnostics.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-ua&quot;&gt;Капітальний ремонт та діагностика.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-pl&quot;&gt;Remont kapitalny i diagnostyka.&lt;/p&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;col-sm-4&quot;&gt;\r\n                        &lt;div class=&quot;service-box&quot;&gt;\r\n                            &lt;i class=&quot;fa fa-car&quot; style=&quot;font-size: 40px; color: #e63946; margin-bottom: 15px;&quot;&gt;&lt;/i&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-en&quot;&gt;Suspension&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-ua&quot;&gt;Ходова&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-pl&quot;&gt;Zawieszenie&lt;/h3&gt;\r\n\r\n                            &lt;p class=&quot;lang-block lang-en&quot;&gt;Premium parts and bench testing.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-ua&quot;&gt;Запчастини преміум-класу та стенд.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-pl&quot;&gt;Części premium i testy.&lt;/p&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;col-sm-4&quot;&gt;\r\n                        &lt;div class=&quot;service-box&quot;&gt;\r\n                            &lt;i class=&quot;fa fa-star&quot; style=&quot;font-size: 40px; color: #e63946; margin-bottom: 15px;&quot;&gt;&lt;/i&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-en&quot;&gt;Detailing&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-ua&quot;&gt;Детейлінг&lt;/h3&gt;\r\n                            &lt;h3 class=&quot;lang-block lang-pl&quot;&gt;Detailing&lt;/h3&gt;\r\n\r\n                            &lt;p class=&quot;lang-block lang-en&quot;&gt;Polishing and protective coatings.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-ua&quot;&gt;Полірування та захисні покриття.&lt;/p&gt;\r\n                            &lt;p class=&quot;lang-block lang-pl&quot;&gt;Polerowanie i powłoki ochronne.&lt;/p&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/div&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n\r\n    {{ footer }}\r\n&lt;/div&gt;\r\n\r\n&lt;script&gt;\r\ndocument.addEventListener(&quot;DOMContentLoaded&quot;, function() {\r\n    // 1. Получаем URL и Куки\r\n    var currentUrl = window.location.href.toLowerCase();\r\n    var cookieValue = (document.cookie.split(\'; \').find(row =&gt; row.startsWith(\'language=\'))?.split(\'=\')[1] || \'\').toLowerCase();\r\n\r\n    var finalLang = \'en\'; // По умолчанию английский\r\n\r\n    // 2. ЖЕСТКАЯ ПРОВЕРКА ПРИОРИТЕТОВ\r\n\r\n    // ПРОВЕРКА ПОЛЬСКОГО (URL важнее куки)\r\n    if (currentUrl.includes(\'language=pl\') || currentUrl.includes(\'/pl\')) {\r\n        finalLang = \'pl\';\r\n    }\r\n    // ПРОВЕРКА АНГЛИЙСКОГО (Если в URL есть en-gb, игнорируем всё остальное!)\r\n    else if (currentUrl.includes(\'language=en\') || currentUrl.includes(\'/en\')) {\r\n        finalLang = \'en\';\r\n    }\r\n    // ПРОВЕРКА УКРАИНСКОГО\r\n    else if (currentUrl.includes(\'language=uk\') || currentUrl.includes(\'/ua\') || cookieValue === \'uk-ua\' || cookieValue === \'ua\') {\r\n        finalLang = \'ua\';\r\n    }\r\n\r\n    // Если в URL ничего не нашли, а в куки есть польский\r\n    if (finalLang === \'en\' &amp;&amp; (cookieValue === \'pl\' || cookieValue === \'pl-pl\')) {\r\n        finalLang = \'pl\';\r\n    }\r\n\r\n    console.log(&quot;--- FINAL FIX ---&quot;);\r\n    console.log(&quot;URL:&quot;, currentUrl);\r\n    console.log(&quot;Cookie:&quot;, cookieValue);\r\n    console.log(&quot;Result:&quot;, finalLang);\r\n\r\n    // 3. ПРИМЕНЕНИЕ\r\n    var allBlocks = document.querySelectorAll(\'.lang-block\');\r\n    allBlocks.forEach(function(el) {\r\n        el.style.setProperty(\'display\', \'none\', \'important\');\r\n    });\r\n\r\n    var activeBlocks = document.querySelectorAll(\'.lang-\' + finalLang);\r\n    activeBlocks.forEach(function(block) {\r\n        block.style.setProperty(\'display\', \'block\', \'important\');\r\n    });\r\n});\r\n&lt;/script&gt;', 1, '2026-02-22 19:36:19'),
(3, 0, 'common/header', '&lt;!DOCTYPE html&gt;\r\n&lt;html dir=&quot;{{ direction }}&quot; lang=&quot;{{ lang }}&quot;&gt;\r\n&lt;head&gt;\r\n  &lt;meta charset=&quot;UTF-8&quot;/&gt;\r\n  &lt;meta name=&quot;viewport&quot; content=&quot;width=device-width, initial-scale=1&quot;&gt;\r\n  &lt;meta http-equiv=&quot;X-UA-Compatible&quot; content=&quot;IE=edge&quot;&gt;\r\n  &lt;title&gt;{{ title }}&lt;/title&gt;\r\n  &lt;base href=&quot;{{ base }}&quot;/&gt;\r\n  &lt;script src=&quot;{{ jquery }}&quot; type=&quot;text/javascript&quot;&gt;&lt;/script&gt;\r\n  &lt;link href=&quot;{{ bootstrap }}&quot; type=&quot;text/css&quot; rel=&quot;stylesheet&quot; media=&quot;screen&quot;/&gt;\r\n  &lt;link href=&quot;{{ icons }}&quot; rel=&quot;stylesheet&quot; type=&quot;text/css&quot;/&gt;\r\n  &lt;link href=&quot;{{ stylesheet }}&quot; type=&quot;text/css&quot; rel=&quot;stylesheet&quot;/&gt;\r\n  &lt;script src=&quot;catalog/view/javascript/common.js&quot; type=&quot;text/javascript&quot;&gt;&lt;/script&gt;\r\n\r\n  &lt;style&gt;\r\n    /* 1. БАЗА */\r\n    body { background-color: #0d0d0d; color: #eee; }\r\n    nav#top { background-color: #0a0a0a !important; border-bottom: 1px solid #222 !important; padding: 8px 0 !important; }\r\n    nav#top a, nav#top button { color: #888 !important; font-size: 11px !important; text-transform: uppercase; text-decoration: none !important; background: none; border: none; }\r\n    nav#top a:hover { color: #ff0000 !important; }\r\n\r\n    /* 2. ШАПКА (ВОЗВРАТ СТРУКТУРЫ) */\r\n    header { background-color: #121212 !important; padding: 20px 0 !important; border-bottom: 1px solid #222 !important; }\r\n    \r\n    /* Используем Flex вместо Grid для стабильности иконок */\r\n    .header-content { display: flex; align-items: center; justify-content: space-between; gap: 20px; }\r\n    #logo img { max-height: 50px; width: auto; }\r\n\r\n    /* Поиск и Корзина */\r\n    .header-search { flex-grow: 1; max-width: 500px; }\r\n    .header-cart { min-width: 220px; }\r\n\r\n    /* КНОПКА КОРЗИНЫ (ФИКС ИКОНОК) */\r\n    header #cart .btn-dark {\r\n        background-color: #000 !important;\r\n        border: 2px solid #ff0000 !important;\r\n        color: #fff !important;\r\n        text-transform: uppercase;\r\n        font-weight: 800;\r\n        height: 46px;\r\n        padding: 0 20px;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        width: 100%;\r\n        border-radius: 0;\r\n    }\r\n    header #cart i { color: #ff0000 !important; margin-right: 10px; font-size: 16px; }\r\n\r\n    /* ВЫПАДАЮЩЕЕ МЕНЮ КОРЗИНЫ */\r\n    #cart .dropdown-menu {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #ff0000 !important;\r\n        border-radius: 0 !important;\r\n        padding: 15px !important;\r\n        min-width: 350px;\r\n        right: 0;\r\n        left: auto;\r\n        box-shadow: 0 10px 40px rgba(0,0,0,0.8);\r\n        display: none; /* Скрыто по умолчанию */\r\n    }\r\n    #cart.show .dropdown-menu, #cart .dropdown-menu.show { display: block !important; }\r\n\r\n    /* 3. ГАРАЖНЫЙ TOAST */\r\n    .garage-toast {\r\n        position: fixed; top: 20px; right: 20px; width: 320px;\r\n        background: #111; border: 1px solid #ff0000; color: #fff;\r\n        z-index: 9999; display: none; font-family: \'Orbitron\', sans-serif;\r\n        padding: 15px; box-shadow: 0 0 20px rgba(255,0,0,0.4);\r\n    }\r\n\r\n    /* ЯЗЫКИ (ДЛЯ CSS ПЕРЕВОДА) */\r\n    body[data-lang=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n    body[data-lang=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n  &lt;/style&gt;\r\n\r\n  &lt;script&gt;\r\n    $(document).ready(function() {\r\n        // Определение языка для CSS\r\n        const htmlLang = document.documentElement.lang.toLowerCase();\r\n        let currentLang = \'en\';\r\n        if (htmlLang.includes(\'pl\')) currentLang = \'pl\';\r\n        else if (htmlLang.includes(\'uk\') || htmlLang.includes(\'ua\')) currentLang = \'ua\';\r\n        document.body.setAttribute(\'data-lang\', currentLang);\r\n\r\n        // --- ГЛАВНЫЙ ФИКС КОРЗИНЫ ---\r\n        // Используем &quot;делегирование&quot;, чтобы клик работал всегда\r\n        $(document).on(\'click\', \'#cart .dropdown-toggle\', function(e) {\r\n            e.preventDefault();\r\n            e.stopPropagation();\r\n            console.log(\'Клик по корзине зафиксирован\'); // Проверка в консоли\r\n            \r\n            const $cartBlock = $(\'#cart\');\r\n            $cartBlock.toggleClass(\'show\');\r\n        });\r\n\r\n        // Закрытие при клике мимо\r\n        $(document).on(\'click\', function (e) {\r\n            if (!$(e.target).closest(\'#cart\').length) {\r\n                $(\'#cart\').removeClass(\'show\');\r\n            }\r\n        });\r\n\r\n        // Глобальная функция уведомлений\r\n        window.showGarageToast = function(isError, title, message) {\r\n            const btnText = (currentLang === \'ua\') ? \'В ГАРАЖ\' : \'DO GARAŻU\';\r\n            $(\'.garage-toast\').remove();\r\n            $(\'body\').append(`\r\n                &lt;div class=&quot;garage-toast&quot;&gt;\r\n                    &lt;b style=&quot;color:#ff0000; display:block; margin-bottom:10px;&quot;&gt;⚠️ ${title}&lt;/b&gt;\r\n                    &lt;p style=&quot;font-size:12px; margin-bottom:10px;&quot;&gt;${message}&lt;/p&gt;\r\n                    &lt;a href=&quot;index.php?route=checkout/cart&quot; style=&quot;color:#00ff00; text-decoration:none; font-size:10px; border-bottom:1px solid&quot;&gt;${btnText} →&lt;/a&gt;\r\n                &lt;/div&gt;\r\n            `);\r\n            $(\'.garage-toast\').fadeIn().delay(5000).fadeOut();\r\n        };\r\n    });\r\n  &lt;/script&gt;\r\n&lt;/head&gt;\r\n\r\n&lt;body&gt;\r\n&lt;div id=&quot;container&quot;&gt;\r\n  &lt;nav id=&quot;top&quot;&gt;\r\n    &lt;div class=&quot;container d-flex justify-content-between&quot;&gt;\r\n      &lt;div&gt;{{ currency }} {{ language }}&lt;/div&gt;\r\n      &lt;div class=&quot;d-flex gap-3&quot;&gt;\r\n        &lt;a href=&quot;tel:{{ telephone }}&quot;&gt;&lt;i class=&quot;fa-solid fa-phone&quot; style=&quot;color:#ff0000&quot;&gt;&lt;/i&gt; {{ telephone }}&lt;/a&gt;\r\n        &lt;div class=&quot;dropdown&quot;&gt;\r\n          &lt;a href=&quot;#&quot; class=&quot;dropdown-toggle&quot; data-bs-toggle=&quot;dropdown&quot;&gt;&lt;i class=&quot;fa-solid fa-user&quot;&gt;&lt;/i&gt; {{ text_account }}&lt;/a&gt;\r\n          &lt;ul class=&quot;dropdown-menu dropdown-menu-end&quot;&gt;\r\n            {% if not logged %}\r\n              &lt;li&gt;&lt;a class=&quot;dropdown-item&quot; href=&quot;{{ register }}&quot;&gt;{{ text_register }}&lt;/a&gt;&lt;/li&gt;\r\n              &lt;li&gt;&lt;a class=&quot;dropdown-item&quot; href=&quot;{{ login }}&quot;&gt;{{ text_login }}&lt;/a&gt;&lt;/li&gt;\r\n            {% else %}\r\n              &lt;li&gt;&lt;a class=&quot;dropdown-item&quot; href=&quot;{{ account }}&quot;&gt;{{ text_account }}&lt;/a&gt;&lt;/li&gt;\r\n              &lt;li&gt;&lt;a class=&quot;dropdown-item&quot; href=&quot;{{ logout }}&quot;&gt;{{ text_logout }}&lt;/a&gt;&lt;/li&gt;\r\n            {% endif %}\r\n          &lt;/ul&gt;\r\n        &lt;/div&gt;\r\n      &lt;/div&gt;\r\n    &lt;/div&gt;\r\n  &lt;/nav&gt;\r\n\r\n  &lt;header&gt;\r\n    &lt;div class=&quot;container&quot;&gt;\r\n      &lt;div class=&quot;header-content&quot;&gt;\r\n        &lt;div id=&quot;logo&quot;&gt;\r\n          {% if logo %}&lt;a href=&quot;{{ home }}&quot;&gt;&lt;img src=&quot;{{ logo }}&quot; alt=&quot;{{ name }}&quot; /&gt;&lt;/a&gt;{% endif %}\r\n        &lt;/div&gt;\r\n        \r\n        &lt;div class=&quot;header-search&quot;&gt;\r\n          {{ search }}\r\n        &lt;/div&gt;\r\n        \r\n        &lt;div class=&quot;header-cart&quot;&gt;\r\n          &lt;div id=&quot;cart&quot; class=&quot;dropdown&quot;&gt;\r\n            {{ cart }}\r\n          &lt;/div&gt;\r\n        &lt;/div&gt;\r\n      &lt;/div&gt;\r\n    &lt;/div&gt;\r\n  &lt;/header&gt;\r\n\r\n  {{ menu }}\r\n  &lt;main&gt;', 1, '2026-02-25 22:37:02'),
(4, 0, 'common/menu', '{% if categories %}\r\n  &lt;div class=&quot;container&quot;&gt;\r\n    &lt;nav id=&quot;menu&quot; class=&quot;navbar navbar-expand-lg&quot; style=&quot;background-color: #0a0a0a !important; border-bottom: 2px solid #ff0000 !important; border-radius: 0;&quot;&gt;\r\n\r\n      &lt;div id=&quot;category&quot; class=&quot;d-block d-sm-block d-lg-none&quot; style=&quot;color: #fff; text-transform: uppercase; font-weight: 800; padding-left: 15px;&quot;&gt;{{ text_category }}&lt;/div&gt;\r\n\r\n      &lt;button type=&quot;button&quot; data-bs-toggle=&quot;collapse&quot; data-bs-target=&quot;#navbar-menu&quot; class=&quot;navbar-toggler d-lg-none&quot; style=&quot;border-color: #ff0000; margin-right: 15px;&quot;&gt;\r\n        &lt;i class=&quot;fa-solid fa-bars&quot; style=&quot;color: #ff0000;&quot;&gt;&lt;/i&gt;\r\n      &lt;/button&gt;\r\n\r\n      &lt;div id=&quot;navbar-menu&quot; class=&quot;collapse navbar-collapse&quot;&gt;\r\n        &lt;ul class=&quot;nav navbar-nav&quot;&gt;\r\n\r\n          {# 1. КАТЕГОРИИ ИЗ БАЗЫ (Автомобили, Услуги) #}\r\n          {% for category in categories %}\r\n            {% if category.children %}\r\n              &lt;li class=&quot;nav-item dropdown&quot;&gt;\r\n                &lt;a href=&quot;{{ category.href }}&quot; class=&quot;nav-link dropdown-toggle&quot; style=&quot;color: #fff !important; font-family: \'Orbitron\', sans-serif; text-transform: uppercase; font-weight: 800;&quot;&gt;{{ category.name }}&lt;/a&gt;\r\n                &lt;div class=&quot;dropdown-menu&quot;&gt;\r\n                  &lt;div class=&quot;dropdown-inner&quot;&gt;\r\n                    {% for children in category.children|batch(5) %}\r\n                      &lt;ul class=&quot;list-unstyled&quot;&gt;\r\n                        {% for child in children %}\r\n                          &lt;li&gt;&lt;a href=&quot;{{ child.href }}&quot; class=&quot;dropdown-item&quot;&gt;{{ child.name }}&lt;/a&gt;&lt;/li&gt;\r\n                        {% endfor %}\r\n                      &lt;/ul&gt;\r\n                    {% endfor %}\r\n                  &lt;/div&gt;\r\n                &lt;/div&gt;\r\n              &lt;/li&gt;\r\n            {% else %}\r\n              &lt;li class=&quot;nav-item&quot;&gt;&lt;a href=&quot;{{ category.href }}&quot; class=&quot;nav-link&quot; style=&quot;color: #fff !important; font-family: \'Orbitron\', sans-serif; text-transform: uppercase; font-weight: 800;&quot;&gt;{{ category.name }}&lt;/a&gt;&lt;/li&gt;\r\n            {% endif %}\r\n          {% endfor %}\r\n\r\n          {# 2. КНОПКА КОНТАКТЫ #}\r\n          &lt;li class=&quot;nav-item&quot;&gt;\r\n            &lt;a href=&quot;index.php?route=information/contact&quot; class=&quot;nav-link&quot; style=&quot;color: #fff !important; font-family: \'Orbitron\', sans-serif; text-transform: uppercase; font-weight: 800;&quot;&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;CONTACT&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;КОНТАКТИ&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;KONTAKT&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n\r\n          {# 3. КНОПКА O NAS #}\r\n          &lt;li class=&quot;nav-item&quot;&gt;\r\n            &lt;a href=&quot;index.php?route=information/information&amp;information_id=1&quot; class=&quot;nav-link&quot; style=&quot;color: #fff !important; font-family: \'Orbitron\', sans-serif; text-transform: uppercase; font-weight: 800;&quot;&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;ABOUT US&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;ПРО НАС&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;O NAS&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n\r\n        &lt;/ul&gt;\r\n      &lt;/div&gt;\r\n    &lt;/nav&gt;\r\n  &lt;/div&gt;\r\n{% endif %}\r\n\r\n&lt;style&gt;\r\n  /* Скрываем все блоки перевода по умолчанию */\r\n  .lang-block {\r\n    display: none !important;\r\n  }\r\n\r\n  /* Магия CSS: показываем нужный язык на основе атрибута lang в &lt;html&gt; */\r\n  /* Польский (pl, pl-pl) */\r\n  html[lang*=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n  \r\n  /* Украинский (uk, ua, uk-ua) */\r\n  html[lang*=&quot;uk&quot;] .lang-ua { display: inline-block !important; }\r\n  html[lang*=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n  \r\n  /* Английский (en, en-gb) - показываем только если нет польского или украинского */\r\n  html[lang*=&quot;en&quot;] .lang-en { display: inline-block !important; }\r\n\r\n  /* Стили для красоты меню */\r\n  .nav-link:hover { background-color: #ff0000 !important; color: #000 !important; }\r\n  .dropdown-item:hover { background-color: #ff0000 !important; color: #fff !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;script&gt;\r\n(function() {\r\n    function garagePowerTranslate() {\r\n        // 1. Пытаемся достать язык из куки (самый точный метод для OpenCart)\r\n        const getCookie = (name) =&gt; {\r\n            let matches = document.cookie.match(new RegExp(&quot;(?:^|; )&quot; + name.replace(/([\\.$?*|{}\\(\\)\\[\\]\\\\\\/\\+^])/g, \'\\\\$1\') + &quot;=([^;]*)&quot;));\r\n            return matches ? decodeURIComponent(matches[1]) : undefined;\r\n        };\r\n\r\n        const cookieLang = getCookie(\'language\');\r\n        const htmlLang = document.documentElement.lang.toLowerCase();\r\n\r\n        let currentLang = \'en\';\r\n\r\n        // Приоритет: Куки -&gt; Атрибут HTML\r\n        if (cookieLang === \'pl\' || htmlLang.startsWith(\'pl\')) {\r\n            currentLang = \'pl\';\r\n        } else if (cookieLang === \'uk\' || cookieLang === \'ua\' || htmlLang.startsWith(\'uk\') || htmlLang.startsWith(\'ua\')) {\r\n            currentLang = \'ua\';\r\n        }\r\n\r\n        // Принудительно ставим класс на body для надежности CSS\r\n        document.body.setAttribute(\'data-current-lang\', currentLang);\r\n\r\n        // Показываем нужные блоки\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; el.style.setProperty(\'display\', \'none\', \'important\'));\r\n        document.querySelectorAll(\'.lang-\' + currentLang).forEach(el =&gt; {\r\n            const displayType = [\'SPAN\', \'A\', \'B\'].includes(el.tagName) ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n\r\n    // Запуск на всех этапах жизни страницы\r\n    garagePowerTranslate();\r\n    document.addEventListener(\'DOMContentLoaded\', garagePowerTranslate);\r\n    window.addEventListener(\'load\', garagePowerTranslate);\r\n\r\n    // MutationObserver — если OpenCart вздумает перерисовать меню через AJAX\r\n    const obs = new MutationObserver(garagePowerTranslate);\r\n    obs.observe(document.body, { childList: true, subtree: true });\r\n})();\r\n&lt;/script&gt;', 1, '2026-02-23 11:20:10'),
(5, 0, 'information/contact', '{{ header }}\r\n&lt;style&gt;\r\n    /* ПРИНУДИТЕЛЬНОЕ ЗАТЕМНЕНИЕ ВСЕЙ СТРАНИЦЫ */\r\n    body, #information-contact, #content { background-color: #0d0d0d !important; color: #eee !important; }\r\n\r\n    /* УДАЛЕНИЕ ХЛЕБНЫХ КРОШЕК */\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* СТИЛИЗАЦИЯ ЗАГОЛОВКОВ С ОТСТУПОМ ОТ КРАСНОЙ ПОЛОСЫ */\r\n    h1, h3, legend {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        letter-spacing: 2px;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 25px !important;\r\n        margin-bottom: 30px !important;\r\n        color: #fff !important;\r\n        margin-top: 20px;\r\n    }\r\n\r\n    /* КАРТОЧКА ИНФОРМАЦИИ */\r\n    .card {\r\n        background: #161616 !important;\r\n        border: 1px solid #333 !important;\r\n        border-top: 3px solid #ff0000 !important;\r\n        border-radius: 0 !important;\r\n        margin-bottom: 40px;\r\n    }\r\n    .card-body { color: #ccc !important; }\r\n    .card-body strong { color: #ff0000; text-transform: uppercase; }\r\n\r\n    /* ФОРМА ОБРАТНОЙ СВЯЗИ */\r\n    #form-contact {\r\n        background: #111;\r\n        padding: 30px;\r\n        border: 1px solid #222;\r\n    }\r\n\r\n    /* ПОЛЯ ВВОДА: СВЕТЛЫЙ ТЕКСТ И ВИДИМЫЕ ПОДСКАЗКИ */\r\n    .form-control {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #ffffff !important; /* Цвет вводимого текста */\r\n        border-radius: 0 !important;\r\n        padding: 12px !important;\r\n    }\r\n\r\n    /* Цвет текста-подсказки (placeholder) */\r\n    .form-control::placeholder {\r\n        color: #888 !important;\r\n        opacity: 1;\r\n    }\r\n\r\n    .form-control:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: 0 0 10px rgba(255, 0, 0, 0.2) !important;\r\n        color: #fff !important;\r\n    }\r\n\r\n    .col-form-label {\r\n        color: #ff0000 !important;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        font-size: 0.85rem;\r\n        padding-left: 25px;\r\n    }\r\n\r\n    /* КНОПКИ */\r\n    .btn-primary, .btn-submit {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        text-transform: uppercase !important;\r\n        font-weight: 900 !important;\r\n        padding: 15px 40px !important;\r\n        transition: 0.3s;\r\n    }\r\n    .btn-primary:hover {\r\n        background-color: #fff !important;\r\n        color: #ff0000 !important;\r\n        transform: translateY(-2px);\r\n    }\r\n\r\n    /* МЕНЮ И ЛОГИКА ЯЗЫКОВ */\r\n    #navbar-menu, .navbar {\r\n        background-color: #0a0a0a !important;\r\n        border-bottom: 2px solid #ff0000 !important;\r\n        padding: 0 !important;\r\n    }\r\n\r\n    .nav.navbar-nav &gt; li &gt; a {\r\n        color: #ffffff !important;\r\n        text-transform: uppercase !important;\r\n        font-weight: 800 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 13px !important;\r\n        padding: 15px 25px !important;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .nav.navbar-nav &gt; li:hover &gt; a {\r\n        background-color: #ff0000 !important;\r\n        color: #000000 !important;\r\n    }\r\n\r\n    .lang-block { display: none; }\r\n    /* УНИЧТОЖЕНИЕ СИНЕГО ЦВЕТА И ЛИШНИХ ТЕНЕЙ В МЕНЮ */\r\n    #menu, \r\n    .navbar, \r\n    #navbar-menu, \r\n    .navbar-collapse, \r\n    .nav-container {\r\n        background-color: #0a0a0a !important; /* Глубокий черный фон */\r\n        background-image: none !important;    /* Убираем синие градиенты */\r\n        border: none !important;             /* Убираем все рамки */\r\n        box-shadow: none !important;         /* Убираем синее свечение */\r\n        outline: none !important;\r\n    }\r\n\r\n    /* ФИКС КРАСНОЙ ЛИНИИ ПОД МЕНЮ */\r\n    #menu, .navbar {\r\n        border-bottom: 2px solid #ff0000 !important; \r\n    }\r\n\r\n    /* ССЫЛКИ В МЕНЮ (Убираем синий фон при фокусе и нажатии) */\r\n    .nav.navbar-nav &gt; li &gt; a,\r\n    .nav-link {\r\n        background: transparent !important;\r\n        color: #ffffff !important;\r\n        text-shadow: none !important;\r\n    }\r\n\r\n    /* ПРИ НАВЕДЕНИИ - СТРОГО КРАСНЫЙ */\r\n    .nav.navbar-nav &gt; li &gt; a:hover,\r\n    .nav.navbar-nav &gt; li:hover &gt; a {\r\n        background-color: #ff0000 !important;\r\n        color: #000000 !important;\r\n    }\r\n\r\n    /* УБИРАЕМ СИНИЙ ЦВЕТ У АКТИВНЫХ ПУНКТОВ (Для некоторых тем) */\r\n    .navbar-nav &gt; li &gt; a:focus, \r\n    .navbar-nav &gt; li &gt; a:active {\r\n        background-color: transparent !important;\r\n        box-shadow: none !important;\r\n    }\r\n\r\n    /* ИСПРАВЛЕНИЕ ДЛЯ ВЫПАДАЮЩИХ СПИСКОВ (Если есть) */\r\n    .dropdown-menu {\r\n        background-color: #111 !important;\r\n        border: 1px solid #ff0000 !important;\r\n    }\r\n    .dropdown-item {\r\n        color: #fff !important;\r\n    }\r\n    .dropdown-item:hover {\r\n        background-color: #ff0000 !important;\r\n        color: #000 !important;\r\n    }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;information-contact&quot; class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        {{ column_left }}\r\n        &lt;div id=&quot;content&quot; class=&quot;col&quot;&gt;\r\n            {{ content_top }}\r\n\r\n            &lt;h1&gt;{{ heading_title }}&lt;/h1&gt;\r\n\r\n            &lt;div class=&quot;card&quot;&gt;\r\n                &lt;div class=&quot;card-body&quot;&gt;\r\n                    &lt;div class=&quot;row&quot;&gt;\r\n                        {% if image %}\r\n                            &lt;div class=&quot;col-sm-3&quot;&gt;&lt;img src=&quot;{{ image }}&quot; alt=&quot;{{ store }}&quot; title=&quot;{{ store }}&quot; class=&quot;img-thumbnail&quot; style=&quot;background: #222; border: 1px solid #444;&quot;/&gt;&lt;/div&gt;\r\n                        {% endif %}\r\n                        &lt;div class=&quot;col-sm-3&quot;&gt;\r\n                            &lt;strong&gt;{{ store }}&lt;/strong&gt;&lt;br/&gt;\r\n                            &lt;address&gt;{{ address }}&lt;/address&gt;\r\n                            {% if geocode %}\r\n                                &lt;a href=&quot;https://maps.google.com/maps?q={{ geocode|url_encode }}&quot; target=&quot;_blank&quot; class=&quot;btn btn-primary btn-sm&quot;&gt;&lt;i class=&quot;fa-solid fa-location-dot&quot;&gt;&lt;/i&gt; {{ button_map }}&lt;/a&gt;\r\n                            {% endif %}\r\n                        &lt;/div&gt;\r\n                        &lt;div class=&quot;col-sm-3&quot;&gt;\r\n                            &lt;strong&gt;{{ text_telephone }}&lt;/strong&gt;&lt;br/&gt;\r\n                            &lt;span style=&quot;font-size: 1.2rem; font-weight: 800;&quot;&gt;{{ telephone }}&lt;/span&gt;\r\n                        &lt;/div&gt;\r\n                        &lt;div class=&quot;col-sm-3&quot;&gt;\r\n                            {% if open %}\r\n                                &lt;strong&gt;{{ text_open }}&lt;/strong&gt;&lt;br/&gt;\r\n                                {{ open }}&lt;br/&gt;&lt;br/&gt;\r\n                            {% endif %}\r\n                            {% if comment %}\r\n                                &lt;strong&gt;{{ text_comment }}&lt;/strong&gt;&lt;br/&gt;\r\n                                {{ comment }}\r\n                            {% endif %}\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n\r\n            &lt;form id=&quot;form-contact&quot; action=&quot;{{ send }}&quot; method=&quot;post&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n                &lt;fieldset&gt;\r\n                    &lt;legend&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;CONTACT FORM&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;КОНТАКТНА ФОРМА&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;FORMULARZ KONTAKTOWY&lt;/span&gt;\r\n                    &lt;/legend&gt;\r\n\r\n                    &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n                        &lt;label for=&quot;input-name&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;YOUR NAME&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;ВАШЕ ІМ\'Я&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;TWOJE IMIĘ&lt;/span&gt;\r\n                        &lt;/label&gt;\r\n                        &lt;div class=&quot;col-sm-10&quot;&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;name&quot; value=&quot;{{ name }}&quot; id=&quot;input-name&quot; class=&quot;form-control&quot; placeholder=&quot;...&quot;/&gt;\r\n                            &lt;div id=&quot;error-name&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n                        &lt;label for=&quot;input-email&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;E-MAIL ADDRESS&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;E-MAIL АДРЕСА&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;ADRES E-MAIL&lt;/span&gt;\r\n                        &lt;/label&gt;\r\n                        &lt;div class=&quot;col-sm-10&quot;&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;email&quot; value=&quot;{{ email }}&quot; id=&quot;input-email&quot; class=&quot;form-control&quot; placeholder=&quot;...&quot;/&gt;\r\n                            &lt;div id=&quot;error-email&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n                        &lt;label for=&quot;input-enquiry&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;ENQUIRY&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;ПОВІДОМЛЕННЯ&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;ZAPYTANIE&lt;/span&gt;\r\n                        &lt;/label&gt;\r\n                        &lt;div class=&quot;col-sm-10&quot;&gt;\r\n                            &lt;textarea name=&quot;enquiry&quot; rows=&quot;6&quot; id=&quot;input-enquiry&quot; class=&quot;form-control&quot; placeholder=&quot;...&quot;&gt;&lt;/textarea&gt;\r\n                            &lt;div id=&quot;error-enquiry&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n                    {{ captcha }}\r\n                &lt;/fieldset&gt;\r\n                &lt;div class=&quot;text-end&quot;&gt;\r\n                    &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;SEND MESSAGE&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;ВІДПРАВИТИ&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;WYŚLIJ WIADOMOŚĆ&lt;/span&gt;\r\n                    &lt;/button&gt;\r\n                &lt;/div&gt;\r\n            &lt;/form&gt;\r\n\r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n        {{ column_right }}\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script&gt;\r\ndocument.addEventListener(&quot;DOMContentLoaded&quot;, function() {\r\n    var url = window.location.href.toLowerCase();\r\n    var cookieValue = (document.cookie.split(\'; \').find(row =&gt; row.startsWith(\'language=\'))?.split(\'=\')[1] || \'\').toLowerCase();\r\n\r\n    var finalLang = \'en\';\r\n\r\n    if (url.includes(\'language=pl\') || url.includes(\'/pl\')) {\r\n        finalLang = \'pl\';\r\n    } else if (url.includes(\'language=uk\') || url.includes(\'language=ua\') || url.includes(\'/ua\')) {\r\n        finalLang = \'ua\';\r\n    } else if (url.includes(\'language=en\') || url.includes(\'/en\')) {\r\n        finalLang = \'en\';\r\n    }\r\n    else if (cookieValue.includes(\'pl\')) {\r\n        finalLang = \'pl\';\r\n    } else if (cookieValue.includes(\'uk\') || cookieValue.includes(\'ua\')) {\r\n        finalLang = \'ua\';\r\n    }\r\n\r\n    function applyTranslations() {\r\n        var allLangBlocks = document.querySelectorAll(\'.lang-block\');\r\n        allLangBlocks.forEach(function(el) {\r\n            el.style.setProperty(\'display\', \'none\', \'important\');\r\n        });\r\n\r\n        var activeBlocks = document.querySelectorAll(\'.lang-\' + finalLang);\r\n        activeBlocks.forEach(function(block) {\r\n            var displayType = (block.tagName === \'SPAN\') ? \'inline-block\' : \'block\';\r\n            block.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n\r\n    applyTranslations();\r\n    // Повторный вызов на случай динамической подгрузки элементов\r\n    setTimeout(applyTranslations, 100);\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-22 20:56:49');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(6, 0, 'common/success', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН */\r\n    #common-success {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 50px;\r\n        padding-bottom: 80px;\r\n        min-height: 65vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    .success-title {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 30px;\r\n        line-height: 1.2;\r\n    }\r\n\r\n    /* 3. БОКС С ТЕКСТОМ */\r\n    .message-box {\r\n        background: #111; \r\n        padding: 40px; \r\n        border: 1px solid #222; \r\n        border-top: 3px solid #ff0000;\r\n        margin-bottom: 35px; \r\n    }\r\n\r\n    .message-box p {\r\n        font-size: 1.1rem;\r\n        color: #ccc;\r\n        line-height: 1.7;\r\n    }\r\n\r\n    /* 4. КНОПКА */\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 15px 45px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: bold;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: #fff !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    /* 5. ПРАВАЯ ПАНЕЛЬ (ФИКС ШИРИНЫ) */\r\n    #column-right {\r\n        padding-left: 50px !important;\r\n        min-width: 360px !important;\r\n    }\r\n\r\n    #column-right .list-group-item {\r\n        background-color: #111 !important;\r\n        border: 1px solid #222 !important;\r\n        color: #888 !important;\r\n        padding: 14px 25px !important;\r\n        margin-bottom: 5px !important;\r\n        text-transform: uppercase;\r\n        font-size: 11px;\r\n        letter-spacing: 1px;\r\n        white-space: nowrap !important;\r\n        transition: 0.3s all ease;\r\n        display: block !important;\r\n    }\r\n\r\n    #column-right .list-group-item:hover {\r\n        color: #fff !important;\r\n        border-left: 6px solid #ff0000 !important;\r\n        background-color: #1a1a1a !important;\r\n        padding-left: 30px !important;\r\n    }\r\n\r\n    /* Скрываем ненужные пункты в колонке */\r\n    #column-right a[href*=&quot;reward&quot;], \r\n    #column-right a[href*=&quot;affiliate&quot;], \r\n    #column-right a[href*=&quot;newsletter&quot;] {\r\n        display: none !important;\r\n    }\r\n\r\n    /* 6. ЛОГИКА ПЕРЕВОДА */\r\n    .lang-block { display: none !important; }\r\n    body[data-lang=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n    body[data-lang=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n    body[data-lang=&quot;en&quot;] .lang-en { display: inline-block !important; }\r\n    \r\n    body[data-lang=&quot;pl&quot;] div.lang-pl { display: block !important; }\r\n    body[data-lang=&quot;ua&quot;] div.lang-ua { display: block !important; }\r\n    body[data-lang=&quot;en&quot;] div.lang-en { display: block !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;common-success&quot; class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        {{ column_left }}\r\n        \r\n        &lt;div id=&quot;content&quot; class=&quot;col-md-7 col-sm-12&quot;&gt;\r\n            {{ content_top }}\r\n            \r\n            &lt;h1 class=&quot;success-title&quot;&gt;\r\n                {# Проверка: ВЫХОД #}\r\n                {% if &quot;Logout&quot; in heading_title or &quot;Вихід&quot; in heading_title or &quot;Wylogowanie&quot; in heading_title %}\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Account Logout&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Вихід з акаунта&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Wylogowano&lt;/span&gt;\r\n                \r\n                {# Проверка: РЕГИСТРАЦИЯ #}\r\n                {% elseif &quot;Created&quot; in heading_title or &quot;створено&quot; in heading_title or &quot;utworzone&quot; in heading_title %}\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Account Created!&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Акаунт створено!&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Konto utworzone!&lt;/span&gt;\r\n\r\n                {# Проверка: КОНТАКТЫ #}\r\n                {% elseif &quot;Contact&quot; in heading_title or &quot;Контакт&quot; in heading_title or &quot;Kontakt&quot; in heading_title %}\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Message Sent&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Повідомлення відправлено&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Wiadomość wysłana&lt;/span&gt;\r\n\r\n                {% else %}\r\n                    {{ heading_title }}\r\n                {% endif %}\r\n            &lt;/h1&gt;\r\n            \r\n            &lt;div class=&quot;message-box&quot;&gt;\r\n                {# Текст: ВЫХОД #}\r\n                {% if &quot;Logout&quot; in heading_title or &quot;Вихід&quot; in heading_title or &quot;Wylogowanie&quot; in heading_title %}\r\n                    &lt;div class=&quot;lang-block lang-en&quot;&gt;You have been logged off your account. It is now safe to leave the computer.&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-ua&quot;&gt;Ви вийшли зі свого облікового запису. Тепер можна безпечно залишити комп\'ютер.&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-pl&quot;&gt;Wylogowałeś się z konta. Możesz teraz bezpiecznie opuścić komputer.&lt;/div&gt;\r\n                \r\n                {# Текст: РЕГИСТРАЦИЯ #}\r\n                {% elseif &quot;Created&quot; in heading_title or &quot;створено&quot; in heading_title or &quot;utworzone&quot; in heading_title %}\r\n                    &lt;div class=&quot;lang-block lang-en&quot;&gt;Congratulations! Your new account has been successfully created!&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-ua&quot;&gt;Вітаємо! Ваш новий акаунт було успішно створено!&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-pl&quot;&gt;Gratulacje! Twoje nowe konto zostało pomyślnie utworzone!&lt;/div&gt;\r\n\r\n                {# Текст: КОНТАКТЫ #}\r\n                {% elseif &quot;Contact&quot; in heading_title or &quot;Контакт&quot; in heading_title or &quot;Kontakt&quot; in heading_title %}\r\n                    &lt;div class=&quot;lang-block lang-en&quot;&gt;Your enquiry has been successfully sent to the store owner!&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-ua&quot;&gt;Ваш запит успішно надіслано власнику магазину!&lt;/div&gt;\r\n                    &lt;div class=&quot;lang-block lang-pl&quot;&gt;Twoje zapytanie zostało pomyślnie wysłane do właściciela sklepu!&lt;/div&gt;\r\n\r\n                {% else %}\r\n                    {{ text_message }}\r\n                {% endif %}\r\n            &lt;/div&gt;\r\n            \r\n            &lt;div class=&quot;text-start&quot;&gt;\r\n                &lt;a href=&quot;{{ continue }}&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Continue&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Продовжити&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Kontynuuj&lt;/span&gt;\r\n                &lt;/a&gt;\r\n            &lt;/div&gt;\r\n\r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n\r\n        &lt;div id=&quot;column-right&quot; class=&quot;col-md-5 d-none d-md-block&quot;&gt;\r\n            {{ column_right }}\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script&gt;\r\n(function() {\r\n    function refreshSuccessLang() {\r\n        const activeLang = document.body.getAttribute(\'data-lang\') || \'en\';\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; el.style.setProperty(\'display\', \'none\', \'important\'));\r\n        document.querySelectorAll(\'.lang-\' + activeLang).forEach(el =&gt; {\r\n            const displayType = (el.tagName === \'SPAN\') ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n    refreshSuccessLang();\r\n    setTimeout(refreshSuccessLang, 250); // Небольшая задержка для корректного срабатывания\r\n})();\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-23 22:31:40'),
(8, 0, 'information/information', '{{ header }}\r\n\r\n&lt;script&gt;\r\n/**\r\n * УЛЬТРА-ФОРСИРОВАННЫЙ ПЕРЕХВАТ ЯЗЫКА\r\n * Исправляет проблему отображения английского языка на внутренних страницах.\r\n */\r\n(function() {\r\n    function finalInfoTranslate() {\r\n        const url = window.location.href.toLowerCase();\r\n        const htmlLang = document.documentElement.lang.toLowerCase();\r\n        // Прямое чтение куки без сторонних библиотек\r\n        const cookie = (document.cookie.match(\'(^|;)\\\\s*language\\\\s*=\\\\s*([^;]+)\') || [])[2] || \'\';\r\n        \r\n        let lang = \'en\';\r\n\r\n        // Приоритетное определение польского языка (ищем вхождение \'pl\')\r\n        if (url.indexOf(\'pl\') !== -1 || htmlLang.indexOf(\'pl\') !== -1 || cookie.indexOf(\'pl\') !== -1) {\r\n            lang = \'pl\';\r\n        } \r\n        // Определение украинского языка\r\n        else if (url.indexOf(\'uk\') !== -1 || url.indexOf(\'ua\') !== -1 || htmlLang.indexOf(\'uk\') !== -1 || htmlLang.indexOf(\'ua\') !== -1 || cookie.indexOf(\'uk\') !== -1 || cookie.indexOf(\'ua\') !== -1) {\r\n            lang = \'ua\';\r\n        }\r\n\r\n        console.log(&quot;FINAL ATTEMPT. Lang detected:&quot;, lang);\r\n\r\n        // Форсируем атрибуты для работы глобального CSS\r\n        const langAttr = lang === \'pl\' ? \'pl-pl\' : (lang === \'ua\' ? \'uk-ua\' : \'en-gb\');\r\n        document.documentElement.setAttribute(\'lang\', langAttr);\r\n        document.body.setAttribute(\'data-lang\', lang);\r\n\r\n        // Инъекция критического CSS для мгновенного показа\r\n        const styleId = \'garage-force-style\';\r\n        let style = document.getElementById(styleId);\r\n        if (!style) {\r\n            style = document.createElement(\'style\');\r\n            style.id = styleId;\r\n            document.head.appendChild(style);\r\n        }\r\n        style.innerHTML = `\r\n            .lang-block { display: none !important; }\r\n            .lang-${lang} { display: inline-block !important; }\r\n            div.lang-${lang} { display: block !important; }\r\n        `;\r\n\r\n        // Дублируем скрытие через перебор элементов (на случай задержек DOM)\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; el.style.setProperty(\'display\', \'none\', \'important\'));\r\n        document.querySelectorAll(\'.lang-\' + lang).forEach(el =&gt; {\r\n            const displayType = (el.tagName === \'SPAN\') ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n\r\n    // Тройной запуск для надежности на localhost\r\n    finalInfoTranslate();\r\n    setTimeout(finalInfoTranslate, 100);\r\n    setTimeout(finalInfoTranslate, 500);\r\n    \r\n    window.addEventListener(\'load\', finalInfoTranslate);\r\n})();\r\n&lt;/script&gt;\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И КОНТЕНТ */\r\n    #information-information {\r\n        background-color: #0d0d0d !important;\r\n        padding-top: 40px !important;\r\n        padding-bottom: 80px !important;\r\n        color: #eee !important;\r\n        min-height: 60vh;\r\n    }\r\n\r\n    /* 2.Breadcrumb не используется в дизайне Garage */\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 3. ЗАГОЛОВОК СТРАНИЦЫ */\r\n    h1.info-title {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 25px !important;\r\n        color: #fff !important;\r\n        margin-bottom: 30px;\r\n    }\r\n\r\n    /* 4. БОКС С КОНТЕНТОМ СТАТЬИ */\r\n    .info-content-box {\r\n        background: #111;\r\n        padding: 40px;\r\n        border: 1px solid #222;\r\n        border-top: 3px solid #ff0000;\r\n    }\r\n\r\n    .description-text { font-size: 1.1rem; line-height: 1.8; color: #ccc; }\r\n    .description-text strong { color: #ff0000 !important; }\r\n\r\n    /* 5. СТАТИЧЕСКИЕ ПРАВИЛА ПЕРЕВОДА (CSS) */\r\n    .lang-block { display: none !important; }\r\n\r\n    /* Мгновенная реакция на атрибут lang */\r\n    html[lang*=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n    html[lang*=&quot;pl&quot;] div.lang-pl { display: block !important; }\r\n\r\n    html[lang*=&quot;uk&quot;] .lang-ua, html[lang*=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n    html[lang*=&quot;uk&quot;] div.lang-ua, html[lang*=&quot;ua&quot;] div.lang-ua { display: block !important; }\r\n\r\n    html[lang*=&quot;en&quot;] .lang-en { display: inline-block !important; }\r\n    html[lang*=&quot;en&quot;] div.lang-en { display: block !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;information-information&quot; class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        {{ column_left }}\r\n        &lt;div id=&quot;content&quot; class=&quot;col&quot;&gt;\r\n            {{ content_top }}\r\n\r\n            &lt;h1 class=&quot;info-title&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;About Us&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Про нас&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;O nas&lt;/span&gt;\r\n            &lt;/h1&gt;\r\n\r\n            &lt;div class=&quot;info-content-box&quot;&gt;\r\n                &lt;div class=&quot;description-text&quot;&gt;\r\n                    {# Описание из базы данных (OpenCart отдает его на текущем языке системы) #}\r\n                    {{ description }}\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n\r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n        {{ column_right }}\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n{{ footer }}', 1, '2026-02-23 12:36:54'),
(9, 0, 'common/footer', '&lt;/main&gt;\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЕ СТИЛИ ФУТЕРА */\r\n    footer {\r\n        background-color: #0a0a0a !important;\r\n        border-top: 2px solid #ff0000 !important;\r\n        padding: 50px 0 30px !important;\r\n        margin-top: auto !important;\r\n        color: #888 !important;\r\n    }\r\n\r\n    footer h5 {\r\n        color: #ff0000 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 800;\r\n        font-size: 15px;\r\n        margin-bottom: 25px;\r\n        letter-spacing: 1px;\r\n    }\r\n\r\n    footer ul li { margin-bottom: 10px; }\r\n\r\n    footer ul li a {\r\n        color: #ccc !important;\r\n        text-decoration: none !important;\r\n        transition: 0.3s all ease;\r\n        font-size: 14px;\r\n        display: inline-block;\r\n    }\r\n\r\n    footer ul li a:hover {\r\n        color: #ff0000 !important;\r\n        padding-left: 5px;\r\n    }\r\n\r\n    /* 2. КАРТА */\r\n    .footer-map-container {\r\n        border: 1px solid #222;\r\n        line-height: 0;\r\n        overflow: hidden;\r\n        filter: grayscale(1) invert(0.9) contrast(1.2);\r\n        transition: 0.5s filter ease;\r\n    }\r\n\r\n    .footer-map-container:hover { filter: grayscale(0) invert(0) contrast(1); }\r\n\r\n    .footer-bottom {\r\n        border-top: 1px solid #222;\r\n        margin-top: 30px;\r\n        padding-top: 20px;\r\n        font-size: 12px;\r\n        color: #444;\r\n    }\r\n\r\n    /* 3. МГНОВЕННЫЙ ПЕРЕВОД (CSS ТРИГГЕРЫ) */\r\n    /* Прячем все блоки перевода по умолчанию */\r\n    .lang-block { display: none !important; }\r\n\r\n    /* Показываем нужный язык на основе атрибута lang в теге html */\r\n    html[lang*=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n    html[lang*=&quot;pl&quot;] div.lang-pl { display: block !important; }\r\n\r\n    html[lang*=&quot;uk&quot;] .lang-ua, html[lang*=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n    html[lang*=&quot;uk&quot;] div.lang-ua, html[lang*=&quot;ua&quot;] div.lang-ua { display: block !important; }\r\n\r\n    html[lang*=&quot;en&quot;] .lang-en { display: inline-block !important; }\r\n    html[lang*=&quot;en&quot;] div.lang-en { display: block !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;footer&gt;\r\n  &lt;div class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n\r\n      &lt;div class=&quot;col-md-3 col-sm-6 mb-4&quot;&gt;\r\n        &lt;h5&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Information&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Інформація&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Informacja&lt;/span&gt;\r\n        &lt;/h5&gt;\r\n        &lt;ul class=&quot;list-unstyled&quot;&gt;\r\n          &lt;li&gt;\r\n            &lt;a href=&quot;index.php?route=information/information&amp;information_id=1&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;About Us&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Про нас&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;O nas&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n          &lt;li&gt;\r\n            &lt;a href=&quot;{{ contact }}&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Contact Us&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Контакти&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Kontakt z nami&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n          &lt;li&gt;&lt;a href=&quot;{{ sitemap }}&quot;&gt;{{ text_sitemap }}&lt;/a&gt;&lt;/li&gt;\r\n        &lt;/ul&gt;\r\n      &lt;/div&gt;\r\n\r\n      &lt;div class=&quot;col-md-3 col-sm-6 mb-4&quot;&gt;\r\n        &lt;h5&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;My Account&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Мій кабінет&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Moje konto&lt;/span&gt;\r\n        &lt;/h5&gt;\r\n        &lt;ul class=&quot;list-unstyled&quot;&gt;\r\n          &lt;li&gt;\r\n            &lt;a href=&quot;{{ account }}&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Dashboard&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Особистий кабінет&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Moje konto&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n          &lt;li&gt;\r\n            &lt;a href=&quot;{{ order }}&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Order History&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Історія замовлень&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Historia zamówień&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n          &lt;li&gt;\r\n            &lt;a href=&quot;{{ wishlist }}&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Wish List&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Закладки&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Lista życzeń&lt;/span&gt;\r\n            &lt;/a&gt;\r\n          &lt;/li&gt;\r\n        &lt;/ul&gt;\r\n      &lt;/div&gt;\r\n\r\n      &lt;div class=&quot;col-md-6 col-sm-12 mb-4&quot;&gt;\r\n        &lt;h5&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Our Location&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Наша локація&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Nasza lokalizacja&lt;/span&gt;\r\n        &lt;/h5&gt;\r\n        &lt;div class=&quot;footer-map-container&quot;&gt;\r\n            &lt;iframe src=&quot;https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d2459.723653139886!2d16.591242315786193!3d51.84155107969145!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4705978939c4d9b7%3A0x7d0138939c4d9b7!2zSmFuYSBTdHlraSA4LCA2NC0xMDAgTGVzem5vLCBQb2xza2E!5e0!3m2!1spl!2spl!4v1645450000000!5m2!1spl!2spl&quot;\r\n                    width=&quot;100%&quot; height=&quot;150&quot; style=&quot;border:0;&quot; allowfullscreen=&quot;&quot; loading=&quot;lazy&quot;&gt;&lt;/iframe&gt;\r\n        &lt;/div&gt;\r\n        &lt;div style=&quot;margin-top: 15px; font-size: 13px; color: #fff;&quot;&gt;\r\n            &lt;p&gt;\r\n                &lt;i class=&quot;fa fa-map-marker&quot; style=&quot;color: #ff0000; width: 20px;&quot;&gt;&lt;/i&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Jana Styki 8, 64-100 Leszno, Poland&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Jana Styki 8, 64-100 Leszno, Poland&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Jana Styki 8, 64-100 Leszno, Polska&lt;/span&gt;\r\n            &lt;/p&gt;\r\n            &lt;p&gt;\r\n                &lt;i class=&quot;fa fa-phone&quot; style=&quot;color: #ff0000; width: 20px;&quot;&gt;&lt;/i&gt; +48 570 833 162\r\n            &lt;/p&gt;\r\n        &lt;/div&gt;\r\n      &lt;/div&gt;\r\n\r\n    &lt;/div&gt;\r\n\r\n    &lt;div class=&quot;footer-bottom&quot;&gt;\r\n      &lt;div class=&quot;row&quot;&gt;\r\n        &lt;div class=&quot;col-sm-6&quot;&gt;\r\n          CarServiceGarage © 2026.\r\n          &lt;span class=&quot;lang-block lang-en&quot;&gt;All rights reserved.&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-ua&quot;&gt;Всі права захищені.&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-pl&quot;&gt;Wszelkie prawa zastrzeżone.&lt;/span&gt;\r\n        &lt;/div&gt;\r\n        &lt;div class=&quot;col-sm-6 text-end&quot;&gt;\r\n          Powered By &lt;a href=&quot;http://www.opencart.com&quot; style=&quot;color: #444;&quot;&gt;OpenCart&lt;/a&gt;\r\n        &lt;/div&gt;\r\n      &lt;/div&gt;\r\n    &lt;/div&gt;\r\n  &lt;/div&gt;\r\n&lt;/footer&gt;\r\n\r\n&lt;script&gt;\r\n(function() {\r\n    function garageFinalTranslate() {\r\n        // 1. ПРИОРИТЕТЫ: URL &gt; HTML LANG &gt; COOKIE\r\n        const url = window.location.href.toLowerCase();\r\n        const htmlLang = document.documentElement.lang.toLowerCase();\r\n        const cookie = (document.cookie.match(\'(^|;)\\\\s*language\\\\s*=\\\\s*([^;]+)\') || [])[2] || \'\';\r\n        \r\n        let lang = \'en\';\r\n\r\n        // 2. Улучшенная логика определения (ищем подстроку, чтобы ловить и pl, и pl-pl)\r\n        if (url.includes(\'pl\') || htmlLang.includes(\'pl\') || cookie.includes(\'pl\')) {\r\n            lang = \'pl\';\r\n        } else if (url.includes(\'uk\') || url.includes(\'ua\') || htmlLang.includes(\'uk\') || htmlLang.includes(\'ua\') || cookie.includes(\'uk\') || cookie.includes(\'ua\')) {\r\n            lang = \'ua\';\r\n        }\r\n\r\n        // 3. ПРИНУДИТЕЛЬНОЕ ОБНОВЛЕНИЕ (форсируем атрибуты для CSS)\r\n        document.body.setAttribute(\'data-lang\', lang);\r\n        document.documentElement.setAttribute(\'lang\', lang === \'pl\' ? \'pl-pl\' : (lang === \'ua\' ? \'uk-ua\' : \'en-gb\'));\r\n\r\n        // 4. ОТОБРАЖЕНИЕ БЛОКОВ\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; {\r\n            el.style.setProperty(\'display\', \'none\', \'important\');\r\n        });\r\n\r\n        document.querySelectorAll(\'.lang-\' + lang).forEach(el =&gt; {\r\n            const displayType = (el.tagName === \'SPAN\' || el.tagName === \'I\') ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n\r\n    // 5. ПЕРЕХВАТ ПЕРЕКЛЮЧАТЕЛЯ (пишем куку вручную при клике на флаг)\r\n    document.addEventListener(\'click\', function(e) {\r\n        const langItem = e.target.closest(\'#form-language .dropdown-item\');\r\n        if (langItem) {\r\n            const code = langItem.getAttribute(\'href\');\r\n            document.cookie = &quot;language=&quot; + code + &quot;; path=/; max-age=&quot; + (30*24*60*60);\r\n        }\r\n    });\r\n\r\n    // Запуск на всех стадиях загрузки\r\n    garageFinalTranslate();\r\n    window.addEventListener(\'load\', garageFinalTranslate);\r\n    \r\n    // Следим за изменениями (важно для AJAX и переходов)\r\n    const observer = new MutationObserver(garageFinalTranslate);\r\n    observer.observe(document.body, { childList: true, subtree: true });\r\n})();\r\n&lt;/script&gt;\r\n&lt;/body&gt;\r\n&lt;/html&gt;', 1, '2026-02-23 12:43:14'),
(10, 0, 'account/register', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ОБЩИЙ ФОН СТРАНИЦЫ */\r\n    #account-register {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n    }\r\n\r\n    /* 2. ЗАГОЛОВКИ И ГРУППЫ ПОЛЕЙ */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 30px;\r\n    }\r\n\r\n    legend {\r\n        color: #ff0000 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 1.2rem;\r\n        text-transform: uppercase;\r\n        border-bottom: 1px solid #333;\r\n        padding-bottom: 10px;\r\n        margin-top: 20px;\r\n        margin-bottom: 20px;\r\n    }\r\n\r\n    /* 3. ИНПУТЫ И ФОРМЫ */\r\n    .form-control, .form-select {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #fff !important;\r\n        border-radius: 0 !important;\r\n        padding: 12px !important;\r\n    }\r\n\r\n    .form-control:focus, .form-select:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: none !important;\r\n    }\r\n\r\n    .col-form-label {\r\n        color: #aaa;\r\n        font-weight: bold;\r\n    }\r\n\r\n    /* 4. КНОПКА РЕГИСТРАЦИИ */\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 12px 30px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: bold;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: #cc0000 !important;\r\n        transform: scale(1.05);\r\n    }\r\n\r\n    /* 5. ИСПРАВЛЕНИЕ ПРАВОЙ ПАНЕЛИ (Сбоку) */\r\n    #column-right .list-group-item {\r\n        background-color: #111 !important;\r\n        border: 1px solid #222 !important;\r\n        color: #ccc !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    #column-right .list-group-item:hover {\r\n        border-color: #ff0000 !important;\r\n        color: #ff0000 !important;\r\n        background-color: #1a1a1a !important;\r\n    }\r\n\r\n    #column-right .list-group-item.active {\r\n        background-color: #ff0000 !important;\r\n        border-color: #ff0000 !important;\r\n        color: #fff !important;\r\n    }\r\n\r\n    /* 6. ПЕРЕКЛЮЧАТЕЛИ (Switch) */\r\n    .form-check-input:checked {\r\n        background-color: #ff0000 !important;\r\n        border-color: #ff0000 !important;\r\n    }\r\n\r\n    /* Прячем хлебные крошки */\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* МГНОВЕННЫЙ ПЕРЕВОД */\r\n    .lang-block { display: none; }\r\n    body[data-lang=&quot;pl&quot;] .lang-pl { display: inline; }\r\n    body[data-lang=&quot;ua&quot;] .lang-ua { display: inline; }\r\n    body[data-lang=&quot;en&quot;] .lang-en { display: inline; }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;account-register&quot; class=&quot;container&quot;&gt;\r\n  &lt;div class=&quot;row&quot;&gt;\r\n    {{ column_left }}\r\n    &lt;div id=&quot;content&quot; class=&quot;col&quot;&gt;\r\n      {{ content_top }}\r\n\r\n      &lt;h1&gt;\r\n          &lt;span class=&quot;lang-block lang-en&quot;&gt;Register Account&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-ua&quot;&gt;Реєстрація акаунта&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zarejestruj konto&lt;/span&gt;\r\n      &lt;/h1&gt;\r\n\r\n      &lt;p&gt;\r\n          &lt;span class=&quot;lang-block lang-en&quot;&gt;If you already have an account with us, please login at the &lt;a href=&quot;{{ login }}&quot; style=&quot;color:#ff0000;&quot;&gt;login page&lt;/a&gt;.&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-ua&quot;&gt;Якщо ви вже маєте акаунт, будь ласка, перейдіть на &lt;a href=&quot;{{ login }}&quot; style=&quot;color:#ff0000;&quot;&gt;сторінку входу&lt;/a&gt;.&lt;/span&gt;\r\n          &lt;span class=&quot;lang-block lang-pl&quot;&gt;Jeśli masz już u nas konto, zaloguj się na &lt;a href=&quot;{{ login }}&quot; style=&quot;color:#ff0000;&quot;&gt;stronie logowania&lt;/a&gt;.&lt;/span&gt;\r\n      &lt;/p&gt;\r\n\r\n      &lt;form id=&quot;form-register&quot; action=&quot;{{ register }}&quot; method=&quot;post&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n        &lt;fieldset id=&quot;account&quot;&gt;\r\n          &lt;legend&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;Your Personal Details&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;Ваші персональні дані&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twoje dane osobowe&lt;/span&gt;\r\n          &lt;/legend&gt;\r\n\r\n          {% if customer_groups|length &gt; 1 %}\r\n            &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n              &lt;label class=&quot;col-sm-2 col-form-label&quot;&gt;{{ entry_customer_group }}&lt;/label&gt;\r\n              &lt;div class=&quot;col-sm-10&quot;&gt;\r\n                &lt;select name=&quot;customer_group_id&quot; id=&quot;input-customer-group&quot; class=&quot;form-select&quot;&gt;\r\n                  {% for customer_group in customer_groups %}\r\n                    &lt;option value=&quot;{{ customer_group.customer_group_id }}&quot;{% if customer_group.customer_group_id == customer_group_id %} selected{% endif %}&gt;{{ customer_group.name }}&lt;/option&gt;\r\n                  {% endfor %}\r\n                &lt;/select&gt;\r\n              &lt;/div&gt;\r\n            &lt;/div&gt;\r\n          {% endif %}\r\n\r\n          &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n            &lt;label for=&quot;input-firstname&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;First Name&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Ім\'я&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Imię&lt;/span&gt;\r\n            &lt;/label&gt;\r\n            &lt;div class=&quot;col-sm-10&quot;&gt;\r\n              &lt;input type=&quot;text&quot; name=&quot;firstname&quot; value=&quot;&quot; placeholder=&quot;...&quot; id=&quot;input-firstname&quot; class=&quot;form-control&quot;/&gt;\r\n              &lt;div id=&quot;error-firstname&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n          &lt;/div&gt;\r\n\r\n          &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n            &lt;label for=&quot;input-lastname&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Last Name&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Прізвище&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Nazwisko&lt;/span&gt;\r\n            &lt;/label&gt;\r\n            &lt;div class=&quot;col-sm-10&quot;&gt;\r\n              &lt;input type=&quot;text&quot; name=&quot;lastname&quot; value=&quot;&quot; placeholder=&quot;...&quot; id=&quot;input-lastname&quot; class=&quot;form-control&quot;/&gt;\r\n              &lt;div id=&quot;error-lastname&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n          &lt;/div&gt;\r\n\r\n          &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n            &lt;label for=&quot;input-email&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;E-Mail&lt;/label&gt;\r\n            &lt;div class=&quot;col-sm-10&quot;&gt;\r\n              &lt;input type=&quot;email&quot; name=&quot;email&quot; value=&quot;&quot; placeholder=&quot;example@mail.com&quot; id=&quot;input-email&quot; class=&quot;form-control&quot;/&gt;\r\n              &lt;div id=&quot;error-email&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n          &lt;/div&gt;\r\n\r\n          {% if config_telephone_display %}\r\n            &lt;div class=&quot;row mb-3{% if config_telephone_required %} required{% endif %}&quot;&gt;\r\n              &lt;label for=&quot;input-telephone&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                  &lt;span class=&quot;lang-block lang-en&quot;&gt;Telephone&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-ua&quot;&gt;Телефон&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-pl&quot;&gt;Telefon&lt;/span&gt;\r\n              &lt;/label&gt;\r\n              &lt;div class=&quot;col-sm-10&quot;&gt;\r\n                &lt;input type=&quot;tel&quot; name=&quot;telephone&quot; value=&quot;&quot; placeholder=&quot;+48 ...&quot; id=&quot;input-telephone&quot; class=&quot;form-control&quot;/&gt;\r\n                &lt;div id=&quot;error-telephone&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n              &lt;/div&gt;\r\n            &lt;/div&gt;\r\n          {% endif %}\r\n        &lt;/fieldset&gt;\r\n\r\n        &lt;fieldset&gt;\r\n          &lt;legend&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;Your Password&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;Ваш пароль&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twoje hasło&lt;/span&gt;\r\n          &lt;/legend&gt;\r\n          &lt;div class=&quot;row mb-3 required&quot;&gt;\r\n            &lt;label for=&quot;input-password&quot; class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Password&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Пароль&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Hasło&lt;/span&gt;\r\n            &lt;/label&gt;\r\n            &lt;div class=&quot;col-sm-10&quot;&gt;\r\n              &lt;input type=&quot;password&quot; name=&quot;password&quot; value=&quot;&quot; placeholder=&quot;******&quot; id=&quot;input-password&quot; class=&quot;form-control&quot;/&gt;\r\n              &lt;div id=&quot;error-password&quot; class=&quot;invalid-feedback&quot;&gt;&lt;/div&gt;\r\n            &lt;/div&gt;\r\n          &lt;/div&gt;\r\n        &lt;/fieldset&gt;\r\n\r\n        &lt;fieldset&gt;\r\n          &lt;legend&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;Newsletter&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;Розсилка&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;Biuletyn&lt;/span&gt;\r\n          &lt;/legend&gt;\r\n          &lt;div class=&quot;row mb-3&quot;&gt;\r\n            &lt;label class=&quot;col-sm-2 col-form-label&quot;&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Subscribe&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Підписатися&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Subskrybuj&lt;/span&gt;\r\n            &lt;/label&gt;\r\n            &lt;div class=&quot;col-sm-10&quot;&gt;\r\n              &lt;div class=&quot;form-check form-switch form-switch-lg&quot;&gt;\r\n                &lt;input type=&quot;hidden&quot; name=&quot;newsletter&quot; value=&quot;0&quot;/&gt;\r\n                &lt;input type=&quot;checkbox&quot; name=&quot;newsletter&quot; value=&quot;1&quot; id=&quot;input-newsletter&quot; class=&quot;form-check-input&quot;/&gt;\r\n              &lt;/div&gt;\r\n            &lt;/div&gt;\r\n          &lt;/div&gt;\r\n        &lt;/fieldset&gt;\r\n\r\n        {{ captcha }}\r\n\r\n        &lt;div class=&quot;text-end&quot; style=&quot;margin-top: 30px;&quot;&gt;\r\n          {% if text_agree %}\r\n            &lt;div class=&quot;form-check form-switch form-switch-lg form-check-reverse form-check-inline&quot;&gt;\r\n              &lt;label class=&quot;form-check-label&quot; style=&quot;color:#aaa; font-size: 0.9rem;&quot;&gt;{{ text_agree }}&lt;/label&gt;\r\n              &lt;input type=&quot;checkbox&quot; name=&quot;agree&quot; value=&quot;1&quot; class=&quot;form-check-input&quot;/&gt;\r\n            &lt;/div&gt;\r\n          {% endif %}\r\n          &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n              &lt;span class=&quot;lang-block lang-en&quot;&gt;Continue&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-ua&quot;&gt;Продовжити&lt;/span&gt;\r\n              &lt;span class=&quot;lang-block lang-pl&quot;&gt;Kontynuuj&lt;/span&gt;\r\n          &lt;/button&gt;\r\n        &lt;/div&gt;\r\n      &lt;/form&gt;\r\n\r\n      {{ content_bottom }}\r\n    &lt;/div&gt;\r\n\r\n    &lt;div id=&quot;column-right&quot; class=&quot;col-md-4 d-none d-md-block ms-auto&quot;&gt;\r\n    {{ column_right }}\r\n    &lt;/div&gt;\r\n  &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script type=&quot;text/javascript&quot;&gt;&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-23 14:01:36'),
(11, 0, 'account/account', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СТРУКТУРА */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-account {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n        min-height: 75vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВКИ СЕКЦИЙ */\r\n    h1, h2 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 25px;\r\n        margin-top: 35px;\r\n        font-size: 1.4rem;\r\n    }\r\n\r\n    /* 3. КАРТОЧКИ-КНОПКИ */\r\n    .account-link-list {\r\n        padding: 0;\r\n        margin-bottom: 40px;\r\n        display: grid;\r\n        grid-template-columns: 1fr 1fr;\r\n        gap: 15px;\r\n    }\r\n\r\n    .account-link-list li { list-style: none; }\r\n\r\n    .account-link-list li a {\r\n        display: flex;\r\n        align-items: center;\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 18px 20px;\r\n        color: #ccc;\r\n        text-decoration: none;\r\n        text-transform: uppercase;\r\n        font-size: 11px;\r\n        letter-spacing: 1px;\r\n        transition: 0.3s all ease;\r\n        border-left: 3px solid transparent;\r\n        height: 100%;\r\n    }\r\n\r\n    .account-link-list li a:hover {\r\n        background: #1a1a1a;\r\n        color: #ff0000;\r\n        border-left: 3px solid #ff0000;\r\n        padding-left: 25px;\r\n    }\r\n\r\n    /* 4. ПРАВАЯ ЧАСТЬ С ЛОГОТИПОМ */\r\n    .account-sidebar-logo {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        height: 100%;\r\n        padding-left: 40px;\r\n    }\r\n\r\n    .account-sidebar-logo img {\r\n        max-width: 100%;\r\n        height: auto;\r\n        filter: drop-shadow(0 0 15px rgba(255, 0, 0, 0.2));\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .account-sidebar-logo img:hover {\r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 0.5));\r\n        transform: scale(1.03);\r\n    }\r\n\r\n    /* 5. ЛОГИКА ПЕРЕВОДА */\r\n    .lang-block { display: none !important; }\r\n    body[data-lang=&quot;pl&quot;] .lang-pl { display: inline-block !important; }\r\n    body[data-lang=&quot;ua&quot;] .lang-ua { display: inline-block !important; }\r\n    body[data-lang=&quot;en&quot;] .lang-en { display: inline-block !important; }\r\n    \r\n    body[data-lang=&quot;pl&quot;] div.lang-pl { display: block !important; }\r\n    body[data-lang=&quot;ua&quot;] div.lang-ua { display: block !important; }\r\n    body[data-lang=&quot;en&quot;] div.lang-en { display: block !important; }\r\n\r\n    @media (max-width: 991px) {\r\n        .account-link-list { grid-template-columns: 1fr; }\r\n        .account-sidebar-logo { display: none; }\r\n    }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-account&quot; class=&quot;container&quot;&gt;\r\n        {% if success %}\r\n            &lt;div class=&quot;alert alert-success alert-dismissible&quot;&gt;&lt;i class=&quot;fa-solid fa-circle-check&quot;&gt;&lt;/i&gt; {{ success }}&lt;/div&gt;\r\n        {% endif %}\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7 col-md-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;My Account&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Мій Акаунт&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Moje Konto&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;ul class=&quot;account-link-list&quot;&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ edit }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Edit account&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Редагувати акаунт&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Edytuj konto&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ password }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Password&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Пароль&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Hasło&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ payment_method }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Payments&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Оплати&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Płatności&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ wishlist }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Wish list&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Список бажань&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Lista życzeń&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                &lt;/ul&gt;\r\n\r\n                &lt;h2&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;My Orders&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Мої Замовлення&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Moje Zamówienia&lt;/span&gt;\r\n                &lt;/h2&gt;\r\n                &lt;ul class=&quot;account-link-list&quot;&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ order }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Order history&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Історія замовлень&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Historia zamówień&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ subscription }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Subscriptions&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Передплати&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Subskrypcje&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ download }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Downloads&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Завантаження&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Pliki do pobrania&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ return }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Returns&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Повернення&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Zwроty&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                    &lt;li&gt;&lt;a href=&quot;{{ transaction }}&quot;&gt;&lt;span class=&quot;lang-block lang-en&quot;&gt;Transactions&lt;/span&gt;&lt;span class=&quot;lang-block lang-ua&quot;&gt;Транзакції&lt;/span&gt;&lt;span class=&quot;lang-block lang-pl&quot;&gt;Transakcje&lt;/span&gt;&lt;/a&gt;&lt;/li&gt;\r\n                &lt;/ul&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center&quot;&gt;\r\n                &lt;div class=&quot;account-sidebar-logo&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; title=&quot;CarServiceGarage&quot; alt=&quot;CarServiceGarage&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script&gt;\r\n(function() {\r\n    function refreshAccountLang() {\r\n        const activeLang = document.body.getAttribute(\'data-lang\') || \'en\';\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; el.style.setProperty(\'display\', \'none\', \'important\'));\r\n        document.querySelectorAll(\'.lang-\' + activeLang).forEach(el =&gt; {\r\n            const displayType = (el.tagName === \'SPAN\') ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n    refreshAccountLang();\r\n    setTimeout(refreshAccountLang, 250);\r\n})();\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 14:58:47');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(12, 0, 'account/login', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СЕТКА */\r\n    #account-login {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 60px;\r\n        padding-bottom: 100px;\r\n        min-height: 80vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    .login-wrapper {\r\n        max-width: 1000px;\r\n        margin: 0 auto;\r\n    }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 40px;\r\n    }\r\n\r\n    /* 3. КАРТОЧКИ */\r\n    .login-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 40px;\r\n        height: 100%;\r\n        display: flex;\r\n        flex-direction: column;\r\n        justify-content: space-between;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .login-card:hover { border-color: #444; }\r\n\r\n    .login-card strong {\r\n        color: #ff0000;\r\n        text-transform: uppercase;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        display: block;\r\n        margin-bottom: 20px;\r\n        font-size: 1.2rem;\r\n    }\r\n\r\n    /* 4. ПОЛЯ ВВОДА */\r\n    .form-control {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #fff !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px !important;\r\n    }\r\n\r\n    .form-control:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: 0 0 10px rgba(255, 0, 0, 0.2) !important;\r\n    }\r\n\r\n    /* 5. КНОПКИ */\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 15px 30px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        width: 100%;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: #fff !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    /* 6. УВЕДОМЛЕНИЕ ОБ ОШИБКЕ (Garage Style) */\r\n    /* Мы показываем его, только если в URL или в системе есть ошибка */\r\n    .garage-error-alert {\r\n        background: #ff0000;\r\n        color: #fff;\r\n        padding: 20px;\r\n        margin-bottom: 30px;\r\n        border: 2px solid #fff;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        box-shadow: 0 0 20px rgba(255, 0, 0, 0.4);\r\n        display: none; /* Управляется через Твиг ниже */\r\n    }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;account-login&quot; class=&quot;container&quot;&gt;\r\n    &lt;div class=&quot;login-wrapper&quot;&gt;\r\n        \r\n        {# БЛОК ОШИБКИ: Показывается только если сервер прислал warning #}\r\n        &lt;div id=&quot;error-alert&quot; class=&quot;garage-error-alert&quot; {% if error_warning %}style=&quot;display: block;&quot;{% endif %}&gt;\r\n            &lt;i class=&quot;fa-solid fa-triangle-exclamation&quot; style=&quot;margin-right: 15px;&quot;&gt;&lt;/i&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Warning: No match for E-Mail and/or Password.&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Помилка: Неправильний e-mail або пароль.&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Błąd: Nieprawidłowy e-mail lub hasło.&lt;/span&gt;\r\n        &lt;/div&gt;\r\n\r\n        {# УСПЕШНАЯ РЕГИСТРАЦИЯ #}\r\n        {% if success %}\r\n            &lt;div class=&quot;alert alert-success&quot; style=&quot;background:#111; border-left:4px solid #00ff00; color:#fff; border-radius:0;&quot;&gt;\r\n                &lt;i class=&quot;fa-solid fa-check-circle&quot; style=&quot;color:#00ff00; margin-right:10px;&quot;&gt;&lt;/i&gt; {{ success }}\r\n            &lt;/div&gt;\r\n        {% endif %}\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Account Login&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Вхід в акаунт&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Logowanie&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;row g-4&quot;&gt;\r\n                    &lt;div class=&quot;col-md-6&quot;&gt;\r\n                        &lt;div class=&quot;login-card&quot;&gt;\r\n                            &lt;div&gt;\r\n                                &lt;strong&gt;\r\n                                    &lt;span class=&quot;lang-block lang-en&quot;&gt;New Customer&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Новий клієнт&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Nowy klient&lt;/span&gt;\r\n                                &lt;/strong&gt;\r\n                                &lt;p style=&quot;color: #888; font-size: 0.95rem; line-height: 1.6;&quot;&gt;\r\n                                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Registering allows you to shop faster and track your order status.&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Реєстрація дозволить вам купувати швидше та відстежувати статус замовлень.&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Rejestracja pozwala na szybsze zakupy и śledzenie statusu zamówień.&lt;/span&gt;\r\n                                &lt;/p&gt;\r\n                            &lt;/div&gt;\r\n                            &lt;a href=&quot;{{ register }}&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Register&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Реєстрація&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zarejestruj się&lt;/span&gt;\r\n                            &lt;/a&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n\r\n                    &lt;div class=&quot;col-md-6&quot;&gt;\r\n                        &lt;div class=&quot;login-card&quot;&gt;\r\n                            {# Используем стандартный AJAX OC4, но наш футер все переведет автоматически #}\r\n                            &lt;form action=&quot;{{ login }}&quot; method=&quot;post&quot; id=&quot;form-login&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n                                &lt;strong&gt;\r\n                                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Returning Customer&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Постійний клієнт&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Stały klient&lt;/span&gt;\r\n                                &lt;/strong&gt;\r\n                                \r\n                                &lt;div class=&quot;mb-3&quot;&gt;\r\n                                    &lt;label class=&quot;form-label&quot; style=&quot;font-size:12px; color:#666; text-transform:uppercase;&quot;&gt;E-mail&lt;/label&gt;\r\n                                    &lt;input type=&quot;text&quot; name=&quot;email&quot; value=&quot;{{ email }}&quot; placeholder=&quot;Email&quot; class=&quot;form-control&quot; /&gt;\r\n                                &lt;/div&gt;\r\n                                \r\n                                &lt;div class=&quot;mb-3&quot;&gt;\r\n                                    &lt;label class=&quot;form-label&quot; style=&quot;font-size:12px; color:#666; text-transform:uppercase;&quot;&gt;\r\n                                        &lt;span class=&quot;lang-block lang-en&quot;&gt;Password&lt;/span&gt;\r\n                                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;Пароль&lt;/span&gt;\r\n                                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Hasło&lt;/span&gt;\r\n                                    &lt;/label&gt;\r\n                                    &lt;input type=&quot;password&quot; name=&quot;password&quot; value=&quot;{{ password }}&quot; placeholder=&quot;...&quot; class=&quot;form-control&quot; /&gt;\r\n                                    \r\n                                    &lt;div class=&quot;text-end mt-2&quot;&gt;\r\n                                        &lt;a href=&quot;{{ forgotten }}&quot; style=&quot;color: #ff0000; font-size: 11px; text-transform: uppercase; text-decoration: none; font-weight: bold;&quot;&gt;\r\n                                            &lt;span class=&quot;lang-block lang-en&quot;&gt;Forgotten Password?&lt;/span&gt;\r\n                                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Забули пароль?&lt;/span&gt;\r\n                                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zapomniałeś hasła?&lt;/span&gt;\r\n                                        &lt;/a&gt;\r\n                                    &lt;/div&gt;\r\n                                &lt;/div&gt;\r\n                                \r\n                                &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Login&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Увійти&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zaloguj się&lt;/span&gt;\r\n                                &lt;/button&gt;\r\n                                \r\n                                {% if redirect %}\r\n                                    &lt;input type=&quot;hidden&quot; name=&quot;redirect&quot; value=&quot;{{ redirect }}&quot; /&gt;\r\n                                {% endif %}\r\n                            &lt;/form&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/div&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n{# Скрипт-адаптер для AJAX-ответов OpenCart 4 #}\r\n&lt;script&gt;\r\n$(document).on(\'ajaxComplete\', function(e, xhr, settings) {\r\n    if (settings.url.indexOf(\'route=account/login\') !== -1) {\r\n        try {\r\n            const res = JSON.parse(xhr.responseText);\r\n            if (res.error &amp;&amp; res.error.warning) {\r\n                $(\'#error-alert\').fadeIn();\r\n            }\r\n            if (res.redirect) {\r\n                location = res.redirect;\r\n            }\r\n        } catch (err) {}\r\n    }\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-23 23:03:17'),
(13, 0, 'account/forgotten', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* Фикс для того, чтобы контент не залезал под хедер */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-forgotten {\r\n        color: #eee !important;\r\n        padding-top: 80px;\r\n        padding-bottom: 100px;\r\n        min-height: 70vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    .forgotten-wrapper {\r\n        max-width: 600px;\r\n        margin: 0 auto;\r\n    }\r\n\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 35px;\r\n        font-size: 26px;\r\n    }\r\n\r\n    .forgotten-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 40px;\r\n        border-top: 3px solid #ff0000;\r\n    }\r\n\r\n    .form-control {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #fff !important;\r\n        border-radius: 0 !important;\r\n        padding: 15px !important;\r\n        margin-bottom: 15px;\r\n    }\r\n\r\n    .form-control:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: 0 0 10px rgba(255, 0, 0, 0.3) !important;\r\n    }\r\n\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 16px 30px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        width: 100%;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: #fff !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    .btn-back {\r\n        background: transparent;\r\n        color: #666;\r\n        border: 1px solid #333;\r\n        text-align: center;\r\n        padding: 12px;\r\n        text-decoration: none;\r\n        text-transform: uppercase;\r\n        font-size: 12px;\r\n        margin-top: 20px;\r\n        display: block;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-back:hover {\r\n        color: #fff;\r\n        border-color: #666;\r\n    }\r\n\r\n    /* Стиль ошибки */\r\n    #garage-error {\r\n        display: none;\r\n        background: #ff0000;\r\n        color: #fff;\r\n        padding: 20px;\r\n        margin-bottom: 25px;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: bold;\r\n        border: 1px solid #fff;\r\n    }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-forgotten&quot; class=&quot;container&quot;&gt;\r\n        &lt;div class=&quot;forgotten-wrapper&quot;&gt;\r\n\r\n            &lt;div id=&quot;garage-error&quot;&gt;\r\n                &lt;i class=&quot;fa-solid fa-triangle-exclamation&quot; style=&quot;margin-right: 15px;&quot;&gt;&lt;/i&gt;\r\n                &lt;span class=&quot;lang-block lang-en&quot;&gt;Warning: E-Mail Address was not found!&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Помилка: E-Mail не знайдено в базі!&lt;/span&gt;\r\n                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Błąd: Nie znaleziono adresu E-Mail!&lt;/span&gt;\r\n            &lt;/div&gt;\r\n\r\n            &lt;div id=&quot;content&quot;&gt;\r\n                {{ content_top }}\r\n\r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Forgotten Password&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Забули пароль?&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zapomniałeś hasła?&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;forgotten-card&quot;&gt;\r\n                    &lt;form action=&quot;{{ confirm }}&quot; method=&quot;post&quot; id=&quot;form-forgotten&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n                        &lt;p style=&quot;color:#888; margin-bottom: 25px; font-size: 14px; line-height: 1.6;&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;Enter your e-mail address. We will send you a reset link.&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Введіть ваш e-mail. Ми надішлемо вам посилання для скидання.&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Wprowadź swój e-mail. Wyślemy Ci link do resetowania.&lt;/span&gt;\r\n                        &lt;/p&gt;\r\n\r\n                        &lt;div class=&quot;mb-3&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot; style=&quot;color:#555; font-size:11px; text-transform:uppercase; letter-spacing:1px;&quot;&gt;E-Mail Address&lt;/label&gt;\r\n                            &lt;input type=&quot;email&quot; name=&quot;email&quot; value=&quot;&quot; placeholder=&quot;example@mail.com&quot; id=&quot;input-email&quot; class=&quot;form-control&quot; required autofocus /&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;Reset Password&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Скинути пароль&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Resetuj hasło&lt;/span&gt;\r\n                        &lt;/button&gt;\r\n                        \r\n                        &lt;a href=&quot;{{ back }}&quot; class=&quot;btn btn-back&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;Return to Login&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Назад до входу&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Powrót do logowania&lt;/span&gt;\r\n                        &lt;/a&gt;\r\n                    &lt;/form&gt;\r\n                &lt;/div&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script&gt;\r\n$(document).on(\'ajaxComplete\', function(e, xhr, settings) {\r\n    if (settings.url.indexOf(\'route=account/forgotten\') !== -1) {\r\n        try {\r\n            const res = JSON.parse(xhr.responseText);\r\n            if (res.error &amp;&amp; res.error.warning) {\r\n                $(\'#garage-error\').fadeIn();\r\n            }\r\n            if (res.redirect) {\r\n                location = res.redirect;\r\n            }\r\n        } catch (err) {}\r\n    }\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-23 23:12:33'),
(14, 0, 'account/edit', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СТРУКТУРА */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-edit {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n        min-height: 75vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 35px;\r\n        font-size: 1.6rem;\r\n    }\r\n\r\n    /* 3. КАРТОЧКА ФОРМЫ */\r\n    .edit-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 40px;\r\n        border-top: 3px solid #ff0000;\r\n    }\r\n\r\n    .form-group { margin-bottom: 20px; }\r\n\r\n    .form-label {\r\n        color: #888;\r\n        text-transform: uppercase;\r\n        font-size: 11px;\r\n        letter-spacing: 1px;\r\n        margin-bottom: 8px;\r\n        display: block;\r\n    }\r\n\r\n    /* 4. ПОЛЯ ВВОДА */\r\n    .form-control {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #fff !important;\r\n        border-radius: 0 !important;\r\n        padding: 12px 15px !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .form-control:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: 0 0 10px rgba(255, 0, 0, 0.2) !important;\r\n    }\r\n\r\n    /* 5. КНОПКИ */\r\n    .buttons {\r\n        margin-top: 30px;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 20px;\r\n    }\r\n\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: 2px solid #ff0000 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        color: #fff !important;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: transparent !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    .btn-back-custom {\r\n        background: transparent !important;\r\n        border: 2px solid #333 !important;\r\n        color: #666 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        font-size: 13px;\r\n        text-decoration: none !important;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        transition: 0.3s all ease;\r\n        letter-spacing: 1px;\r\n    }\r\n\r\n    .btn-back-custom i {\r\n        margin-right: 10px;\r\n        font-size: 14px;\r\n    }\r\n\r\n    .btn-back-custom:hover {\r\n        border-color: #fff !important;\r\n        background-color: #fff !important;\r\n        color: #000 !important;\r\n        transform: translateY(-2px);\r\n    }\r\n\r\n    /* 6. УВЕДОМЛЕНИЯ */\r\n    .alert-garage {\r\n        border-radius: 0 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-size: 13px;\r\n        padding: 15px 20px;\r\n        margin-bottom: 25px;\r\n        border: none !important;\r\n        display: none;\r\n    }\r\n\r\n    .alert-garage-error { background: #ff0000 !important; color: #fff !important; border-left: 5px solid #fff !important; }\r\n    .alert-garage-success { background: #28a745 !important; color: #fff !important; border-left: 5px solid #fff !important; }\r\n\r\n    .text-danger {\r\n        color: #ff0000 !important;\r\n        font-size: 11px;\r\n        text-transform: uppercase;\r\n        margin-top: 5px;\r\n    }\r\n\r\n    /* 7. ЛОГОТИП СПРАВА (С ЭФФЕКТОМ ГОРЕНИЯ) */\r\n    .edit-sidebar-logo {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        height: 100%;\r\n        padding-left: 40px;\r\n    }\r\n\r\n    .edit-sidebar-logo img {\r\n        max-width: 100%;\r\n        height: auto;\r\n        filter: drop-shadow(0 0 15px rgba(255, 0, 0, 0.2));\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .edit-sidebar-logo img:hover {\r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 0.5));\r\n        transform: scale(1.03);\r\n    }\r\n\r\n    .lang-block { display: none !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-edit&quot; class=&quot;container&quot;&gt;\r\n        &lt;div id=&quot;alert-error&quot; class=&quot;alert alert-garage alert-garage-error&quot;&gt;\r\n            &lt;i class=&quot;fa-solid fa-triangle-exclamation&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Error: Please check the form!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Помилка: Перевірте дані!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Błąd: Sprawdź formularz!&lt;/span&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div id=&quot;alert-success&quot; class=&quot;alert alert-garage alert-garage-success&quot;&gt;\r\n            &lt;i class=&quot;fa-solid fa-circle-check&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Success: Updated!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Успіх: Оновлено!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Sukces: Zaktualizowano!&lt;/span&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7 col-md-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Edit Profile&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Редагувати профіль&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Edytuj profil&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;edit-card&quot;&gt;\r\n                    &lt;form action=&quot;{{ save }}&quot; method=&quot;post&quot; id=&quot;form-edit&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;{{ entry_firstname }}&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;firstname&quot; value=&quot;{{ firstname }}&quot; id=&quot;input-firstname&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-firstname&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;{{ entry_lastname }}&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;lastname&quot; value=&quot;{{ lastname }}&quot; id=&quot;input-lastname&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-lastname&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;E-Mail&lt;/label&gt;\r\n                            &lt;input type=&quot;email&quot; name=&quot;email&quot; value=&quot;{{ email }}&quot; id=&quot;input-email&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-email&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;{{ entry_telephone }}&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;telephone&quot; value=&quot;{{ telephone }}&quot; id=&quot;input-telephone&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-telephone&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;buttons&quot;&gt;\r\n                            &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Save&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Зберегти&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zapisz&lt;/span&gt;\r\n                            &lt;/button&gt;\r\n                            \r\n                            &lt;a href=&quot;{{ back }}&quot; class=&quot;btn-back-custom&quot;&gt;\r\n                                &lt;i class=&quot;fa-solid fa-arrow-left&quot;&gt;&lt;/i&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Back&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Назад&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Powrót&lt;/span&gt;\r\n                            &lt;/a&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/form&gt;\r\n                &lt;/div&gt;\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center&quot;&gt;\r\n                &lt;div class=&quot;edit-sidebar-logo&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; alt=&quot;Logo&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script&gt;\r\n$(document).on(\'ajaxComplete\', function(e, xhr, settings) {\r\n    if (settings.url.indexOf(\'route=account/edit\') !== -1) {\r\n        try {\r\n            const res = JSON.parse(xhr.responseText);\r\n            $(\'.alert-garage\').fadeOut(100);\r\n            $(\'.text-danger\').empty();\r\n\r\n            if (res.error) {\r\n                if (res.error.warning) $(\'#alert-error\').fadeIn();\r\n                for (let i in res.error) $(\'#error-\' + i).html(res.error[i]);\r\n            }\r\n            if (res.success) $(\'#alert-success\').fadeIn();\r\n        } catch (err) {}\r\n    }\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 10:32:38'),
(15, 0, 'account/password', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СТРУКТУРА */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-password {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n        min-height: 75vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 35px;\r\n        font-size: 1.6rem;\r\n    }\r\n\r\n    /* 3. КАРТОЧКА ФОРМЫ */\r\n    .password-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 40px;\r\n        border-top: 3px solid #ff0000;\r\n    }\r\n\r\n    .form-group { margin-bottom: 25px; }\r\n\r\n    .form-label {\r\n        color: #888;\r\n        text-transform: uppercase;\r\n        font-size: 11px;\r\n        letter-spacing: 1px;\r\n        margin-bottom: 8px;\r\n        display: block;\r\n    }\r\n\r\n    /* 4. ПОЛЯ ВВОДА */\r\n    .form-control {\r\n        background-color: #1a1a1a !important;\r\n        border: 1px solid #333 !important;\r\n        color: #fff !important;\r\n        border-radius: 0 !important;\r\n        padding: 12px 15px !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .form-control:focus {\r\n        border-color: #ff0000 !important;\r\n        box-shadow: 0 0 10px rgba(255, 0, 0, 0.2) !important;\r\n    }\r\n\r\n    /* 5. КНОПКИ */\r\n    .buttons {\r\n        margin-top: 30px;\r\n        display: flex;\r\n        align-items: center;\r\n        gap: 20px;\r\n    }\r\n\r\n    .btn-primary {\r\n        background-color: #ff0000 !important;\r\n        border: 2px solid #ff0000 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        color: #fff !important;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .btn-primary:hover {\r\n        background-color: transparent !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    .btn-back-custom {\r\n        background: transparent !important;\r\n        border: 2px solid #333 !important;\r\n        color: #666 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        font-size: 13px;\r\n        text-decoration: none !important;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .btn-back-custom:hover {\r\n        border-color: #fff !important;\r\n        background-color: #fff !important;\r\n        color: #000 !important;\r\n        transform: translateY(-2px);\r\n    }\r\n\r\n    /* 6. УВЕДОМЛЕНИЯ */\r\n    .alert-garage {\r\n        border-radius: 0 !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-size: 13px;\r\n        padding: 15px 20px;\r\n        margin-bottom: 25px;\r\n        display: none;\r\n    }\r\n\r\n    .alert-garage-error { background: #ff0000 !important; color: #fff !important; border-left: 5px solid #fff !important; }\r\n    .alert-garage-success { background: #28a745 !important; color: #fff !important; border-left: 5px solid #fff !important; }\r\n\r\n    .text-danger {\r\n        color: #ff0000 !important;\r\n        font-size: 11px;\r\n        text-transform: uppercase;\r\n        margin-top: 5px;\r\n    }\r\n\r\n    /* 7. ЛОГОТИП СПРАВА С ЭФФЕКТОМ */\r\n    .password-sidebar-logo {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        height: 100%;\r\n        padding-left: 40px;\r\n    }\r\n\r\n    .password-sidebar-logo img {\r\n        max-width: 100%;\r\n        height: auto;\r\n        filter: drop-shadow(0 0 15px rgba(255, 0, 0, 0.2));\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .password-sidebar-logo img:hover {\r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 0.5));\r\n        transform: scale(1.03);\r\n    }\r\n\r\n    .lang-block { display: none !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-password&quot; class=&quot;container&quot;&gt;\r\n        \r\n        &lt;div id=&quot;alert-error&quot; class=&quot;alert alert-garage alert-garage-error&quot;&gt;\r\n            &lt;i class=&quot;fa-solid fa-triangle-exclamation&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Error: Please check the passwords!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Помилка: Перевірте введені паролі!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Błąd: Sprawdź wprowadzone hasła!&lt;/span&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div id=&quot;alert-success&quot; class=&quot;alert alert-garage alert-garage-success&quot;&gt;\r\n            &lt;i class=&quot;fa-solid fa-circle-check&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n            &lt;span class=&quot;lang-block lang-en&quot;&gt;Success: Password changed!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Успіх: Пароль змінено!&lt;/span&gt;\r\n            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Sukces: Hasło zostało zmienione!&lt;/span&gt;\r\n        &lt;/div&gt;\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7 col-md-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Change Password&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Змінити пароль&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Zmień hasło&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;password-card&quot;&gt;\r\n                    &lt;form action=&quot;{{ save }}&quot; method=&quot;post&quot; id=&quot;form-password&quot; data-oc-toggle=&quot;ajax&quot;&gt;\r\n                        \r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Password&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Пароль&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Hasło&lt;/span&gt;\r\n                            &lt;/label&gt;\r\n                            &lt;input type=&quot;password&quot; name=&quot;password&quot; value=&quot;{{ password }}&quot; id=&quot;input-password&quot; class=&quot;form-control&quot; placeholder=&quot;******&quot; /&gt;\r\n                            &lt;div id=&quot;error-password&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                \r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Password Confirm&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Підтвердження пароля&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Potwierdź hasło&lt;/span&gt;\r\n                            &lt;/label&gt;\r\n                            &lt;input type=&quot;password&quot; name=&quot;confirm&quot; value=&quot;{{ confirm }}&quot; id=&quot;input-confirm&quot; class=&quot;form-control&quot; placeholder=&quot;******&quot; /&gt;\r\n                            &lt;div id=&quot;error-confirm&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                \r\n                        &lt;div class=&quot;buttons&quot;&gt;\r\n                            &lt;button type=&quot;submit&quot; class=&quot;btn btn-primary&quot;&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Update&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Оновити&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Aktualizuj&lt;/span&gt;\r\n                            &lt;/button&gt;\r\n                            \r\n                            &lt;a href=&quot;{{ back }}&quot; class=&quot;btn-back-custom&quot;&gt;\r\n                                &lt;i class=&quot;fa-solid fa-arrow-left&quot;&gt;&lt;/i&gt;\r\n                                &lt;span class=&quot;lang-block lang-en&quot;&gt;Back&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-ua&quot;&gt;Назад&lt;/span&gt;\r\n                                &lt;span class=&quot;lang-block lang-pl&quot;&gt;Powrót&lt;/span&gt;\r\n                            &lt;/a&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/form&gt;\r\n                &lt;/div&gt;\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center&quot;&gt;\r\n                &lt;div class=&quot;password-sidebar-logo&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; alt=&quot;Logo&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script&gt;\r\n$(document).on(\'ajaxComplete\', function(e, xhr, settings) {\r\n    if (settings.url.indexOf(\'route=account/password\') !== -1) {\r\n        try {\r\n            const res = JSON.parse(xhr.responseText);\r\n            $(\'.alert-garage\').fadeOut(100);\r\n            $(\'.text-danger\').empty();\r\n\r\n            if (res.error) {\r\n                if (res.error.warning) $(\'#alert-error\').fadeIn();\r\n                if (res.error.password) $(\'#error-password\').html(res.error.password);\r\n                if (res.error.confirm) $(\'#error-confirm\').html(res.error.confirm);\r\n            }\r\n            if (res.success) {\r\n                $(\'#alert-success\').fadeIn();\r\n                // Опционально: очистить поля после успеха\r\n                $(\'#input-password, #input-confirm\').val(\'\');\r\n            }\r\n            if (res.redirect) {\r\n                location = res.redirect;\r\n            }\r\n        } catch (err) {}\r\n    }\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 10:36:56'),
(16, 0, 'account/payment_method', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СТРУКТУРА */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-payment-method {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n        min-height: 75vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 35px;\r\n        font-size: 1.6rem;\r\n    }\r\n\r\n    /* 3. КОНТЕНТНАЯ КАРТОЧКА */\r\n    .payment-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 40px;\r\n        border-top: 3px solid #ff0000;\r\n    }\r\n\r\n    /* Таблица методов (если они есть) */\r\n    .table-garage {\r\n        width: 100%;\r\n        color: #ccc;\r\n        border-collapse: collapse;\r\n    }\r\n\r\n    .table-garage td {\r\n        padding: 15px;\r\n        border-bottom: 1px solid #222;\r\n    }\r\n\r\n    /* 4. КНОПКИ */\r\n    .buttons {\r\n        margin-top: 30px;\r\n    }\r\n\r\n    .btn-back-custom {\r\n        background: transparent !important;\r\n        border: 2px solid #333 !important;\r\n        color: #666 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        font-size: 13px;\r\n        text-decoration: none !important;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .btn-back-custom i { margin-right: 10px; }\r\n\r\n    .btn-back-custom:hover {\r\n        border-color: #fff !important;\r\n        background-color: #fff !important;\r\n        color: #000 !important;\r\n        transform: translateY(-2px);\r\n    }\r\n\r\n    /* 5. ЛОГОТИП СПРАВА */\r\n    .payment-sidebar-logo {\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        height: 100%;\r\n        padding-left: 40px;\r\n    }\r\n\r\n    .payment-sidebar-logo img {\r\n        max-width: 100%;\r\n        filter: drop-shadow(0 0 15px rgba(255, 0, 0, 0.2));\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .payment-sidebar-logo img:hover {\r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 0.5));\r\n        transform: scale(1.03);\r\n    }\r\n\r\n    .lang-block { display: none !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-payment-method&quot; class=&quot;container&quot;&gt;\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7 col-md-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Payment Methods&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Способи оплати&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Metody płatności&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;payment-card&quot;&gt;\r\n                    {% if payment_methods %}\r\n                        &lt;div class=&quot;table-responsive&quot;&gt;\r\n                            &lt;table class=&quot;table-garage&quot;&gt;\r\n                                &lt;tbody&gt;\r\n                                {% for payment_method in payment_methods %}\r\n                                    &lt;tr&gt;\r\n                                        &lt;td&gt;&lt;b&gt;{{ payment_method.name }}&lt;/b&gt;&lt;/td&gt;\r\n                                        &lt;td class=&quot;text-end&quot;&gt;&lt;a href=&quot;{{ payment_method.delete }}&quot; class=&quot;btn btn-danger&quot; style=&quot;border-radius:0;&quot;&gt;&lt;i class=&quot;fa-solid fa-trash-can&quot;&gt;&lt;/i&gt;&lt;/a&gt;&lt;/td&gt;\r\n                                    &lt;/tr&gt;\r\n                                {% endfor %}\r\n                                &lt;/tbody&gt;\r\n                            &lt;/table&gt;\r\n                        &lt;/div&gt;\r\n                    {% else %}\r\n                        &lt;p style=&quot;color:#666; font-style: italic; margin-bottom: 0;&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;You have no saved payment methods.&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;У вас немає збережених способів оплати.&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Nie masz zapisanych metod płatności.&lt;/span&gt;\r\n                        &lt;/p&gt;\r\n                    {% endif %}\r\n                &lt;/div&gt;\r\n\r\n                &lt;div class=&quot;buttons&quot;&gt;\r\n                    &lt;a href=&quot;{{ back }}&quot; class=&quot;btn-back-custom&quot;&gt;\r\n                        &lt;i class=&quot;fa-solid fa-arrow-left&quot;&gt;&lt;/i&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;Back&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;Назад&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Powrót&lt;/span&gt;\r\n                    &lt;/a&gt;\r\n                &lt;/div&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center&quot;&gt;\r\n                &lt;div class=&quot;payment-sidebar-logo&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; alt=&quot;Logo&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 10:38:57');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(17, 0, 'account/address', '{{ header }}\r\n&lt;div style=&quot;background: #222; padding: 10px; border: 1px solid red; margin-bottom: 20px;&quot;&gt;\r\n    &lt;p&gt;Debug Info:&lt;/p&gt;\r\n    &lt;ul&gt;\r\n        &lt;li&gt;Addresses Count: {{ addresses|length }}&lt;/li&gt;\r\n        &lt;li&gt;Current Customer ID: {{ customer_id|default(\'Unknown\') }}&lt;/li&gt;\r\n    &lt;/ul&gt;\r\n&lt;/div&gt;\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ ФОН И СТРУКТУРА */\r\n    main {\r\n        display: block;\r\n        position: relative;\r\n        z-index: 1;\r\n        background-color: #0d0d0d;\r\n    }\r\n\r\n    #account-address {\r\n        background-color: #0d0d0d !important;\r\n        color: #eee !important;\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n        min-height: 75vh;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    /* 2. ЗАГОЛОВОК */\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 35px;\r\n        font-size: 1.6rem;\r\n    }\r\n\r\n    /* 3. КАРТОЧКИ АДРЕСОВ */\r\n    .address-card {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        padding: 25px;\r\n        margin-bottom: 20px;\r\n        border-top: 2px solid #333;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .address-card:hover {\r\n        border-top-color: #ff0000;\r\n        background: #151515;\r\n    }\r\n\r\n    .address-text {\r\n        color: #ccc;\r\n        font-size: 14px;\r\n        line-height: 1.6;\r\n        margin-bottom: 20px;\r\n    }\r\n\r\n    /* 4. КНОПКИ УПРАВЛЕНИЯ */\r\n    .address-actions {\r\n        display: flex;\r\n        gap: 10px;\r\n    }\r\n\r\n    .btn-edit-garage {\r\n        background: #333 !important;\r\n        color: #fff !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 8px 20px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 10px;\r\n        text-transform: uppercase;\r\n        text-decoration: none !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-edit-garage:hover {\r\n        background: #ff0000 !important;\r\n    }\r\n\r\n    .btn-delete-garage {\r\n        background: transparent !important;\r\n        color: #666 !important;\r\n        border: 1px solid #333 !important;\r\n        border-radius: 0 !important;\r\n        padding: 8px 15px !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-delete-garage:hover {\r\n        color: #ff0000 !important;\r\n        border-color: #ff0000 !important;\r\n    }\r\n\r\n    /* 5. НИЖНИЕ КНОПКИ */\r\n    .buttons-nav {\r\n        margin-top: 30px;\r\n        display: flex;\r\n        justify-content: space-between;\r\n        align-items: center;\r\n    }\r\n\r\n    .btn-primary-garage {\r\n        background-color: #ff0000 !important;\r\n        border: none !important;\r\n        border-radius: 0 !important;\r\n        padding: 15px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 900;\r\n        color: #fff !important;\r\n        text-decoration: none !important;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-primary-garage:hover {\r\n        background-color: #fff !important;\r\n        color: #ff0000 !important;\r\n    }\r\n\r\n    .btn-back-custom {\r\n        background: transparent !important;\r\n        border: 2px solid #333 !important;\r\n        color: #666 !important;\r\n        border-radius: 0 !important;\r\n        padding: 14px 35px !important;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-weight: 700;\r\n        font-size: 13px;\r\n        text-decoration: none !important;\r\n        display: inline-flex;\r\n        align-items: center;\r\n        transition: 0.3s all ease;\r\n    }\r\n\r\n    .btn-back-custom:hover {\r\n        border-color: #fff !important;\r\n        background-color: #fff !important;\r\n        color: #000 !important;\r\n    }\r\n\r\n    /* 6. ЛОГОТИП */\r\n    .address-sidebar-logo img {\r\n        max-width: 100%;\r\n        filter: drop-shadow(0 0 15px rgba(255, 0, 0, 0.2));\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .address-sidebar-logo img:hover {\r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 0.5));\r\n        transform: scale(1.03);\r\n    }\r\n\r\n    .lang-block { display: none !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-address&quot; class=&quot;container&quot;&gt;\r\n        {% if success %}\r\n          &lt;div class=&quot;alert alert-success alert-dismissible&quot; style=&quot;background:#111; border-left:4px solid #28a745; border-radius:0; color:#fff; padding: 20px;&quot;&gt;\r\n              &lt;i class=&quot;fa-solid fa-circle-check&quot; style=&quot;color:#28a745; margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n              {# ПРОВЕРЯЕМ ТЕКСТ И ПОДМЕНЯЕМ ЕГО #}\r\n              {% if \'successfully added\' in success or \'dodany\' in success or \'успішно додано\' in success %}\r\n                  &lt;span class=&quot;lang-block lang-en&quot;&gt;Your address has been successfully added!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-ua&quot;&gt;Вашу адресу успішно додано!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twój adres został pomyślnie dodany!&lt;/span&gt;\r\n              {% elseif \'successfully updated\' in success or \'zaktualizowany\' in success or \'успішно оновлено\' in success %}\r\n                  &lt;span class=&quot;lang-block lang-en&quot;&gt;Your address has been successfully updated!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-ua&quot;&gt;Вашу адресу успішно оновлено!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twój adres został pomyślnie zaktualizowany!&lt;/span&gt;\r\n              {% elseif \'successfully deleted\' in success or \'usunięty\' in success or \'успішно видалено\' in success %}\r\n                  &lt;span class=&quot;lang-block lang-en&quot;&gt;Your address has been successfully deleted!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-ua&quot;&gt;Вашу адресу успішно видалено!&lt;/span&gt;\r\n                  &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twój adres został pomyślnie usunięty!&lt;/span&gt;\r\n              {% else %}\r\n                  {{ success }}\r\n              {% endif %}\r\n              &lt;button type=&quot;button&quot; class=&quot;btn-close btn-close-white&quot; data-bs-dismiss=&quot;alert&quot;&gt;&lt;/button&gt;\r\n          &lt;/div&gt;\r\n        {% endif %}\r\n        {% if error_warning %}\r\n            &lt;div class=&quot;alert alert-danger&quot; style=&quot;background:#ff0000; border:none; border-radius:0; color:#fff;&quot;&gt;\r\n                &lt;i class=&quot;fa-solid fa-triangle-exclamation&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt; {{ error_warning }}\r\n            &lt;/div&gt;\r\n        {% endif %}\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7 col-md-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Address Book Entries&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Адресна книга&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Książka adresowa&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                {% if addresses %}\r\n                    {% for address in addresses %}\r\n                        &lt;div class=&quot;address-card&quot;&gt;\r\n                            &lt;div class=&quot;address-text&quot;&gt;{{ address.address }}&lt;/div&gt;\r\n                            &lt;div class=&quot;address-actions&quot;&gt;\r\n                                &lt;a href=&quot;{{ address.update }}&quot; class=&quot;btn-edit-garage&quot;&gt;\r\n                                    &lt;span class=&quot;lang-block lang-en&quot;&gt;Edit&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Редагувати&lt;/span&gt;\r\n                                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Edytuj&lt;/span&gt;\r\n                                &lt;/a&gt;\r\n                                &lt;a href=&quot;{{ address.delete }}&quot; class=&quot;btn-delete-garage&quot; onclick=&quot;return confirm(\'{{ text_confirm }}\');&quot;&gt;\r\n                                    &lt;i class=&quot;fa-solid fa-trash-can&quot;&gt;&lt;/i&gt;\r\n                                &lt;/a&gt;\r\n                            &lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                    {% endfor %}\r\n                {% else %}\r\n                    &lt;p style=&quot;color:#666; font-style: italic;&quot;&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;Your address book is empty.&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;Ваша адресна книга порожня.&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Twoja książka adresowa jest pusta.&lt;/span&gt;\r\n                    &lt;/p&gt;\r\n                {% endif %}\r\n\r\n                &lt;div class=&quot;buttons-nav&quot;&gt;\r\n                    &lt;a href=&quot;{{ back }}&quot; class=&quot;btn-back-custom&quot;&gt;\r\n                        &lt;i class=&quot;fa-solid fa-arrow-left&quot; style=&quot;margin-right:10px;&quot;&gt;&lt;/i&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;Back&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;Назад&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Powrót&lt;/span&gt;\r\n                    &lt;/a&gt;\r\n                    &lt;a href=&quot;{{ add }}&quot; class=&quot;btn-primary-garage&quot;&gt;\r\n                        &lt;span class=&quot;lang-block lang-en&quot;&gt;New Address&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;Нова адреса&lt;/span&gt;\r\n                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Nowy adres&lt;/span&gt;\r\n                    &lt;/a&gt;\r\n                &lt;/div&gt;\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center&quot;&gt;\r\n                &lt;div class=&quot;address-sidebar-logo&quot; style=&quot;padding-left:40px;&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; alt=&quot;Logo Garage&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 11:38:08'),
(18, 0, 'account/address_form', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    main { display: block; position: relative; z-index: 1; background-color: #0d0d0d; }\r\n    #account-address-form { background-color: #0d0d0d !important; color: #eee !important; padding-top: 40px; padding-bottom: 80px; min-height: 75vh; }\r\n    .breadcrumb { display: none !important; }\r\n    h1 { font-family: \'Orbitron\', sans-serif; text-transform: uppercase; border-left: 5px solid #ff0000; padding-left: 20px; color: #fff; margin-bottom: 35px; font-size: 1.6rem; }\r\n    .address-form-card { background: #111; border: 1px solid #222; padding: 40px; border-top: 3px solid #ff0000; }\r\n    .form-group { margin-bottom: 20px; }\r\n\r\n    .form-label { color: #888; text-transform: uppercase; font-size: 11px; letter-spacing: 1px; margin-bottom: 8px; display: block; }\r\n    .form-control, .form-select { background-color: #1a1a1a !important; border: 1px solid #333 !important; color: #fff !important; border-radius: 0 !important; padding: 12px 15px !important; }\r\n    .form-control:focus, .form-select:focus { border-color: #ff0000 !important; outline: none; }\r\n    \r\n    .text-danger { color: #ff0000 !important; font-size: 10px; text-transform: uppercase; margin-top: 5px; display: block; }\r\n\r\n    .buttons-nav { margin-top: 30px; display: flex; justify-content: space-between; align-items: center; }\r\n    .btn-primary-garage { background-color: #ff0000 !important; border: none !important; padding: 15px 35px !important; font-family: \'Orbitron\', sans-serif; text-transform: uppercase; font-weight: 900; color: #fff !important; cursor: pointer; transition: 0.3s ease; width: 100%; }\r\n    .btn-primary-garage:hover { background-color: #fff !important; color: #ff0000 !important; box-shadow: 0 0 20px rgba(255, 255, 255, 0.2); }\r\n    \r\n    .address-sidebar-logo img { \r\n        max-width: 100%; \r\n        filter: drop-shadow(0 0 5px rgba(255, 0, 0, 0.1)); \r\n        transition: all 0.5s ease; \r\n    }\r\n    .address-sidebar-logo img:hover { \r\n        filter: drop-shadow(0 0 25px rgba(255, 0, 0, 1)) !important; \r\n        transform: scale(1.05); \r\n    }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-address-form&quot; class=&quot;container&quot;&gt;\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-lg-7&quot;&gt;\r\n                {{ content_top }}\r\n                &lt;h1&gt;FORMULARZ ADRESU&lt;/h1&gt;\r\n\r\n                &lt;div class=&quot;address-form-card&quot;&gt;\r\n                    {# Убрали все лишние атрибуты, оставили только ID и action #}\r\n                    &lt;form action=&quot;{{ save }}&quot; method=&quot;post&quot; id=&quot;form-garage-final&quot;&gt;\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Imię&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;firstname&quot; value=&quot;{{ firstname }}&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-firstname&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Nazwisko&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;lastname&quot; value=&quot;{{ lastname }}&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-lastname&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Firma&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;company&quot; value=&quot;{{ company }}&quot; class=&quot;form-control&quot; /&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Adres&lt;/label&gt;\r\n                            &lt;input type=&quot;text&quot; name=&quot;address_1&quot; value=&quot;{{ address_1 }}&quot; class=&quot;form-control&quot; /&gt;\r\n                            &lt;div id=&quot;error-address-1&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;row&quot;&gt;\r\n                            &lt;div class=&quot;col-sm-6&quot;&gt;\r\n                                &lt;div class=&quot;form-group&quot;&gt;\r\n                                    &lt;label class=&quot;form-label&quot;&gt;Miasto&lt;/label&gt;\r\n                                    &lt;input type=&quot;text&quot; name=&quot;city&quot; value=&quot;{{ city }}&quot; class=&quot;form-control&quot; /&gt;\r\n                                    &lt;div id=&quot;error-city&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                                &lt;/div&gt;\r\n                            &lt;/div&gt;\r\n                            &lt;div class=&quot;col-sm-6&quot;&gt;\r\n                                &lt;div class=&quot;form-group&quot;&gt;\r\n                                    &lt;label class=&quot;form-label&quot;&gt;Kod pocztowy&lt;/label&gt;\r\n                                    &lt;input type=&quot;text&quot; name=&quot;postcode&quot; value=&quot;{{ postcode }}&quot; class=&quot;form-control&quot; /&gt;\r\n                                    &lt;div id=&quot;error-postcode&quot; class=&quot;text-danger&quot;&gt;&lt;/div&gt;\r\n                                &lt;/div&gt;\r\n                            &lt;/div&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Kraj&lt;/label&gt;\r\n                            &lt;select name=&quot;country_id&quot; id=&quot;input-country&quot; class=&quot;form-select&quot;&gt;\r\n                                &lt;option value=&quot;&quot;&gt; --- &lt;/option&gt;\r\n                                {% for country in countries %}\r\n                                    &lt;option value=&quot;{{ country.country_id }}&quot; {% if country.country_id == country_id %}selected{% endif %}&gt;{{ country.name }}&lt;/option&gt;\r\n                                {% endfor %}\r\n                            &lt;/select&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;form-group&quot;&gt;\r\n                            &lt;label class=&quot;form-label&quot;&gt;Województwo&lt;/label&gt;\r\n                            &lt;select name=&quot;zone_id&quot; id=&quot;input-zone&quot; class=&quot;form-select&quot;&gt;\r\n                                &lt;option value=&quot;&quot;&gt; --- &lt;/option&gt;\r\n                            &lt;/select&gt;\r\n                        &lt;/div&gt;\r\n\r\n                        &lt;div class=&quot;buttons-nav&quot;&gt;\r\n                            {# Кнопка теперь просто кнопка, без типа submit внутри формы, чтобы избежать конфликтов #}\r\n                            &lt;button type=&quot;button&quot; id=&quot;btn-save-manual&quot; class=&quot;btn-primary-garage&quot;&gt;ZAPISZ ADRES&lt;/button&gt;\r\n                        &lt;/div&gt;\r\n                    &lt;/form&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n\r\n            &lt;div class=&quot;col-lg-5 d-none d-lg-flex align-items-center justify-content-center&quot;&gt;\r\n                &lt;div class=&quot;address-sidebar-logo&quot;&gt;\r\n                    &lt;img src=&quot;http://localhost/myshop/image/catalog/лого кар2.png&quot; alt=&quot;Garage Logo&quot;&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script type=&quot;text/javascript&quot;&gt;\r\ndocument.addEventListener(\'DOMContentLoaded\', function() {\r\n    const countryEl = document.getElementById(\'input-country\');\r\n    const zoneEl = document.getElementById(\'input-zone\');\r\n    const saveBtn = document.getElementById(\'btn-save-manual\');\r\n    const formEl = document.getElementById(\'form-garage-final\');\r\n\r\n    // 1. Загрузка зон\r\n    function loadZones(cid) {\r\n        fetch(\'index.php?route=localisation/country&amp;country_id=\' + cid)\r\n            .then(r =&gt; r.json())\r\n            .then(json =&gt; {\r\n                let html = \'&lt;option value=&quot;&quot;&gt; --- &lt;/option&gt;\';\r\n                if (json.zone) {\r\n                    json.zone.forEach(z =&gt; {\r\n                        html += `&lt;option value=&quot;${z.zone_id}&quot; ${z.zone_id == \'{{ zone_id }}\' ? \'selected\' : \'\'}&gt;${z.name}&lt;/option&gt;`;\r\n                    });\r\n                }\r\n                zoneEl.innerHTML = html;\r\n            });\r\n    }\r\n\r\n    countryEl.addEventListener(\'change\', function() { loadZones(this.value); });\r\n    if (countryEl.value) loadZones(countryEl.value);\r\n\r\n    // 2. РУЧНОЕ СОХРАНЕНИЕ ПО КЛИКУ\r\n    saveBtn.addEventListener(\'click\', function() {\r\n        console.log(&quot;Клик зафиксирован!&quot;);\r\n        saveBtn.disabled = true;\r\n        saveBtn.innerText = &quot;ЗАГРУЗКА...&quot;;\r\n\r\n        const data = new FormData(formEl);\r\n\r\n        fetch(formEl.action, {\r\n            method: \'POST\',\r\n            body: data\r\n        })\r\n        .then(response =&gt; response.json())\r\n        .then(json =&gt; {\r\n            console.log(&quot;Ответ сервера:&quot;, json);\r\n            \r\n            // Чистим старые ошибки\r\n            document.querySelectorAll(\'.text-danger\').forEach(e =&gt; e.innerText = \'\');\r\n\r\n            if (json.error) {\r\n                saveBtn.disabled = false;\r\n                saveBtn.innerText = &quot;ZAPISZ ADRES&quot;;\r\n                for (let i in json.error) {\r\n                    let errBox = document.getElementById(\'error-\' + i.replace(\'_\', \'-\'));\r\n                    if (errBox) errBox.innerText = json.error[i];\r\n                }\r\n            }\r\n\r\n            if (json.redirect) {\r\n                window.location.href = json.redirect;\r\n            }\r\n        })\r\n        .catch(err =&gt; {\r\n            console.error(&quot;Ошибка:&quot;, err);\r\n            saveBtn.disabled = false;\r\n            saveBtn.innerText = &quot;ZAPISZ ADRES&quot;;\r\n        });\r\n    });\r\n});\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 12:56:44'),
(19, 0, 'account/wishlist', '{{ header }}\r\n\r\n&lt;style&gt;\r\n    /* 1. ОБЩАЯ СТИЛИСТИКА */\r\n    main {\r\n        display: block;\r\n        background-color: #0d0d0d;\r\n        min-height: 100vh;\r\n        color: #eee;\r\n    }\r\n\r\n    #account-wishlist {\r\n        padding-top: 40px;\r\n        padding-bottom: 80px;\r\n    }\r\n\r\n    .breadcrumb { display: none !important; }\r\n\r\n    h1 {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        border-left: 5px solid #ff0000;\r\n        padding-left: 20px;\r\n        color: #fff;\r\n        margin-bottom: 40px;\r\n        font-size: 1.8rem;\r\n    }\r\n\r\n    /* 2. СЕТКА ТОВАРОВ */\r\n    .wishlist-grid {\r\n        display: grid;\r\n        grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));\r\n        gap: 25px;\r\n    }\r\n\r\n    .wishlist-item {\r\n        background: #111;\r\n        border: 1px solid #222;\r\n        position: relative;\r\n        transition: 0.3s all ease;\r\n        display: flex;\r\n        flex-direction: column;\r\n        border-bottom: 3px solid #333;\r\n    }\r\n\r\n    .wishlist-item:hover {\r\n        border-color: #ff0000;\r\n        transform: translateY(-5px);\r\n        box-shadow: 0 10px 30px rgba(255, 0, 0, 0.15);\r\n        border-bottom: 3px solid #ff0000;\r\n    }\r\n\r\n    /* 3. ИЗОБРАЖЕНИЕ */\r\n    .wishlist-image {\r\n        position: relative;\r\n        padding: 20px;\r\n        background: #161616;\r\n        text-align: center;\r\n        overflow: hidden;\r\n    }\r\n\r\n    .wishlist-image img {\r\n        max-width: 100%;\r\n        height: 200px;\r\n        object-fit: contain;\r\n        transition: 0.5s ease;\r\n    }\r\n\r\n    .wishlist-item:hover .wishlist-image img {\r\n        transform: scale(1.1);\r\n        filter: drop-shadow(0 0 10px rgba(255, 0, 0, 0.3));\r\n    }\r\n\r\n    /* 4. ИНФОРМАЦИЯ */\r\n    .wishlist-info {\r\n        padding: 20px;\r\n        flex-grow: 1;\r\n        display: flex;\r\n        flex-direction: column;\r\n    }\r\n\r\n    .wishlist-name {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 14px;\r\n        text-transform: uppercase;\r\n        margin-bottom: 10px;\r\n        height: 40px;\r\n        overflow: hidden;\r\n    }\r\n\r\n    .wishlist-name a {\r\n        color: #fff;\r\n        text-decoration: none;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .wishlist-name a:hover { color: #ff0000; }\r\n\r\n    .wishlist-model {\r\n        color: #666;\r\n        font-size: 11px;\r\n        text-transform: uppercase;\r\n        letter-spacing: 1px;\r\n        margin-bottom: 15px;\r\n    }\r\n\r\n    .wishlist-price {\r\n        font-family: \'Orbitron\', sans-serif;\r\n        font-size: 18px;\r\n        color: #ff0000;\r\n        font-weight: 900;\r\n        margin-top: auto;\r\n    }\r\n\r\n    /* 5. КНОПКИ */\r\n    .wishlist-actions {\r\n        display: flex;\r\n        border-top: 1px solid #222;\r\n    }\r\n\r\n    .btn-add-cart {\r\n        flex-grow: 1;\r\n        background: #ff0000;\r\n        color: #fff;\r\n        border: none;\r\n        padding: 15px;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        font-size: 12px;\r\n        font-weight: 700;\r\n        cursor: pointer;\r\n        transition: 0.3s;\r\n        display: flex;\r\n        align-items: center;\r\n        justify-content: center;\r\n        gap: 8px;\r\n    }\r\n\r\n    .btn-add-cart:hover {\r\n        background: #fff;\r\n        color: #ff0000;\r\n    }\r\n\r\n    .btn-remove-wish {\r\n        background: #1a1a1a;\r\n        color: #444;\r\n        border: none;\r\n        padding: 15px 20px;\r\n        cursor: pointer;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-remove-wish:hover {\r\n        color: #ff0000;\r\n        background: #222;\r\n    }\r\n\r\n    /* ПУСТОЙ СПИСОК */\r\n    .wishlist-empty {\r\n        text-align: center;\r\n        padding: 100px 0;\r\n        background: #111;\r\n        border: 1px dashed #333;\r\n    }\r\n\r\n    .wishlist-empty i {\r\n        font-size: 50px;\r\n        color: #333;\r\n        margin-bottom: 20px;\r\n    }\r\n\r\n    .btn-back-garage {\r\n        display: inline-block;\r\n        margin-top: 20px;\r\n        padding: 15px 40px;\r\n        border: 2px solid #ff0000;\r\n        color: #fff;\r\n        text-decoration: none;\r\n        font-family: \'Orbitron\', sans-serif;\r\n        text-transform: uppercase;\r\n        transition: 0.3s;\r\n    }\r\n\r\n    .btn-back-garage:hover {\r\n        background: #ff0000;\r\n    }\r\n\r\n    /* ЛОГИКА ПЕРЕВОДА */\r\n    .lang-block { display: none !important; }\r\n&lt;/style&gt;\r\n\r\n&lt;main&gt;\r\n    &lt;div id=&quot;account-wishlist&quot; class=&quot;container&quot;&gt;\r\n        {% if success %}\r\n            &lt;div class=&quot;alert alert-success alert-dismissible&quot;&gt;&lt;i class=&quot;fa-solid fa-circle-check&quot;&gt;&lt;/i&gt; {{ success }} &lt;button type=&quot;button&quot; class=&quot;btn-close&quot; data-bs-dismiss=&quot;alert&quot;&gt;&lt;/button&gt;&lt;/div&gt;\r\n        {% endif %}\r\n\r\n        &lt;div class=&quot;row&quot;&gt;\r\n            &lt;div id=&quot;content&quot; class=&quot;col-12&quot;&gt;\r\n                {{ content_top }}\r\n                \r\n                &lt;h1&gt;\r\n                    &lt;span class=&quot;lang-block lang-en&quot;&gt;My Wish List&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-ua&quot;&gt;Список бажань&lt;/span&gt;\r\n                    &lt;span class=&quot;lang-block lang-pl&quot;&gt;Lista życzeń&lt;/span&gt;\r\n                &lt;/h1&gt;\r\n\r\n                {% if products %}\r\n                    &lt;div class=&quot;wishlist-grid&quot;&gt;\r\n                        {% for product in products %}\r\n                            &lt;div class=&quot;wishlist-item&quot;&gt;\r\n                                &lt;div class=&quot;wishlist-image&quot;&gt;\r\n                                    &lt;a href=&quot;{{ product.href }}&quot;&gt;&lt;img src=&quot;{{ product.thumb }}&quot; alt=&quot;{{ product.name }}&quot; title=&quot;{{ product.name }}&quot;&gt;&lt;/a&gt;\r\n                                &lt;/div&gt;\r\n                                \r\n                                &lt;div class=&quot;wishlist-info&quot;&gt;\r\n                                    &lt;div class=&quot;wishlist-model&quot;&gt;{{ product.model }}&lt;/div&gt;\r\n                                    &lt;div class=&quot;wishlist-name&quot;&gt;\r\n                                        &lt;a href=&quot;{{ product.href }}&quot;&gt;{{ product.name }}&lt;/a&gt;\r\n                                    &lt;/div&gt;\r\n                                    \r\n                                    &lt;div class=&quot;wishlist-price&quot;&gt;\r\n                                        {% if product.price %}\r\n                                            {% if not product.special %}\r\n                                                {{ product.price }}\r\n                                            {% else %}\r\n                                                &lt;span style=&quot;text-decoration: line-through; color: #666; font-size: 14px; margin-right: 10px;&quot;&gt;{{ product.price }}&lt;/span&gt; {{ product.special }}\r\n                                            {% endif %}\r\n                                        {% endif %}\r\n                                    &lt;/div&gt;\r\n                                &lt;/div&gt;\r\n\r\n                                &lt;div class=&quot;wishlist-actions&quot;&gt;\r\n                                    &lt;button type=&quot;button&quot; onclick=&quot;cart.add(\'{{ product.product_id }}\');&quot; class=&quot;btn-add-cart&quot;&gt;\r\n                                        &lt;i class=&quot;fa-solid fa-cart-shopping&quot;&gt;&lt;/i&gt;\r\n                                        &lt;span class=&quot;lang-block lang-en&quot;&gt;Add to Cart&lt;/span&gt;\r\n                                        &lt;span class=&quot;lang-block lang-ua&quot;&gt;В кошик&lt;/span&gt;\r\n                                        &lt;span class=&quot;lang-block lang-pl&quot;&gt;Do koszyka&lt;/span&gt;\r\n                                    &lt;/button&gt;\r\n                                    \r\n                                    &lt;a href=&quot;{{ product.remove }}&quot; class=&quot;btn-remove-wish&quot; title=&quot;{{ button_remove }}&quot;&gt;\r\n                                        &lt;i class=&quot;fa-solid fa-trash-can&quot;&gt;&lt;/i&gt;\r\n                                    &lt;/a&gt;\r\n                                &lt;/div&gt;\r\n                            &lt;/div&gt;\r\n                        {% endfor %}\r\n                    &lt;/div&gt;\r\n                {% else %}\r\n                    &lt;div class=&quot;wishlist-empty&quot;&gt;\r\n                        &lt;i class=&quot;fa-solid fa-heart-crack&quot;&gt;&lt;/i&gt;\r\n                        &lt;p class=&quot;lang-block lang-en&quot;&gt;Your wish list is empty.&lt;/p&gt;\r\n                        &lt;p class=&quot;lang-block lang-ua&quot;&gt;Ваш список бажань порожній.&lt;/p&gt;\r\n                        &lt;p class=&quot;lang-block lang-pl&quot;&gt;Twoja lista życzeń jest pusta.&lt;/p&gt;\r\n                        &lt;a href=&quot;{{ continue }}&quot; class=&quot;btn-back-garage&quot;&gt;\r\n                            &lt;span class=&quot;lang-block lang-en&quot;&gt;Continue&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-ua&quot;&gt;Продовжити&lt;/span&gt;\r\n                            &lt;span class=&quot;lang-block lang-pl&quot;&gt;Kontynuuj&lt;/span&gt;\r\n                        &lt;/a&gt;\r\n                    &lt;/div&gt;\r\n                {% endif %}\r\n\r\n                {{ content_bottom }}\r\n            &lt;/div&gt;\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/main&gt;\r\n\r\n&lt;script&gt;\r\n(function() {\r\n    function refreshWishLang() {\r\n        const activeLang = document.body.getAttribute(\'data-lang\') || \'en\';\r\n        document.querySelectorAll(\'.lang-block\').forEach(el =&gt; el.style.setProperty(\'display\', \'none\', \'important\'));\r\n        document.querySelectorAll(\'.lang-\' + activeLang).forEach(el =&gt; {\r\n            const displayType = (el.tagName === \'SPAN\') ? \'inline-block\' : \'block\';\r\n            el.style.setProperty(\'display\', displayType, \'important\');\r\n        });\r\n    }\r\n    refreshWishLang();\r\n    // Повтор для AJAX подгрузок\r\n    setTimeout(refreshWishLang, 300);\r\n})();\r\n&lt;/script&gt;\r\n\r\n{{ footer }}', 1, '2026-02-24 15:00:34'),
(20, 0, 'product/product', '{{ header }}\r\n&lt;style&gt;\r\n    /* 1. ГЛОБАЛЬНЫЙ СТИЛЬ */\r\n    #product-info { background: #0a0a0a; color: #fff; padding-top: 40px; font-family: \'Orbitron\', sans-serif; min-height: 100vh; }\r\n    .breadcrumb, .breadcrumb-item { display: none !important; }\r\n\r\n    /* 2. СКАНЕР ИЗОБРАЖЕНИЙ */\r\n    .product-image-scanner { border: 1px solid #222; background: #000; padding: 15px; position: relative; }\r\n    .product-image-scanner::before {\r\n        content: &quot;LIVE_DATA_FEED&quot;; position: absolute; top: 10px; left: 15px;\r\n        color: #ff0000; font-size: 9px; letter-spacing: 2px; animation: blink 2s infinite;\r\n    }\r\n    .img-main-wrap img { width: 100%; height: auto; object-fit: contain; }\r\n\r\n    /* 3. ИНФО-ПАНЕЛЬ */\r\n    .product-info-panel { padding-left: 30px; }\r\n    h1 { font-size: 32px; font-weight: 900; text-transform: uppercase; letter-spacing: 2px; margin-bottom: 25px; border-left: 4px solid #ff0000; padding-left: 20px; }\r\n    .tech-list { list-style: none; padding: 0; margin-bottom: 30px; }\r\n    .tech-list li { font-size: 11px; color: #888; margin-bottom: 12px; text-transform: uppercase; display: flex; justify-content: space-between; border-bottom: 1px solid #1a1a1a; padding-bottom: 5px; }\r\n    .tech-list b { color: #fff; }\r\n\r\n    /* ПЕРЕВОДЫ ЛЕЙБЛОВ */\r\n    .label-model::after { content: &quot;MODEL:&quot;; }\r\n    .label-stock::after { content: &quot;AVAILABILITY:&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .label-model::after { content: &quot;MODEL:&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .label-stock::after { content: &quot;DOSTĘPNOŚĆ:&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .label-model::after { content: &quot;МОДЕЛЬ:&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .label-stock::after { content: &quot;НАЯВНІСТЬ:&quot;; }\r\n\r\n    /* 4. ЦЕНА */\r\n    .price-gauge { background: #111; border: 1px solid #222; padding: 25px; margin-bottom: 35px; position: relative; }\r\n    .price-gauge::after { content: &quot;&quot;; position: absolute; top: 0; left: 0; width: 4px; height: 100%; background: #ff0000; }\r\n    .price-new { color: #ff0000; font-size: 42px; font-weight: 900; }\r\n\r\n    /* 5. СЛОТЫ ВРЕМЕНИ */\r\n    .booking-options { margin-bottom: 30px; background: #000; border: 1px solid #1a1a1a; padding: 20px; }\r\n    .option-label { color: #ff0000; font-size: 10px; letter-spacing: 2px; margin-bottom: 10px; display: block; text-transform: uppercase; }\r\n    input[type=&quot;date&quot;] { background: #111; border: 1px solid #333; color: #fff; padding: 10px; width: 100%; font-family: \'Orbitron\'; margin-bottom: 20px; outline: none; }\r\n    .time-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(80px, 1fr)); gap: 10px; }\r\n    .time-slot { position: relative; }\r\n    .time-slot input { position: absolute; opacity: 0; cursor: pointer; }\r\n    .time-slot label { display: block; background: #111; border: 1px solid #222; color: #666; padding: 10px 5px; text-align: center; font-size: 12px; cursor: pointer; transition: 0.3s; }\r\n    .time-slot input:checked + label { border-color: #ff0000; color: #fff; box-shadow: inset 0 0 10px rgba(255,0,0,0.3); background: rgba(255,0,0,0.05); }\r\n    .slot-disabled { opacity: 0.1; pointer-events: none; filter: grayscale(1); }\r\n\r\n    /* 6. КНОПКИ */\r\n    .qty-wrap { display: flex; gap: 10px; margin-bottom: 20px; }\r\n    #input-quantity { background: #000; border: 1px solid #333; color: #fff; width: 70px; text-align: center; font-family: \'Orbitron\'; }\r\n    .btn-start-engine { flex-grow: 1; background: #ff0000; color: #000 !important; border: none; font-weight: 900; text-transform: uppercase; letter-spacing: 1px; transition: 0.3s; display: flex; align-items: center; justify-content: center; gap: 10px; padding: 15px; font-size: 16px; cursor: pointer; }\r\n    .btn-start-engine:hover { background: #fff; transform: translateY(-3px); box-shadow: 0 5px 15px rgba(255,0,0,0.4); }\r\n\r\n    .btn-book-text::after { content: &quot;BOOK TIME&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .btn-book-text::after { content: &quot;ZAREZERWUJ CZAS&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .btn-book-text::after { content: &quot;ЗАБРОНЮВАТИ ЧАС&quot;; }\r\n\r\n    .btn-wish-garage { background: transparent; border: 1px solid #333; color: #888; padding: 12px 20px; font-size: 10px; font-family: \'Orbitron\', sans-serif; letter-spacing: 2px; transition: 0.4s; cursor: pointer; width: 100%; display: flex; align-items: center; justify-content: center; gap: 10px; margin-top: 10px; }\r\n    .btn-wish-garage.active { color: #ff0000; border-color: #ff0000; }\r\n\r\n    .label-wishlist::after { content: &quot;ADD TO FAVORITES&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .label-wishlist::after { content: &quot;DODAJ DO ULUBIONYCH&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .label-wishlist::after { content: &quot;ДОДАТИ В УЛЮБЛЕНЕ&quot;; }\r\n\r\n    .description-title::after { content: &quot;DESCRIPTION&quot;; }\r\n    body[data-lang=&quot;pl&quot;] .description-title::after { content: &quot;OPIS&quot;; }\r\n    body[data-lang=&quot;ua&quot;] .description-title::after { content: &quot;ОПИС&quot;; }\r\n    .description-content { color: #ccc; line-height: 1.8; font-size: 14px; margin-top: 20px; }\r\n\r\n    @keyframes blink { 0% {opacity: 1;} 50% {opacity: 0.2;} 100% {opacity: 1;} }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;product-info&quot; class=&quot;container&quot;&gt;\r\n    &lt;div id=&quot;alert&quot;&gt;&lt;/div&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        &lt;div id=&quot;content&quot; class=&quot;col&quot;&gt;\r\n            {{ content_top }}\r\n            &lt;div class=&quot;row&quot;&gt;\r\n                &lt;div class=&quot;col-lg-6&quot;&gt;\r\n                    &lt;div class=&quot;product-image-scanner magnific-popup text-center&quot;&gt;\r\n                        {% if thumb %}&lt;a href=&quot;{{ popup }}&quot;&gt;&lt;img src=&quot;{{ thumb }}&quot; class=&quot;img-fluid&quot; /&gt;&lt;/a&gt;{% endif %}\r\n                    &lt;/div&gt;\r\n                &lt;/div&gt;\r\n                &lt;div class=&quot;col-lg-6&quot;&gt;\r\n                    &lt;div class=&quot;product-info-panel&quot;&gt;\r\n                        &lt;h1&gt;{{ heading_title }}&lt;/h1&gt;\r\n                        &lt;ul class=&quot;tech-list&quot;&gt;\r\n                            &lt;li&gt;&lt;span class=&quot;label-model&quot;&gt;&lt;/span&gt; &lt;b&gt;{{ model }}&lt;/b&gt;&lt;/li&gt;\r\n                            &lt;li&gt;&lt;span class=&quot;label-stock&quot;&gt;&lt;/span&gt; &lt;b style=&quot;color:#00ff00;&quot;&gt;{{ stock }}&lt;/b&gt;&lt;/li&gt;\r\n                        &lt;/ul&gt;\r\n                        {% if price %}\r\n                        &lt;div class=&quot;price-gauge&quot;&gt;\r\n                            &lt;span style=&quot;font-size: 9px; color: #444; position: absolute; top: 10px; right: 15px;&quot;&gt;CORE_V_PRICE&lt;/span&gt;\r\n                            &lt;div class=&quot;price-new&quot;&gt;{{ special ? special : price }}&lt;/div&gt;\r\n                        &lt;/div&gt;\r\n                        {% endif %}\r\n\r\n                        &lt;form id=&quot;form-product&quot;&gt;\r\n                            &lt;div class=&quot;booking-options&quot;&gt;\r\n                                {% if options %}\r\n                                    {% for option in options %}\r\n                                        {% if option.type == \'date\' %}\r\n                                            &lt;label class=&quot;option-label&quot;&gt;{{ option.name }}&lt;/label&gt;\r\n                                            &lt;input type=&quot;date&quot; name=&quot;option[{{ option.product_option_id }}]&quot; value=&quot;{{ option.value }}&quot; class=&quot;form-control date-picker-trigger&quot; required /&gt;\r\n                                        {% endif %}\r\n                                        {% if option.type == \'radio\' %}\r\n                                            &lt;label class=&quot;option-label&quot;&gt;{{ option.name }}&lt;/label&gt;\r\n                                            &lt;div class=&quot;time-grid&quot;&gt;\r\n                                                {% for option_value in option.product_option_value %}\r\n                                                    &lt;div class=&quot;time-slot&quot; data-time=&quot;{{ option_value.name }}&quot;&gt;\r\n                                                        &lt;input type=&quot;radio&quot; name=&quot;option[{{ option.product_option_id }}]&quot; value=&quot;{{ option_value.product_option_value_id }}&quot; id=&quot;opt-{{ option_value.product_option_value_id }}&quot; /&gt;\r\n                                                        &lt;label for=&quot;opt-{{ option_value.product_option_value_id }}&quot;&gt;{{ option_value.name }}&lt;/label&gt;\r\n                                                    &lt;/div&gt;\r\n                                                {% endfor %}\r\n                                            &lt;/div&gt;\r\n                                        {% endif %}\r\n                                    {% endfor %}\r\n                                {% endif %}\r\n                            &lt;/div&gt;\r\n                            &lt;div class=&quot;qty-wrap&quot;&gt;\r\n                                &lt;input type=&quot;number&quot; name=&quot;quantity&quot; value=&quot;{{ minimum }}&quot; id=&quot;input-quantity&quot; class=&quot;form-control&quot; /&gt;\r\n                                &lt;input type=&quot;hidden&quot; name=&quot;product_id&quot; value=&quot;{{ product_id }}&quot;/&gt;\r\n                                \r\n                                &lt;button type=&quot;button&quot; onclick=&quot;executeBooking()&quot; class=&quot;btn-start-engine&quot;&gt;\r\n                                    &lt;i class=&quot;fa-solid fa-calendar-check&quot;&gt;&lt;/i&gt; &lt;span class=&quot;btn-book-text&quot;&gt;&lt;/span&gt;\r\n                                &lt;/button&gt;\r\n                            &lt;/div&gt;\r\n                            &lt;button type=&quot;button&quot; onclick=&quot;executeWishlist()&quot; class=&quot;btn-wish-garage&quot; data-id=&quot;{{ product_id }}&quot;&gt;\r\n                                &lt;i class=&quot;fa-regular fa-heart&quot;&gt;&lt;/i&gt; &lt;span class=&quot;label-wishlist&quot;&gt;&lt;/span&gt;\r\n                            &lt;/button&gt;\r\n                        &lt;/form&gt;\r\n                    &lt;/div&gt;\r\n                &lt;/div&gt;\r\n            &lt;/div&gt;\r\n            &lt;div class=&quot;description-section&quot;&gt;\r\n                &lt;span class=&quot;description-title&quot; style=&quot;color: #ff0000; font-weight: 900; letter-spacing: 3px; border-bottom: 1px solid #222; display: block; padding-bottom: 10px; margin-top: 40px;&quot;&gt;&lt;/span&gt;\r\n                &lt;div class=&quot;description-content&quot;&gt;{{ description }}&lt;/div&gt;\r\n            &lt;/div&gt;\r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script type=&quot;text/javascript&quot;&gt;\r\n// 1. ГЛОБАЛЬНАЯ ФУНКЦИЯ БРОНИРОВАНИЯ\r\nfunction executeBooking() {\r\n    console.log(\'--- Нажатие кнопки БРОНИРОВАТЬ ---\');\r\n    const $btn = $(\'.btn-start-engine\');\r\n    \r\n    $.ajax({\r\n        url: \'index.php?route=checkout/cart|add&amp;language={{ language }}\',\r\n        type: \'post\',\r\n        data: $(\'#form-product\').serialize(),\r\n        dataType: \'json\',\r\n        beforeSend: function() {\r\n            $btn.prop(\'disabled\', true).css(\'opacity\', \'0.5\');\r\n            $(\'.text-danger, .alert\').remove();\r\n        },\r\n        complete: function() {\r\n            $btn.prop(\'disabled\', false).css(\'opacity\', \'1\');\r\n        },\r\n        success: function(json) {\r\n            console.log(\'Ответ сервера:\', json);\r\n\r\n            if (json[\'error\']) {\r\n                if (json[\'error\'][\'option\']) {\r\n                    for (i in json[\'error\'][\'option\']) {\r\n                        $(\'.booking-options\').prepend(\'&lt;div class=&quot;text-danger&quot; style=&quot;color:#ff0000; font-size:11px; margin-bottom:5px;&quot;&gt;⚠️ \' + json[\'error\'][\'option\'][i] + \'&lt;/div&gt;\');\r\n                    }\r\n                }\r\n                if (json[\'error\'][\'warning\']) {\r\n                    $(\'#alert\').prepend(\'&lt;div class=&quot;alert alert-danger alert-dismissible&quot;&gt;\' + json[\'error\'][\'warning\'] + \'&lt;button type=&quot;button&quot; class=&quot;btn-close&quot; data-bs-dismiss=&quot;alert&quot;&gt;&lt;/button&gt;&lt;/div&gt;\');\r\n                }\r\n            }\r\n\r\n            if (json[\'success\']) {\r\n                // Обновляем корзину в шапке\r\n                $(\'#cart\').load(\'index.php?route=common/cart|info\');\r\n                \r\n                // Показываем уведомление\r\n                if (typeof showGarageToast === \'function\') {\r\n                    showGarageToast(false, \'SYSTEM\', json[\'success\']);\r\n                } else {\r\n                    alert(json[\'success\']);\r\n                }\r\n            }\r\n        },\r\n        error: function(xhr, ajaxOptions, thrownError) {\r\n            console.error(\'Ошибка AJAX:\', thrownError);\r\n            alert(\'Ошибка выполнения запроса. Проверьте консоль F12.\');\r\n        }\r\n    });\r\n}\r\n\r\n// 2. ГЛОБАЛЬНАЯ ФУНКЦИЯ ИЗБРАННОГО\r\nfunction executeWishlist() {\r\n    console.log(\'--- Нажатие кнопки ИЗБРАННОЕ ---\');\r\n    const product_id = \'{{ product_id }}\';\r\n\r\n    $.ajax({\r\n        url: \'index.php?route=account/wishlist|add&amp;language={{ language }}\',\r\n        type: \'post\',\r\n        data: \'product_id=\' + product_id,\r\n        dataType: \'json\',\r\n        success: function(json) {\r\n            if (json[\'success\']) {\r\n                $(\'.btn-wish-garage\').addClass(\'active\').find(\'i\').attr(\'class\', \'fa-solid fa-heart\');\r\n                if (typeof showGarageToast === \'function\') showGarageToast(false, \'GARAGE\', json[\'success\']);\r\n            }\r\n        }\r\n    });\r\n}\r\n\r\n$(document).ready(function() {\r\n    // ЛОГИКА КАЛЕНДАРЯ\r\n    $(document).on(\'change\', \'.date-picker-trigger\', function() {\r\n        const dateVal = $(this).val();\r\n        if (!dateVal) return;\r\n        \r\n        const date = new Date(dateVal);\r\n        const day = date.getDay();\r\n        \r\n        $(\'.time-slot\').removeClass(\'slot-disabled\').find(\'input\').prop(\'checked\', false);\r\n        \r\n        if (day === 0) { // Воскресенье\r\n            $(\'.time-slot\').addClass(\'slot-disabled\');\r\n            alert(&quot;НЕДІЛЯ - ВИХІДНИЙ / SUNDAY - CLOSED&quot;);\r\n        } else if (day === 6) { // Суббота (9:00 - 13:00)\r\n            $(\'.time-slot\').each(function() {\r\n                const timeStr = $(this).data(\'time\');\r\n                const hour = parseInt(timeStr);\r\n                if (hour &lt; 9 || hour &gt;= 13) $(this).addClass(\'slot-disabled\');\r\n            });\r\n        } else { // Будни (8:00 - 18:00)\r\n            $(\'.time-slot\').each(function() {\r\n                const timeStr = $(this).data(\'time\');\r\n                const hour = parseInt(timeStr);\r\n                if (hour &lt; 8 || hour &gt;= 18) $(this).addClass(\'slot-disabled\');\r\n            });\r\n        }\r\n    });\r\n});\r\n&lt;/script&gt;\r\n{{ footer }}', 1, '2026-02-25 22:28:19');
INSERT INTO `oc_theme` (`theme_id`, `store_id`, `route`, `code`, `status`, `date_added`) VALUES
(21, 0, 'checkout/cart', '{{ header }}\r\n&lt;style&gt;\r\n    #checkout-cart {\r\n        background: #0a0a0a; color: #fff; padding: 40px 0;\r\n        font-family: \'Orbitron\', sans-serif; min-height: 100vh;\r\n    }\r\n    .breadcrumb { display: none !important; }\r\n    \r\n    h1 {\r\n        font-size: 28px; font-weight: 900; text-transform: uppercase;\r\n        border-left: 5px solid #ff0000; padding-left: 20px; margin-bottom: 40px;\r\n    }\r\n\r\n    /* Стили для VIN-блока, который мы добавим в список */\r\n    .vin-container {\r\n        margin-top: 30px; background: #0f0f0f; border-left: 4px solid #00ff00;\r\n        padding: 25px; display: none; /* Покажем через JS если есть услуги */\r\n    }\r\n    .vin-label { color: #ff0000; font-size: 10px; letter-spacing: 2px; margin-bottom: 15px; display: block; }\r\n    .vin-input {\r\n        background: #000; border: 1px solid #333; color: #00ff00; width: 100%;\r\n        padding: 15px; font-family: \'Consolas\', monospace; font-size: 18px; outline: none;\r\n    }\r\n    .vin-input:focus { border-color: #00ff00; }\r\n&lt;/style&gt;\r\n\r\n&lt;div id=&quot;checkout-cart&quot; class=&quot;container&quot;&gt;\r\n    &lt;div id=&quot;alert&quot;&gt;&lt;/div&gt;\r\n    &lt;div class=&quot;row&quot;&gt;\r\n        &lt;div id=&quot;content&quot; class=&quot;col&quot;&gt;\r\n            {{ content_top }}\r\n            &lt;h1&gt;{{ heading_title }}&lt;/h1&gt;\r\n            \r\n            {# Сюда подгружается список товаров #}\r\n            &lt;div id=&quot;shopping-cart&quot;&gt;{{ list }}&lt;/div&gt;\r\n            \r\n            {{ content_bottom }}\r\n        &lt;/div&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script type=&quot;text/javascript&quot;&gt;&lt;/script&gt;\r\n{{ footer }}', 1, '2026-02-25 20:38:26'),
(22, 0, 'checkout/cart_list', '{% if products %}\r\n&lt;style&gt;\r\n    /* СТИЛИ ТАБЛИЦЫ */\r\n    #output-cart { background: #000; border: 1px solid #222; padding: 10px; }\r\n    .table { color: #fff !important; border-color: #1a1a1a !important; margin-bottom: 0; }\r\n    .table thead th { \r\n        color: #ff0000; font-family: \'Orbitron\'; font-size: 10px; \r\n        text-transform: uppercase; letter-spacing: 2px; border-bottom: 2px solid #ff0000;\r\n        padding: 15px 10px;\r\n    }\r\n    .table tbody td { vertical-align: middle; border-color: #111 !important; background: #000 !important; color: #fff !important; }\r\n    \r\n    /* ИЗОБРАЖЕНИЕ */\r\n    .img-thumbnail { background: #050505; border: 1px solid #333; padding: 2px; width: 60px; }\r\n    \r\n    /* ИНПУТ КОЛИЧЕСТВА */\r\n    .cart-qty-input { \r\n        background: #000 !important; border: 1px solid #333 !important; \r\n        color: #fff !important; text-align: center; font-family: \'Orbitron\';\r\n    }\r\n    \r\n    /* VIN БЛОК */\r\n    .vin-order-wrap {\r\n        background: #0a0a0a; border-left: 4px solid #00ff00; padding: 20px;\r\n        margin-top: 30px; border-top: 1px solid #1a1a1a;\r\n    }\r\n    .vin-title { color: #00ff00; font-family: \'Orbitron\'; font-size: 11px; letter-spacing: 1px; margin-bottom: 10px; display: block; }\r\n    .vin-field { \r\n        background: #000; border: 1px solid #333; color: #00ff00; width: 100%; padding: 12px; \r\n        font-family: \'Consolas\', monospace; font-size: 16px; text-transform: uppercase;\r\n    }\r\n\r\n    /* КНОПКИ */\r\n    .btn-update-cart { background: #222; border: none; color: #fff; }\r\n    .btn-update-cart:hover { background: #ff0000; }\r\n    .btn-remove-cart { background: transparent; border: none; color: #444; font-size: 18px; }\r\n    .btn-remove-cart:hover { color: #ff0000; }\r\n    \r\n    .btn-action-checkout { \r\n        background: #ff0000; color: #000 !important; font-weight: 900; \r\n        font-family: \'Orbitron\'; border: none; padding: 15px 30px; text-transform: uppercase;\r\n    }\r\n&lt;/style&gt;\r\n\r\n{# ПРОВЕРЯЕМ ЕСТЬ ЛИ УСЛУГИ (ID 60) #}\r\n{% set has_service = false %}\r\n{% for product in products %}\r\n    {% if \'path=60\' in product.href %}{% set has_service = true %}{% endif %}\r\n{% endfor %}\r\n\r\n&lt;div id=&quot;output-cart&quot; class=&quot;table-responsive&quot;&gt;\r\n    &lt;table class=&quot;table&quot;&gt;\r\n        &lt;thead&gt;\r\n            &lt;tr&gt;\r\n                &lt;th class=&quot;text-center&quot; style=&quot;width: 80px;&quot;&gt;SCAN&lt;/th&gt;\r\n                &lt;th class=&quot;text-start&quot;&gt;\r\n                    {% if has_service %}\r\n                        &lt;span data-lang-ua=&quot;ПОСЛУГА / ДІАГНОСТИКА&quot; data-lang-pl=&quot;USŁUGA / DIAGNOSTYKA&quot; data-lang-en=&quot;SERVICE / DIAGNOSTICS&quot;&gt;&lt;/span&gt;\r\n                    {% else %}\r\n                        {{ column_name }}\r\n                    {% endif %}\r\n                &lt;/th&gt;\r\n                &lt;th class=&quot;text-center&quot; style=&quot;width: 150px;&quot;&gt;{{ column_quantity }}&lt;/th&gt;\r\n                &lt;th class=&quot;text-end&quot;&gt;\r\n                    {% if has_service %}\r\n                        &lt;span data-lang-ua=&quot;ВАРТІСТЬ&quot; data-lang-pl=&quot;KOSZT&quot; data-lang-en=&quot;COST&quot;&gt;&lt;/span&gt;\r\n                    {% else %}\r\n                        {{ column_price }}\r\n                    {% endif %}\r\n                &lt;/th&gt;\r\n                &lt;th class=&quot;text-end&quot;&gt;{{ column_total }}&lt;/th&gt;\r\n            &lt;/tr&gt;\r\n        &lt;/thead&gt;\r\n        &lt;tbody&gt;\r\n            {% for product in products %}\r\n                &lt;tr&gt;\r\n                    &lt;td class=&quot;text-center&quot;&gt;\r\n                        {% if product.thumb %}\r\n                            &lt;img src=&quot;{{ product.thumb }}&quot; alt=&quot;{{ product.name }}&quot; class=&quot;img-thumbnail&quot;/&gt;\r\n                        {% endif %}\r\n                    &lt;/td&gt;\r\n                    &lt;td class=&quot;text-start&quot;&gt;\r\n                        &lt;a href=&quot;{{ product.href }}&quot; style=&quot;color: #fff; text-decoration: none; font-weight: 700; font-size: 15px;&quot;&gt;{{ product.name }}&lt;/a&gt;\r\n                        &lt;div class=&quot;small text-muted&quot; style=&quot;font-size: 10px;&quot;&gt;{{ text_model }}: {{ product.model }}&lt;/div&gt;\r\n                        {% for option in product.option %}\r\n                            &lt;div class=&quot;small&quot; style=&quot;color: #ff0000;&quot;&gt;• {{ option.name }}: {{ option.value }}&lt;/div&gt;\r\n                        {% endfor %}\r\n                    &lt;/td&gt;\r\n                    &lt;td&gt;\r\n                        &lt;form method=&quot;post&quot; data-oc-target=&quot;#shopping-cart&quot;&gt;\r\n                            &lt;div class=&quot;input-group input-group-sm&quot;&gt;\r\n                                &lt;input type=&quot;text&quot; name=&quot;quantity&quot; value=&quot;{{ product.quantity }}&quot; class=&quot;form-control cart-qty-input&quot;/&gt;\r\n                                &lt;input type=&quot;hidden&quot; name=&quot;key&quot; value=&quot;{{ product.cart_id }}&quot;/&gt;\r\n                                &lt;button type=&quot;submit&quot; formaction=&quot;{{ edit }}&quot; class=&quot;btn btn-update-cart&quot;&gt;&lt;i class=&quot;fa-solid fa-rotate&quot;&gt;&lt;/i&gt;&lt;/button&gt;\r\n                                &lt;a href=&quot;{{ product.remove }}&quot; class=&quot;btn-remove-cart ml-2&quot;&gt;&lt;i class=&quot;fa-solid fa-circle-xmark&quot;&gt;&lt;/i&gt;&lt;/a&gt;\r\n                            &lt;/div&gt;\r\n                        &lt;/form&gt;\r\n                    &lt;/td&gt;\r\n                    &lt;td class=&quot;text-end&quot;&gt;{{ product.price }}&lt;/td&gt;\r\n                    &lt;td class=&quot;text-end&quot; style=&quot;color: #ff0000; font-weight: 700;&quot;&gt;{{ product.total }}&lt;/td&gt;\r\n                &lt;/tr&gt;\r\n            {% endfor %}\r\n        &lt;/tbody&gt;\r\n        &lt;tfoot&gt;\r\n            {% for total in totals %}\r\n                &lt;tr&gt;\r\n                    &lt;td colspan=&quot;4&quot; class=&quot;text-end&quot; style=&quot;border: none; padding: 5px;&quot;&gt;\r\n                        &lt;span style=&quot;color: #888; font-size: 11px; text-transform: uppercase;&quot;&gt;{{ total.title }}&lt;/span&gt;\r\n                    &lt;/td&gt;\r\n                    &lt;td class=&quot;text-end&quot; style=&quot;border: none; padding: 5px; font-weight: 900; font-size: {{ loop.last ? \'22px\' : \'16px\' }}; color: {{ loop.last ? \'#ff0000\' : \'#fff\' }};&quot;&gt;\r\n                        {{ total.text }}\r\n                    &lt;/td&gt;\r\n                &lt;/tr&gt;\r\n            {% endfor %}\r\n        &lt;/tfoot&gt;\r\n    &lt;/table&gt;\r\n&lt;/div&gt;\r\n\r\n{# VIN-БЛОК: ПОКАЗЫВАЕМ ТОЛЬКО ДЛЯ УСЛУГ #}\r\n{% if has_service %}\r\n&lt;div class=&quot;vin-order-wrap&quot;&gt;\r\n    &lt;label class=&quot;vin-title&quot;&gt;\r\n        &lt;span data-lang-ua=&quot;ВВЕДІТЬ VIN-КОД АБО ДЕРЖНОМЕР АВТО&quot; data-lang-pl=&quot;WPISZ NUMER VIN LUB REJESTRACYJNY&quot; data-lang-en=&quot;ENTER VIN OR LICENSE PLATE&quot;&gt;&lt;/span&gt;\r\n    &lt;/label&gt;\r\n    &lt;input type=&quot;text&quot; name=&quot;comment&quot; class=&quot;vin-field&quot; placeholder=&quot;XTA210700...&quot; maxlength=&quot;17&quot;&gt;\r\n    &lt;div style=&quot;font-size: 8px; color: #444; margin-top: 8px; font-family: \'Orbitron\';&quot;&gt;AUTO_RECOGNITION_SYSTEM: ACTIVE&lt;/div&gt;\r\n&lt;/div&gt;\r\n{% endif %}\r\n\r\n&lt;div class=&quot;row mt-4 mb-5&quot;&gt;\r\n    &lt;div class=&quot;col&quot;&gt;&lt;a href=&quot;{{ continue }}&quot; class=&quot;btn btn-outline-secondary btn-sm&quot; style=&quot;font-family: \'Orbitron\'; font-size: 10px;&quot;&gt;← BACK TO SHOP&lt;/a&gt;&lt;/div&gt;\r\n    &lt;div class=&quot;col text-end&quot;&gt;\r\n        &lt;a href=&quot;{{ checkout }}&quot; class=&quot;btn-action-checkout&quot;&gt;\r\n             &lt;span data-lang-ua=&quot;ПІДТВЕРДИТИ ЗАПИС&quot; data-lang-pl=&quot;POTWIERDŹ ZAPIS&quot; data-lang-en=&quot;CONFIRM BOOKING&quot;&gt;&lt;/span&gt; →\r\n        &lt;/a&gt;\r\n    &lt;/div&gt;\r\n&lt;/div&gt;\r\n\r\n&lt;script&gt;\r\n$(document).ready(function() {\r\n    function applyCartLang() {\r\n        const lang = document.body.getAttribute(\'data-lang\') || \'ua\';\r\n        $(\'[data-lang-\' + lang + \']\').each(function() {\r\n            $(this).text($(this).attr(\'data-lang-\' + lang));\r\n        });\r\n    }\r\n    applyCartLang();\r\n});\r\n&lt;/script&gt;\r\n\r\n{% else %}\r\n  &lt;div class=&quot;text-center&quot; style=&quot;padding: 100px 0;&quot;&gt;\r\n    &lt;h1 style=&quot;color: #222;&quot;&gt;CART_EMPTY&lt;/h1&gt;\r\n    &lt;p style=&quot;color: #444;&quot;&gt;NO_DATA_FOUND&lt;/p&gt;\r\n    &lt;a href=&quot;{{ continue }}&quot; class=&quot;btn btn-primary&quot;&gt;RELOAD_SYSTEM&lt;/a&gt;\r\n  &lt;/div&gt;\r\n{% endif %}', 1, '2026-02-25 20:42:48');

